  "top-pair": { pl: "najwyższa para", en: "top pair", enAlt: [], def: "Para z najwyższą kartą na stole, np. K♠ Q♦ na flopie K-7-2.", area: "board", forms: ["najwyższa para","najwyższej pary","najwyższą parę","najwyższą parą","najwyższej parze","najwyższe pary","najwyższych par","najwyższymi parami"] },
