/** Definicje w językach innych niż polski (D-335): content/<język>/terms-def.yaml, klucz terminu → definicja. */
export const TERM_DEFS: Readonly<Partial<Record<string, Readonly<Record<string, string>>>>> = {
  "de": {"royal-flush":"Die höchste Hand im Poker: Ass, König, Dame, Bube und Zehn in derselben Farbe, z. B. A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Fünf aufeinanderfolgende Karten in derselben Farbe, z. B. 5♥ 6♥ 7♥ 8♥ 9♥. Die höchste Variante (vom Ass bis zur Zehn) hat einen eigenen Namen und ist die stärkste Hand im Spiel.","four-of-a-kind":"Vier Karten desselben Rangs, z. B. vier Siebenen. Haben zwei Spieler einen Vierling desselben Rangs, gewinnt die höhere fünfte Karte (der Kicker).","full-house":"Ein Drilling und ein Paar in einer Hand, z. B. drei Damen und zwei Fünfen. Bei zwei Full Houses gewinnt der höhere Drilling.","flush":"Fünf Karten derselben Farbe (♠, ♥, ♦ oder ♣), die nicht aufeinanderfolgen. Bei zwei solchen Händen gewinnt die mit der höheren höchsten Karte, bei Gleichstand die mit der höheren nächsten Karte.","straight":"Fünf aufeinanderfolgende Karten, nicht alle in derselben Farbe, z. B. 5-6-7-8-9. Das Ass kann die höchste (A-K-Q-J-T) oder die niedrigste Karte (A-2-3-4-5) sein.","three-of-a-kind":"Drei Karten desselben Rangs und zwei andere. Im Hold'em gibt es zwei Varianten mit eigenen Namen: Set, wenn das Paar auf deiner Hand ist und die dritte Karte auf dem Board liegt, und Trips, wenn das Paar auf dem Board liegt und die dritte Karte auf deiner Hand ist.","set":"Ein Drilling aus einem Paar auf deiner Hand und einer Karte auf dem Board, z. B. 7♣ 7♦ auf einem Flop K-7-2.","two-pair":"Zwei verschiedene Paare und eine fünfte Karte, z. B. K-K-8-8-3. Bei Gleichstand entscheidet zuerst das höhere Paar, dann das niedrigere, zuletzt die fünfte Karte.","pair":"Zwei Karten desselben Rangs und drei andere, z. B. zwei Neunen. Schwächer ist nur High Card.","high-card":"Eine Hand ohne Paar oder bessere Kombination; über die Stärke entscheidet die höchste Karte, bei Gleichstand die nächsten.","kicker":"Die höchste Karte außerhalb der Kombination, die einen Gleichstand entscheidet. Beispiel: Ein Paar Asse mit König schlägt ein Paar Asse mit Dame.","wheel":"Die niedrigste Straße: A-2-3-4-5, bei der das Ass als niedrigste Karte zählt.","check":"Weiterspielen, ohne Chips zu setzen; nur möglich, wenn du nichts nachzahlen musst: In dieser Setzrunde hat noch niemand gesetzt (vor dem Flop kann das der Big Blind, wenn niemand erhöht hat). Nicht zu verwechseln mit Call, also dem Mitgehen beim Einsatz eines Gegners.","bet":"Das erste Setzen von Chips in einer Setzrunde, in der noch niemand gesetzt hat (im weiteren Sinn heißt jedes Setzen von Chips in den Pot Bet bzw. Einsatz).","call":"So viele Chips in den Pot legen, wie die Bet oder der Raise des Gegners beträgt, um weiterzuspielen. Nicht zu verwechseln mit Check, also Weiterspielen ohne Einsatz, wenn niemand gesetzt hat.","raise":"Erhöhen über den Einsatz des Gegners hinaus; die anderen müssen die Differenz nachlegen, erneut erhöhen oder folden. Auch „Erhöhung“ genannt.","fold":"Aufgeben der Hand: Du gibst deine Karten ab und verlierst, was du schon in den Pot gelegt hast.","check-raise":"Du checkst zuerst und erhöhst, wenn der Gegner setzt, in derselben Setzrunde.","all-in":"Setzen aller deiner Chips. Von jedem Gegner kannst du dann höchstens so viel gewinnen, wie du selbst eingesetzt hast; um den Rest wird in einem Side Pot gespielt.","pot":"Alle Chips, die in der laufenden Hand gesetzt wurden. Sie gehen an den Spieler mit der besten Hand im Showdown (bei Side Pots wird um jeden Pot einzeln gespielt) oder an den Spieler, bei dem alle anderen gefoldet haben.","side-pot":"Ein separater Pot, der entsteht, wenn jemand all-in ist: Um ihn spielen nur Spieler, die mehr eingesetzt haben als der All-in-Spieler, deshalb kann dieser ihn nicht gewinnen.","split-pot":"Eine Situation, in der sich Spieler mit gleich starken Händen den Pot teilen, z. B. wenn beide dieselbe Straße spielen, die auf dem Board liegt.","playing-the-board":"Eine Situation, in der deine beste Fünf-Karten-Hand nur aus Gemeinschaftskarten besteht; deine Hole Cards bringen nichts, also teilst du den Pot bestenfalls.","board":"Die offenen Gemeinschaftskarten in der Mitte (Flop, Turn, River), die alle Spieler nutzen. Gemeint sind die Karten, nicht der Tisch, an dem gespielt wird (am Tisch, Finaltisch).","community-cards":"Karten, die offen in die Mitte gelegt werden und die jeder Spieler für seine Hand nutzen kann; im Hold'em sind es fünf.","hole-cards":"Die zwei verdeckten Karten, die du im Hold'em zu Beginn einer Hand bekommst; nur du siehst sie.","small-blind":"Der kleinere Pflichteinsatz, den vor dem Austeilen der Spieler links vom Button zahlt (bei zwei Spielern der Button selbst); so heißt auch dieser Platz am Tisch.","big-blind":"Der größere Pflichteinsatz, den vor dem Austeilen der zweite Spieler links vom Button zahlt (bei zwei Spielern der Spieler gegenüber dem Button); so heißt auch dieser Platz. Er dient auch als Einheit für Stackgrößen und Ergebnisse.","chips":"Die Scheiben, mit denen am Tisch gespielt wird; im Cash Game stehen sie für Geld, im Turnier für Turnierpunkte.","stack":"Alle Chips, die ein Spieler vor sich hat; meist in Big Blinds angegeben (z. B. 100 Big Blinds).","street":"Jargon für eine Setzrunde: Preflop, Flop, Turn und River sind die vier Streets. Beispiel: „Value auf drei Streets“ bedeutet Value Bets auf Flop, Turn und River.","betting-round":"Ein Abschnitt der Hand, in dem die Spieler nacheinander checken, setzen, callen, erhöhen oder folden; im Hold'em gibt es vier: Preflop, Flop, Turn und River.","preflop":"Die erste Setzrunde: nach dem Austeilen der Hole Cards, bevor der Flop kommt.","flop":"Die ersten drei Gemeinschaftskarten, die nach der Preflop-Setzrunde gleichzeitig aufgedeckt werden; so heißt auch die zweite Setzrunde.","turn":"Die vierte Gemeinschaftskarte und die dritte Setzrunde.","river":"Die fünfte und letzte Gemeinschaftskarte und die letzte Setzrunde vor dem Showdown.","showdown":"Das Aufdecken der Karten nach der letzten Setzrunde, wenn noch mindestens zwei Spieler in der Hand sind; die beste Hand gewinnt den Pot.","position":"Der Platz am Tisch relativ zum Button, der die Reihenfolge der Aktionen festlegt. Wer später handelt, sieht vor seiner Entscheidung mehr Aktionen der Gegner.","in-position":"Die Lage eines Spielers, der nach dem Flop als Letzter handelt und so vor seiner Entscheidung die Aktion des Gegners sieht.","out-of-position":"Die Lage eines Spielers, der nach dem Flop vor dem Gegner handelt und so entscheidet, ohne dessen Aktion zu kennen.","early-position":"Die ersten Plätze, die vor dem Flop handeln (z. B. UTG); nach dir kommen noch viele Spieler.","late-position":"Die Plätze, die als Letzte handeln: der Button und die Plätze direkt davor, vor allem der Cutoff.","utg":"Der erste Spieler, der vor dem Flop handelt; er sitzt direkt links vom Big Blind.","hijack":"Der Platz direkt vor dem Cutoff, also der zweite rechts vom Button.","cutoff":"Der Platz direkt rechts vom Button, der unmittelbar vor ihm handelt.","button":"Der Platz des Gebers, markiert mit einer „Dealer“-Scheibe. Nach dem Flop handelt er in jeder Setzrunde als Letzter.","outs":"Eine Karte, die noch im Deck ist und deine Hand verbessert, meist indem sie einen Draw vervollständigt. Beispiel: Bei einem Flush-Draw sind deine Outs die übrigen Karten deiner Farbe.","draw":"Eine Hand, die noch keine starke Kombination ist, aber mit den nächsten Gemeinschaftskarten eine werden kann, z. B. wenn dir eine Karte zum Flush oder zur Straße fehlt.","flush-draw":"Vier Karten einer Farbe (auf der Hand und auf dem Board zusammen); dir fehlt eine zum Flush.","straight-draw":"Vier Karten, denen eine zur Straße fehlt. Varianten: OESD (eine Karte fehlt an einem der beiden Enden) und Gutshot (eine Karte fehlt in der Mitte).","oesd":"Abkürzung für open-ended straight draw: ein Straight-Draw aus vier aufeinanderfolgenden Karten, den eine Karte an einem der beiden Enden vervollständigt, z. B. 5-6-7-8 wartet auf eine Vier oder eine Neun.","gutshot":"Ein Straight-Draw, dem ein bestimmter Rang in der Mitte fehlt, z. B. 5-6-8-9 wartet nur auf eine Sieben.","backdoor":"Ein Draw auf dem Flop, der zwei passende Karten hintereinander braucht, auf Turn und River, z. B. drei Karten einer Farbe nach dem Flop.","pot-odds":"Das Verhältnis zwischen dem Betrag, den du zahlen musst, und dem Pot, den du gewinnen kannst (inklusive Einsatz des Gegners). Es zeigt, wie oft du gewinnen musst, damit sich ein Call lohnt.","implied-odds":"Pot Odds plus die Chips, die du auf späteren Streets zu gewinnen erwartest, wenn du deine Hand triffst.","equity":"Deine Chance, den Pot zu gewinnen, wenn alle restlichen Karten ohne weiteres Setzen ausgeteilt würden; meist in Prozent.","equity-realization":"Wie viel ihrer Equity eine Hand in Gewinn umwandelt, wenn weiter gesetzt wird (sie kann weniger oder mehr als ihre Equity realisieren); hängt u. a. von der Position ab und davon, wie leicht die Hand zu spielen ist.","expected-value":"Das durchschnittliche Ergebnis eines Spielzugs, wenn man ihn sehr oft wiederholen würde. Ein Spielzug, der im Schnitt ein Plus bringt, verdient langfristig, auch wenn er diesmal verliert.","combo":"Eine konkrete Zwei-Karten-Kombination mit Farben, z. B. A♠ K♥. Das Zählen solcher Kombinationen zeigt, wie viele Kombinationen einer bestimmten Hand wirklich in einer Range sind.","range":"Die Menge aller Hände, die ein Spieler in einer bestimmten Situation haben kann, oder der Hände, mit denen er einen bestimmten Spielzug machen würde.","mixed-hand":"Eine Hand, mit der die Gleichgewichtsstrategie mal den einen, mal den anderen Spielzug wählt (z. B. mal Raise, mal Call); beide Spielzüge sind korrekt. Man sagt auch, die Hand wird mit gemischter Strategie gespielt.","open":"Der erste Einstieg in den Pot vor dem Flop mit einem Raise, wenn alle vor dir gefoldet haben.","suited":"Zwei Hole Cards derselben Farbe, z. B. A♥ K♥ (Schreibweise AKs).","offsuit":"Zwei Hole Cards unterschiedlicher Farbe, z. B. A♥ K♣ (Schreibweise AKo).","pocket-pair":"Ein Paar aus deinen beiden Hole Cards, z. B. 8♣ 8♦ vor dem Flop.","connectors":"Hole Cards mit benachbarten Rängen, z. B. 8-7 oder 9-8; mit ihnen bildest du leichter eine Straße.","3-bet":"Die erste Erhöhung eines Opens vor dem Flop; der Name zählt den Big Blind als ersten Einsatz und das Open als zweiten.","4-bet":"Eine Erhöhung einer 3-Bet, also der vierte Einsatz in einer Setzrunde.","limp":"Einstieg in den Pot vor dem Flop, indem du nur den Big Blind callst, wenn noch niemand erhöht hat.","isolation":"Ein Raise nach einem oder mehreren Limps, um gegen den Limper (oft einen schwächeren Spieler) eins gegen eins zu spielen.","texture":"Der Charakter der Gemeinschaftskarten: wie viele Farben, ob die Karten nah beieinander liegen, ob ein Paar liegt. Davon hängt ab, welche Hände und Draws möglich sind.","dry":"Ein Board, auf dem wenige Draws und starke Hände möglich sind, z. B. K♠ 7♦ 2♣.","wet":"Ein Board, auf dem viele Draws und starke Hände möglich sind, z. B. J♥ T♥ 8♣.","rainbow":"Ein Flop mit drei Karten in drei verschiedenen Farben, sodass auf dem Flop niemand einen Flush-Draw hat.","two-tone":"Ein Flop, auf dem zwei Karten dieselbe Farbe haben, sodass Flush-Draws möglich sind.","monotone":"Ein Flop mit drei Karten derselben Farbe, sodass ein Flush schon fertig sein kann.","paired":"Ein Board, auf dem ein Paar liegt (zwei Karten desselben Rangs), z. B. 8-8-3.","connected":"Ein Board, auf dem jemand schon eine Straße haben kann, z. B. 9-8-7.","disconnected":"Ein Board mit weit auseinanderliegenden Karten, mit dem sich schwer eine Straße oder ein Straight-Draw bilden lässt, z. B. K-7-2.","semi-connected":"Ein Board mit Straight-Draws, auf dem aber noch keine Straße möglich ist, z. B. T-8-3 (Einteilung dieses Kurses).","wetness":"Wie stark ein Board Draws und starke Hände begünstigt: von trocken bis nass. Man spricht auch davon, wie koordiniert das Board ist.","top-pair":"Ein Paar mit der höchsten Karte auf dem Board, z. B. K♠ Q♦ auf einem Flop K-7-2.","second-pair":"Ein Paar mit der zweithöchsten Karte auf dem Board, z. B. 7♠ 6♠ auf einem Flop K-7-2.","overpair":"Ein Pocket Pair, das höher ist als jede Karte auf dem Board, z. B. Q-Q auf einem Flop J-7-2.","c-bet":"Continuation Bet: ein Einsatz des Spielers, der in der vorherigen Runde der Aggressor war, z. B. ein Einsatz auf dem Flop nach einem Open preflop.","aggressor":"Der Spieler, der in der vorherigen Setzrunde als Letzter gesetzt oder erhöht hat.","initiative":"Die Rolle des letzten Aggressors: Er macht meist den nächsten Einsatz.","range-advantage":"Eine Situation, in der die Range eines Spielers auf einem bestimmten Board insgesamt mehr Equity hat als die Range des Gegners.","nuts-advantage":"Eine Situation, in der ein Spieler anteilig mehr der stärksten Hände in seiner Range hat als der Gegner.","nuts":"Die stärkste mögliche Hand auf einem bestimmten Board zu einem bestimmten Zeitpunkt. Beispiel: Auf K♥ 9♥ 4♥ 2♣ ist es der Flush mit dem Herz-Ass.","polarized":"Über eine Range: besteht vor allem aus sehr starken Händen und Bluffs, fast ohne mittlere Hände.","polarization":"Aufbau einer Range aus den Extremen: starke Hände für Value und Bluffs, ohne mittlere Hände.","linear":"Über eine Range: von oben aufgebaut, von den stärksten Händen abwärts, ohne eigene Gruppe von Bluffs. Verwandt ist der Begriff „merged range“ (eine nicht polarisierte Range); laut veröffentlichten Solver-Analysen ist merged eine Zwischenform zwischen dieser und einer polarisierten Range.","condensed":"Über eine Range: ohne die stärksten Hände (nach oben begrenzt) und vor allem aus mittleren Händen; das Gegenteil von polarisiert.","value":"Setzen mit einer starken Hand, damit der Gegner mit einer schwächeren Hand callt.","value-bet":"Ein einzelner Einsatz auf Value: mit einer starken Hand, damit schwächere Hände ihn callen.","bluff":"Ein Einsatz mit einer schwachen Hand, die im Showdown kaum gewinnt, damit der Gegner eine bessere Hand foldet.","semi-bluff":"Ein Einsatz mit einer noch schwachen Hand, die sich aber verbessern kann (z. B. mit einem Draw): Du gewinnst, wenn der Gegner foldet oder wenn du triffst.","blocker":"Eine Karte auf deiner Hand, die die Chance senkt, dass der Gegner bestimmte Hände hat. Beispiel: Mit dem Herz-Ass kann der Gegner keinen Flush mit dem Herz-Ass haben.","bluff-catcher":"Eine Hand, die nur die Bluffs des Gegners schlägt und gegen seine Value Bets verliert.","barrel":"Ein weiterer Einsatz in der nächsten Setzrunde nach deinem eigenen Einsatz in der vorherigen Runde.","second-barrel":"Der zweite Einsatz in Folge: Nach einer C-Bet auf dem Flop setzt der Spieler auf dem Turn erneut.","probe-bet":"Ein Einsatz auf dem Turn vom Spieler out of Position, nachdem der Preflop-Aggressor auf dem Flop gecheckt hat, statt eine C-Bet zu machen.","donk-bet":"Ein Einsatz eines Spielers, der setzt, bevor der Aggressor der vorherigen Runde handeln konnte.","overbet":"Ein Einsatz nach dem Flop, der größer ist als der ganze Pot.","effective-stack":"In einer Hand zwischen zwei Spielern: der kleinere ihrer Stacks, also das Meiste, was realistisch gewonnen oder verloren werden kann. Bei mehreren Spielern wird er für jedes Paar einzeln berechnet.","spr":"Der effektive Stack geteilt durch den Pot zu Beginn einer Street (für den Plan der Hand wird er auf dem Flop berechnet); er zeigt, wie tief die Stacks im Verhältnis zum Pot sind (je niedriger der SPR, desto schneller landet alles im Pot).","mdf":"Der kleinste Teil deiner Range, den du gegen einen Einsatz verteidigen musst, damit ein Bluff des Gegners mit einer chancenlosen Hand nicht automatisch profitabel ist.","alpha":"Wie oft der Gegner folden muss, damit ein Bluff mit einer chancenlosen Hand auf null hinauskommt; hängt von der Einsatzgröße im Verhältnis zum Pot ab.","variance":"Die Streuung der Ergebnisse um den Erwartungswert: Selbst bei gutem Spiel können kurze Phasen deutlich im Minus oder im Plus liegen.","buy-in":"Der Betrag für den Einstieg in ein Turnier oder in ein Cash Game am Tisch.","bankroll":"Deine gesamte Reserve, die nur fürs Pokerspielen bestimmt ist; in dieser App in Buy-ins gezählt, nicht in Geld.","tilt":"Ein Zustand, in dem Emotionen (Wut, Frust, Euphorie) deine Entscheidungen am Tisch verschlechtern.","winrate":"Das durchschnittliche Ergebnis eines Spielers über eine längere Stichprobe; im Cash Game meist in bb/100, also Big Blinds pro hundert Hände.","downswing":"Eine Phase deutlich schlechterer Ergebnisse, meist größerer Verluste, als es dem Können entspräche; das Gegenteil eines Upswings.","session":"Eine Pokersitzung, vom Beginn bis zum Ende des Spiels.","stakes":"Die Höhe der Blinds im Cash Game oder des Buy-ins im Turnier; „Mikrolimits“ sind die niedrigsten Stufen.","standard-deviation":"Ein Maß für die Streuung der Ergebnisse (die Wurzel aus der Varianz); im Poker meist in bb/100 angegeben.","risk-of-ruin":"Die Wahrscheinlichkeit, dass du irgendwann deine ganze Bankroll verlierst, wenn du auf demselben Limit weiterspielst.","mental-game":"Die psychologische Seite des Pokers: der Umgang mit Tilt, Emotionen und Konzentration am Tisch.","tournament":"Eine Spielform, in der die Blinds in Abständen steigen und so lange gespielt wird, bis ein Spieler alle Chips hat; Preise bekommen die am besten Platzierten.","push-fold":"Eine vereinfachte Strategie für Short Stacks: Vor dem Flop gehst du entweder all-in oder foldest.","shove":"Ein All-in, meist als Raise vor dem Flop.","icm":"Ein Modell, das Turnierchips in Geldwert umrechnet und dabei die Auszahlungsstruktur und die Stacks aller Spieler berücksichtigt.","bubble":"Die Turnierphase kurz vor den bezahlten Plätzen, wenn bis zu den Preisen nur noch wenige Spieler ausscheiden müssen.","bubble-factor":"Eine Kennzahl aus dem ICM: wie viel mehr im Turnier der Verlust einer bestimmten Chipmenge schmerzt, als der Gewinn derselben Menge nützt.","cover":"Mindestens so viele Chips haben wie der Gegner. Wenn dich ein Gegner covert, beendet ein verlorenes All-in gegen ihn dein Turnier.","risk-premium":"Zusätzliche Equity über das hinaus, was die Pot Odds verlangen, die du im Turnier für ein All-in brauchst, weil ein Verlust mehr kostet, als ein Gewinn bringt.","m-ratio":"Dein Stack geteilt durch die Summe aus Blinds und Antes einer Hand: für wie viele volle Runden (Orbits) deine Chips ohne Spielen reichen.","red-zone":"Die Zone mit sehr niedrigem M: Es bleibt vor allem All-in oder Fold.","green-zone":"Die Zone mit hohem M: Dein Stack erlaubt freies Spiel, vorsichtig oder aggressiv.","ante":"Eine kleine Pflichtzahlung aller Spieler in den Pot vor dem Austeilen (vor allem in Turnieren).","bb-ante":"Ein Ante-Format, bei dem statt aller Spieler der Spieler im Big Blind das Ante für den ganzen Tisch zahlt.","fold-equity":"Der Teil des Werts eines Spielzugs, der daher kommt, dass der Gegner folden kann.","gap-concept":"Das Prinzip, dass du zum Callen eines Opens eine stärkere Hand brauchst als zum Open selbst.","chip-ev":"Der Erwartungswert eines Spielzugs in Chips, ohne Umrechnung in Geld (ohne ICM).","tournament-equity":"Dein erwarteter Anteil am Preispool bei gegebener Auszahlungsstruktur und gegebenen Stacks. Dasselbe nennt man auch „$EV“.","prize-pool":"Die Gesamtsumme an Geld, die unter den Preisträgern eines Turniers verteilt wird.","payout":"Der Preis für einen bestimmten Platz im Turnier; zusammen ergeben sie die Preisverteilung.","pay-jump":"Der Unterschied in der Auszahlung zwischen benachbarten Plätzen im Turnier; große Sprünge erhöhen die Risk Premium.","final-table":"Der letzte Tisch eines Turniers, an dem um die höchsten Preise gespielt wird.","short-stack":"Ein Stack, der im Verhältnis zu den Blinds klein ist; im Turnier meist einer mit nur noch wenigen Big Blinds.","nash-equilibrium":"Eine Kombination von Strategien, bei der sich kein Spieler verbessern kann, indem nur er allein seine Strategie ändert.","overcall":"Das Callen eines Einsatzes, den vor dir schon jemand gecallt hat.","heads-up":"Spiel eins gegen eins: Am Tisch oder in der Hand sind nur noch zwei Spieler.","dead-money":"Chips im Pot von Spielern, die ihn nicht mehr gewinnen können, z. B. von denen, die gefoldet haben.","stack-off":"Den ganzen Stack in einer Hand in den Pot bringen, also all-in gehen oder ein All-in callen.","exploit":"Ein bewusstes Abweichen von der Basisstrategie, um einen bestimmten Fehler eines Gegners oder des ganzen Spielerpools auszunutzen.","hud":"Eine Einblendung über dem Tisch im Online-Spiel, die Statistiken der Gegner aus früher gespielten Händen zeigt.","vpip":"HUD-Statistik: in welchem Anteil der Hände ein Spieler vor dem Flop freiwillig Geld in den Pot legt (callt oder erhöht).","pfr":"HUD-Statistik: in welchem Anteil der Hände ein Spieler vor dem Flop erhöht.","wtsd":"HUD-Statistik: wie oft ein Spieler, der den Flop gesehen hat, zum Showdown kommt.","nit":"Ein sehr tighter Spieler, der fast nur mit starken Händen in den Pot geht.","regular":"Ein Stammspieler auf einem bestimmten Limit, der dort ein großes Volumen an Händen spielt; im Kurs dem Freizeitspieler gegenübergestellt.","tag":"Tight-aggressiver Stil: wenige Hände, aber aggressiv gespielt (Bets und Raises).","lag":"Loose-aggressiver Stil: viele Hände, aggressiv gespielt.","recreational":"Ein Spieler, der zum Spaß spielt und meist schwächer ist als die Stammspieler; im Jargon abwertend „Fish“.","calling-station":"Abwertend für einen Spieler, der sehr oft callt, selbst mit schwachen Händen oder Draws.","maniac":"Abwertend für einen sehr loosen und aggressiven Spieler, der mit fast allem setzt und erhöht.","rake":"Die Gebühr, die ein Casino oder Online-Pokerraum für das Ausrichten des Spiels aus dem Pot nimmt.","rake-cap":"Der Höchstbetrag an Rake, den ein Pokerraum aus einer einzelnen Hand nehmen darf."},
  "en": {"royal-flush":"The highest hand in poker: ace, king, queen, jack and ten of the same suit, e.g. A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Five consecutive cards of the same suit, e.g. 5♥ 6♥ 7♥ 8♥ 9♥. The highest version (ace down to ten) has its own name and is the strongest hand in the game.","four-of-a-kind":"Four cards of the same rank, e.g. four sevens. If two players have four of a kind of the same rank, the higher fifth card (the kicker) wins.","full-house":"Three of a kind plus a pair in one hand, e.g. three queens and two fives. Between two full houses, the higher three of a kind wins.","flush":"Five cards of the same suit (♠, ♥, ♦ or ♣) that are not in sequence. Between two such hands, the one with the higher top card wins; if those are equal, the next card decides.","straight":"Five consecutive cards, not all of the same suit, e.g. 5-6-7-8-9. The ace can be the highest card (A-K-Q-J-T) or the lowest (A-2-3-4-5).","three-of-a-kind":"Three cards of the same rank and two other cards. In hold'em it has two versions with their own names: a set, when the pair is in your hand and the third card is on the board, and trips, when the pair is on the board and the third card is in your hand.","set":"Three of a kind made from a pair in your hand and one card on the board, e.g. 7♣ 7♦ on a K-7-2 flop.","two-pair":"Two different pairs and a fifth card, e.g. K-K-8-8-3. Ties are decided first by the higher pair, then the lower pair, and finally the fifth card.","pair":"Two cards of the same rank and three other cards, e.g. two nines. Only high card is weaker.","high-card":"A hand with no pair or better combination; its strength is set by the highest card, and on a tie by the next ones.","kicker":"The highest card outside the made hand, used to break a tie. Example: a pair of aces with a king beats a pair of aces with a queen.","wheel":"The lowest straight: A-2-3-4-5, where the ace counts as the lowest card.","check":"Continuing without putting in chips, possible only when you don't have to add anything: nobody has bet yet in this betting round (before the flop, the big blind can do this when nobody has raised). Not to be confused with call, which means adding chips to match an opponent's bet.","bet":"The first chips put in during a betting round in which nobody has bet yet (in a broader sense, any chips put into the pot are called a bet).","call":"Putting into the pot the amount of an opponent's bet or raise so you can keep playing. Not to be confused with check, which means continuing without betting when nobody has bet.","raise":"Increasing the amount above an opponent's bet; the other players must add the difference, raise again or fold.","fold":"Giving up the hand: you throw away your cards and lose whatever you have already put into the pot.","check-raise":"You check first, and when an opponent bets, you raise them in the same betting round.","all-in":"Betting all of your chips. From each opponent you can then win at most as much as you put in yourself; the rest is played for in a side pot.","pot":"All the chips bet in the current hand. They go to the player with the best hand at showdown (with side pots, each pot is decided separately) or to the player left when everyone else folds.","side-pot":"A separate pot created when someone is all-in: only players who put in more than the all-in player compete for it, so the all-in player cannot win it.","split-pot":"A situation where players with equal hands share the pot, e.g. when both are playing the same straight on the board.","playing-the-board":"A situation where your best five-card hand is made only of community cards; your hole cards add nothing, so at best you split the pot.","board":"The face-up community cards in the middle (flop, turn, river) that all players use. It means the cards, not the table you play at.","community-cards":"Cards dealt face up in the middle that every player can use to make a hand; in hold'em there are five.","hole-cards":"The two face-down cards you get at the start of a hand in hold'em; only you can see them.","small-blind":"The smaller forced bet posted before the deal by the player to the left of the button (heads up, by the button itself); the seat is also called this.","big-blind":"The larger forced bet posted before the deal by the second player to the left of the button (heads up, by the player opposite the button); the seat is also called this. It is also used as the unit for stack sizes and results.","chips":"The discs used to play at the table; in cash games they represent money, in tournaments tournament points.","stack":"All the chips a player has in front of them; usually given in big blinds (e.g. 100 big blinds).","street":"A slang name for a betting round: preflop, flop, turn and river are the four streets. Example: “value on three streets” means value bets on the flop, turn and river.","betting-round":"A stage of the hand in which players take turns to check, bet, call, raise or fold; in hold'em there are four: preflop, flop, turn and river.","preflop":"The first betting round: after the hole cards are dealt, before the flop comes.","flop":"The first three community cards, dealt together after preflop betting; the second betting round is also called this.","turn":"The fourth community card and the third betting round.","river":"The fifth and last community card, and the last betting round before showdown.","showdown":"Revealing the cards after the last betting round when at least two players are still in the hand; the best hand takes the pot.","position":"Your seat at the table relative to the button, which sets the order of action. Whoever acts later sees more of the opponents' actions before deciding.","in-position":"The situation of a player who acts last after the flop, so they see the opponent's action before deciding.","out-of-position":"The situation of a player who acts before the opponent after the flop, so they decide without knowing the opponent's action.","early-position":"The first seats to act before the flop (e.g. UTG); many players are still to act after you.","late-position":"The seats that act last: the button and the seats just before it, especially the cutoff.","utg":"The first player to act before the flop, sitting directly to the left of the big blind.","hijack":"The seat directly before the cutoff, i.e. the second seat to the right of the button.","cutoff":"The seat directly to the right of the button, acting just before it.","button":"The dealer's seat, marked with a “dealer” disc. After the flop it acts last in every betting round.","outs":"A card still in the deck that will improve your hand, usually by completing a draw. Example: with a flush draw, your outs are the remaining cards of your suit.","draw":"A hand that is not yet a strong made hand but can become one with the next community cards, e.g. when you are one card short of a flush or a straight.","flush-draw":"Four cards of the same suit (in your hand and on the board together); you need one more to make a flush.","straight-draw":"Four cards that need one more to make a straight. Types: OESD (a card is missing at either of two ends) and gutshot (a card is missing in the middle).","oesd":"OESD is short for open-ended straight draw: a straight draw of four consecutive cards completed by a card at either end, e.g. 5-6-7-8 needs a four or a nine.","gutshot":"A straight draw missing one specific rank in the middle, e.g. 5-6-8-9 needs only a seven.","backdoor":"A draw on the flop that needs two matching cards in a row, on the turn and on the river, e.g. three cards of one suit after the flop.","pot-odds":"The ratio of the amount you have to put in to the pot you can win (including the opponent's bet). It tells you how often you need to win for a call to be profitable.","implied-odds":"Pot odds increased by the chips you expect to win on later streets if you hit your hand.","equity":"Your chance of winning the pot if all remaining cards were dealt with no more betting; usually given as a percentage.","equity-realization":"How much of its equity a hand turns into winnings when betting continues (it can realize less or more than its equity); it depends on things like position and how easy the hand is to play.","expected-value":"The average result of a play if you repeated it many times. A play that is positive on average makes money in the long run, even if it loses this time.","combo":"One specific two-card holding with suits, e.g. A♠ K♥. Counting these holdings shows how many of a given hand are really in a range.","range":"The set of all hands a player can have in a given situation, or the hands they would make a given play with.","mixed-hand":"A hand with which the equilibrium strategy sometimes chooses one play and sometimes another (e.g. sometimes a raise, sometimes a call); both plays are correct. Such a hand is also said to be played with a mixed strategy.","open":"Entering the pot before the flop with a raise when everyone before you has folded.","suited":"Two hole cards of the same suit, e.g. A♥ K♥ (written AKs).","offsuit":"Two hole cards of different suits, e.g. A♥ K♣ (written AKo).","pocket-pair":"A pair made of your two hole cards, e.g. 8♣ 8♦ before the flop.","connectors":"Hole cards of adjacent ranks, e.g. 8-7 or 9-8; they make straights more easily.","3-bet":"The first raise of an open before the flop; the name counts the big blind as the first bet and the open as the second.","4-bet":"A raise of a 3-bet, i.e. the fourth bet in a betting round.","limp":"Entering the pot before the flop by just calling the big blind when nobody has raised yet.","isolation":"A raise after one or more limps, to play the limper (often a weaker player) one on one.","texture":"The character of the community cards: how many suits there are, whether the cards are close together, whether there is a pair. It determines which hands and draws are possible.","dry":"A board on which few draws and strong hands are possible, e.g. K♠ 7♦ 2♣.","wet":"A board on which many draws and strong hands are possible, e.g. J♥ T♥ 8♣.","rainbow":"A flop with three cards of three different suits, so nobody has a flush draw on the flop.","two-tone":"A flop with two cards of the same suit, so flush draws are possible.","monotone":"A flop with three cards of the same suit, so a flush may already be made.","paired":"A board with a pair on it (two cards of the same rank), e.g. 8-8-3.","connected":"A board on which someone may already have made a straight, e.g. 9-8-7.","disconnected":"A board with cards far apart, making it hard to build a straight or a straight draw, e.g. K-7-2.","semi-connected":"A board with straight draws but no straight possible yet, e.g. T-8-3 (the classification used in this course).","wetness":"How much a board favors draws and strong hands: from dry to wet. It is also described as how coordinated the board is.","top-pair":"A pair with the highest card on the board, e.g. K♠ Q♦ on a K-7-2 flop.","second-pair":"A pair with the second-highest card on the board, e.g. 7♠ 6♠ on a K-7-2 flop.","overpair":"A pocket pair higher than every card on the board, e.g. Q-Q on a J-7-2 flop.","c-bet":"Continuation bet: a bet by the player who was the aggressor in the previous round, e.g. a bet on the flop after opening preflop.","aggressor":"The player who last bet or raised in the previous betting round.","initiative":"The role of the last aggressor: they usually make the next bet.","range-advantage":"A situation where one player's range has more total equity on a given board than the opponent's range.","nuts-advantage":"A situation where one player has proportionally more of the strongest hands in their range than the opponent.","nuts":"The strongest possible hand on a given board at a given moment. Example: on K♥ 9♥ 4♥ 2♣ it is the ace-high flush (with the ace of hearts).","polarized":"Of a range: made up mainly of very strong hands and bluffs, with almost no medium hands.","polarization":"Building a range from the extremes: strong hands for value and bluffs, without medium hands.","linear":"Of a range: built from the top down, from the strongest hands, with no separate group of bluffs. You will also see the related term “merged range” (a non-polarized range); according to published solver analyses, merged is an intermediate shape between this range and a polarized one.","condensed":"Of a range: without the strongest hands (capped) and made up mainly of medium hands; the opposite of polarized.","value":"Betting with a strong hand so that the opponent calls with a weaker hand.","value-bet":"A single bet for value: made with a strong hand so that weaker hands call it.","bluff":"A bet with a weak hand that is unlikely to win at showdown, to make the opponent fold a better hand.","semi-bluff":"A bet with a hand that is still weak but can improve (e.g. with a draw): you win if the opponent folds or if you hit.","blocker":"A card in your hand that lowers the chance that the opponent has certain hands. Example: if you hold the ace of hearts, the opponent cannot have the ace-high heart flush.","bluff-catcher":"A hand that beats only the opponent's bluffs and loses to their value bets.","barrel":"Another bet in the next betting round after your own bet in the previous round.","second-barrel":"A second bet in a row: after a c-bet on the flop, the player bets again on the turn.","probe-bet":"A turn bet by the out-of-position player after the preflop aggressor checked the flop instead of making a c-bet.","donk-bet":"A bet by a player who bets before the aggressor from the previous round has had a chance to act.","overbet":"A bet after the flop that is larger than the whole pot.","effective-stack":"In a hand between two players: the smaller of their stacks, i.e. the most that can realistically be won or lost. With several players, it is calculated separately for each pair.","spr":"The effective stack divided by the pot at the start of a street (for planning the hand, it is calculated on the flop); it shows how deep the stacks are relative to the pot (the lower the SPR, the faster everything goes into the pot).","mdf":"The smallest part of your range you must defend against a bet so that an opponent's bluff with a hand that has no chance is not automatically profitable.","alpha":"How often the opponent must fold for a bluff with a hand that has no chance to break even; it depends on the bet size relative to the pot.","variance":"The spread of results around expected value: even with good play, short stretches can show big losses or big wins.","buy-in":"The amount it costs to enter a tournament or to sit in a cash game.","bankroll":"Your whole reserve set aside only for playing poker; in this app it is counted in buy-ins, not money.","tilt":"A state in which emotions (anger, frustration, euphoria) make your decisions at the table worse.","winrate":"A player's average result over a longer sample; in cash games usually in bb/100, i.e. big blinds per hundred hands.","downswing":"A period of clearly worse results, usually bigger losses than skill would suggest; the opposite of an upswing.","session":"One sitting of poker, from when you start playing to when you stop.","stakes":"The size of the blinds in a cash game or the buy-in in a tournament; “micro stakes” are the lowest levels.","standard-deviation":"A measure of the spread of results (the square root of variance); in poker usually given in bb/100.","risk-of-ruin":"The probability that you will ever lose your whole bankroll if you keep playing at the same stakes.","mental-game":"The psychological side of poker: dealing with tilt, emotions and focus at the table.","tournament":"A format in which the blinds go up at intervals and play continues until one player has all the chips; prizes go to the highest finishers.","push-fold":"A simplified strategy for short stacks: before the flop you either go all-in or fold.","shove":"An all-in play, usually as a raise before the flop.","icm":"A model that converts tournament chips into money value, taking into account the payout structure and all players' stacks.","bubble":"The stage of a tournament just before the paid places, when a few more players need to bust before anyone is in the money.","bubble-factor":"An ICM measure: how much more losing a given number of chips hurts in a tournament than winning the same number helps.","cover":"To have at least as many chips as the opponent. When an opponent covers you, losing an all-in to them ends your tournament.","risk-premium":"Extra equity beyond what pot odds require, needed in a tournament to risk an all-in, because losing costs more than winning gains.","m-ratio":"Your stack divided by the total of blinds and antes in one hand: how many full orbits your chips will last without playing.","red-zone":"The zone of very low M: you are left mainly with all-in or fold.","green-zone":"The zone of high M: your stack lets you play freely, cautiously or aggressively.","ante":"A small forced payment into the pot before the deal from every player (mainly in tournaments).","bb-ante":"An ante format in which, instead of every player, the player in the big blind pays the ante for the whole table.","fold-equity":"The part of a play's value that comes from the chance that the opponent folds.","gap-concept":"The principle that you need a stronger hand to call an open than to open yourself.","chip-ev":"The expected value of a play counted in chips, without converting them into money (without ICM).","tournament-equity":"Your expected share of the prize pool given the payout structure and stacks. It is also called “$EV”.","prize-pool":"The total money to be shared among the players who win prizes in a tournament.","payout":"The prize for a specific finishing place in a tournament; together they make up the prize distribution.","pay-jump":"The difference in payout between adjacent places in a tournament; big jumps increase the risk premium.","final-table":"The last table of a tournament, where the top prizes are played for.","short-stack":"A stack that is small relative to the blinds; in tournaments usually one with only a few big blinds left.","nash-equilibrium":"A set of strategies in which no player can gain by changing only their own strategy.","overcall":"Calling a bet that someone before you has already called.","heads-up":"Playing one on one: only two players are left at the table or in the hand.","dead-money":"Chips in the pot from players who can no longer win it, e.g. from those who folded.","stack-off":"To put your whole stack into the pot in one hand, i.e. to go all-in or call an all-in.","exploit":"A deliberate departure from the baseline strategy to take advantage of a specific mistake by an opponent or by the whole player pool.","hud":"An overlay on the table in online play that shows opponents' statistics from previously played hands.","vpip":"A HUD statistic: the percentage of hands in which a player voluntarily puts money into the pot before the flop (calls or raises).","pfr":"A HUD statistic: the percentage of hands in which a player raises before the flop.","wtsd":"A HUD statistic: how often a player who saw the flop gets to showdown.","nit":"A very tight player who enters the pot almost only with strong hands.","regular":"A frequent player at a given stakes level who plays a lot of hands; in this course contrasted with the recreational player.","tag":"A tight aggressive style: few hands, but played aggressively (bets and raises).","lag":"A loose aggressive style: many hands, played aggressively.","recreational":"A player who plays for fun and is usually weaker than the regulars; in slang, derogatorily called a “fish”.","calling-station":"A derogatory term for a player who calls very often, even with weak hands or draws.","maniac":"A derogatory term for a very loose and aggressive player who bets and raises with almost anything.","rake":"The fee a casino or online poker room takes from the pot for running the game.","rake-cap":"The maximum amount of rake a poker room can take from a single hand."},
  "es": {"royal-flush":"La jugada más alta del póker: as, rey, dama, jota y diez del mismo palo, p. ej., A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Cinco cartas consecutivas del mismo palo, p. ej., 5♥ 6♥ 7♥ 8♥ 9♥. La versión más alta (del as al diez) tiene nombre propio y es la jugada más fuerte del juego.","four-of-a-kind":"Cuatro cartas del mismo valor, p. ej., cuatro sietes. Si hay dos pókeres del mismo valor, gana la quinta carta más alta (el kicker).","full-house":"Un trío y una pareja en la misma jugada, p. ej., tres damas y dos cincos. Entre dos fulls, gana el del trío más alto.","flush":"Cinco cartas del mismo palo (♠, ♥, ♦ o ♣) que no van seguidas. Entre dos jugadas así, gana la de la carta más alta y, si es igual, la de la siguiente.","straight":"Cinco cartas consecutivas, no todas del mismo palo, p. ej., 5-6-7-8-9. El as puede ser la carta más alta (A-K-Q-J-T) o la más baja (A-2-3-4-5).","three-of-a-kind":"Tres cartas del mismo valor y otras dos. En hold'em tiene dos variantes con nombre propio: set, cuando la pareja está en tu mano y la tercera carta en la mesa, y trips, cuando la pareja está en la mesa y la tercera carta en tu mano.","set":"Trío formado con una pareja en la mano y una carta de la mesa, p. ej., 7♣ 7♦ en un flop K-7-2.","two-pair":"Dos parejas distintas y una quinta carta, p. ej., K-K-8-8-3. El empate lo decide primero la pareja más alta, luego la más baja y, al final, la quinta carta.","pair":"Dos cartas del mismo valor y otras tres, p. ej., dos nueves. Solo la carta alta es más débil.","high-card":"Jugada sin pareja ni otra combinación mejor; su fuerza la decide la carta más alta y, si hay empate, las siguientes.","kicker":"La carta más alta fuera de la jugada, que deshace un empate. Ejemplo: una pareja de ases con rey gana a una pareja de ases con dama.","wheel":"La escalera más baja: A-2-3-4-5, en la que el as cuenta como la carta más baja.","check":"Seguir jugando sin poner fichas, solo posible cuando no tienes que añadir nada: en esta ronda de apuestas nadie ha apostado todavía (antes del flop puede hacerlo la ciega grande si nadie ha subido). No confundir con igualar, que es poner fichas para cubrir la apuesta del rival.","bet":"Las primeras fichas que se ponen en una ronda de apuestas en la que nadie ha apostado todavía (en sentido amplio, se llama apuesta a cualquier ficha que se mete en el bote).","call":"Poner en el bote lo mismo que la apuesta o la subida del rival para seguir jugando. No confundir con pasar, que es seguir jugando sin apostar cuando nadie ha apostado.","raise":"Aumentar la cantidad por encima de la apuesta del rival; los demás tienen que poner la diferencia, volver a subir o retirarse.","fold":"Abandonar la mano: tiras tus cartas y pierdes lo que ya hayas metido en el bote.","check-raise":"Primero pasas y, cuando el rival apuesta, le subes en la misma ronda de apuestas.","all-in":"Apostar todas tus fichas. A cada rival puedes ganarle como máximo lo mismo que hayas metido tú; el resto se juega en un bote secundario.","pot":"Todas las fichas apostadas en la mano actual. Se las lleva el jugador con la mejor jugada en el showdown (si hay botes secundarios, cada bote se decide por separado) o el jugador que queda cuando todos los demás se retiran.","side-pot":"Bote aparte que se crea cuando alguien va all-in: solo lo juegan los jugadores que han metido más que el jugador all-in, así que este no puede ganarlo.","split-pot":"Situación en la que los jugadores con jugadas iguales se reparten el bote, p. ej., cuando ambos juegan la misma escalera que está en la mesa.","playing-the-board":"Situación en la que tu mejor jugada de cinco cartas la forman solo las cartas comunitarias; tus cartas propias no aportan nada, así que, como mucho, divides el bote.","board":"Las cartas comunitarias descubiertas en el centro (flop, turn, river), que usan todos los jugadores. En este sentido, «mesa» son las cartas, no el lugar de juego (sentarse a la mesa, mesa final).","community-cards":"Cartas que se colocan descubiertas en el centro y que cualquier jugador puede usar para su jugada; en hold'em son cinco.","hole-cards":"Las dos cartas tapadas que recibes al principio de la mano en hold'em; solo las ves tú.","small-blind":"La apuesta obligatoria más pequeña, que pone antes del reparto el jugador a la izquierda del botón (entre dos jugadores, el propio botón); también se llama así ese asiento.","big-blind":"La apuesta obligatoria más grande, que pone antes del reparto el segundo jugador a la izquierda del botón (entre dos jugadores, el jugador que no es el botón); también se llama así ese asiento. Además, sirve de unidad para medir stacks y resultados.","chips":"Las piezas con las que se juega en la mesa; en las partidas de cash representan dinero y en los torneos, puntos del torneo.","stack":"Todas las fichas que un jugador tiene delante; normalmente se indican en ciegas grandes (p. ej., 100 ciegas grandes).","street":"Nombre coloquial de una ronda de apuestas: preflop, flop, turn y river son las cuatro calles. Ejemplo: «valor en tres calles» son apuestas de valor en el flop, el turn y el river.","betting-round":"Fase de la mano en la que los jugadores, por turnos, pasan, apuestan, igualan, suben o se retiran; en hold'em hay cuatro: preflop, flop, turn y river.","preflop":"La primera ronda de apuestas: después de repartir las cartas propias y antes de que salga el flop.","flop":"Las tres primeras cartas comunitarias, que salen a la vez tras las apuestas preflop; también se llama así la segunda ronda de apuestas.","turn":"La cuarta carta comunitaria y la tercera ronda de apuestas.","river":"La quinta y última carta comunitaria, y la última ronda de apuestas antes del showdown.","showdown":"Mostrar las cartas tras la última ronda de apuestas cuando quedan al menos dos jugadores en la mano; la mejor jugada se lleva el bote.","position":"El asiento en la mesa respecto al botón, que marca el orden de actuación. Quien actúa más tarde ve más acciones de los rivales antes de decidir.","in-position":"Situación del jugador que actúa el último después del flop, así que ve la acción del rival antes de decidir.","out-of-position":"Situación del jugador que actúa antes que el rival después del flop, así que decide sin conocer su acción.","early-position":"Los primeros asientos en actuar antes del flop (p. ej., UTG); detrás de ti aún quedan muchos jugadores.","late-position":"Los asientos que actúan los últimos: el botón y los asientos justo antes de él, sobre todo el cutoff.","utg":"El primer jugador en actuar antes del flop, sentado justo a la izquierda de la ciega grande.","hijack":"El asiento justo antes del cutoff, es decir, el segundo a la derecha del botón.","cutoff":"El asiento justo a la derecha del botón, que actúa inmediatamente antes que él.","button":"El asiento del repartidor, marcado con una ficha de «dealer». Después del flop actúa el último en cada ronda de apuestas.","outs":"Carta que aún está en la baraja y que mejorará tu mano, normalmente completando un proyecto. Ejemplo: con un proyecto de color, tus outs son las cartas que quedan de tu palo.","draw":"Mano que todavía no es una jugada fuerte, pero puede llegar a serlo con las siguientes cartas comunitarias, p. ej., cuando te falta una carta para el color o la escalera.","flush-draw":"Cuatro cartas del mismo palo (sumando tu mano y la mesa); te falta una para tener color.","straight-draw":"Cuatro cartas a las que les falta una para la escalera. Tipos: OESD (falta una carta en cualquiera de los dos extremos) y gutshot (falta una carta en el medio).","oesd":"Abreviatura de open-ended straight draw: proyecto de escalera de cuatro cartas consecutivas que se completa con una carta por cualquiera de los dos extremos, p. ej., 5-6-7-8 espera un cuatro o un nueve.","gutshot":"Proyecto de escalera al que le falta un valor concreto en el medio, p. ej., 5-6-8-9 solo espera un siete.","backdoor":"Proyecto en el flop que necesita dos cartas útiles seguidas, en el turn y en el river, p. ej., tres cartas del mismo palo tras el flop.","pot-odds":"La relación entre lo que tienes que poner y el bote que puedes ganar (incluida la apuesta del rival). Indica con qué frecuencia tienes que ganar para que igualar sea rentable.","implied-odds":"Las pot odds más las fichas que esperas ganar en las calles siguientes si ligas tu jugada.","equity":"Tu probabilidad de ganar el bote si se repartieran todas las cartas que faltan sin más apuestas; normalmente en porcentaje.","equity-realization":"En qué medida una mano convierte su equity en ganancias cuando siguen las apuestas (puede realizar menos o más que su equity); depende, entre otras cosas, de la posición y de lo fácil que sea jugar la mano.","expected-value":"El resultado medio de una jugada si la repitieras muchas veces. Una jugada que de media da beneficio gana dinero a largo plazo, aunque esta vez pierda.","combo":"Una combinación concreta de dos cartas con sus palos, p. ej., A♠ K♥. Contar estas combinaciones muestra cuántas manos de un tipo hay realmente en un rango.","range":"El conjunto de todas las manos que un jugador puede tener en una situación concreta, o de las manos con las que haría una jugada determinada.","mixed-hand":"Mano con la que la estrategia de equilibrio elige unas veces una jugada y otras veces otra (p. ej., a veces subir, a veces igualar); ambas jugadas son correctas. También se dice que esa mano se juega con una estrategia mixta.","open":"Entrar en el bote antes del flop subiendo, cuando todos los que actúan antes que tú se han retirado.","suited":"Dos cartas propias del mismo palo, p. ej., A♥ K♥ (se escribe AKs).","offsuit":"Dos cartas propias de palos distintos, p. ej., A♥ K♣ (se escribe AKo).","pocket-pair":"Pareja formada por tus dos cartas propias, p. ej., 8♣ 8♦ antes del flop.","connectors":"Cartas propias de valores contiguos, p. ej., 8-7 o 9-8; con ellas es más fácil formar escalera.","3-bet":"La primera subida a una apertura antes del flop; el nombre cuenta la ciega grande como la primera apuesta y la apertura como la segunda.","4-bet":"Una subida a un 3-bet, es decir, la cuarta apuesta de una ronda de apuestas.","limp":"Entrar en el bote antes del flop limitándose a igualar la ciega grande, cuando nadie ha subido todavía.","isolation":"Subida tras uno o varios limps para jugar contra el limper (a menudo un jugador más débil) uno contra uno.","texture":"El carácter de las cartas comunitarias: cuántos palos hay, si las cartas están cerca entre sí, si hay pareja. De ello depende qué jugadas y proyectos son posibles.","dry":"Mesa en la que son posibles pocos proyectos y pocas jugadas fuertes, p. ej., K♠ 7♦ 2♣.","wet":"Mesa en la que son posibles muchos proyectos y jugadas fuertes, p. ej., J♥ T♥ 8♣.","rainbow":"Flop con tres cartas de tres palos distintos, así que en el flop nadie tiene proyecto de color.","two-tone":"Flop en el que dos cartas son del mismo palo, así que hay proyectos de color posibles.","monotone":"Flop con las tres cartas del mismo palo, así que puede que ya haya un color hecho.","paired":"Mesa en la que hay una pareja (dos cartas del mismo valor), p. ej., 8-8-3.","connected":"Mesa en la que alguien puede tener ya escalera, p. ej., 9-8-7.","disconnected":"Mesa con cartas alejadas entre sí, con la que es difícil formar escalera o proyecto de escalera, p. ej., K-7-2.","semi-connected":"Mesa en la que hay proyectos de escalera, pero todavía no es posible la escalera, p. ej., T-8-3 (clasificación usada en el curso).","wetness":"Grado en que una mesa favorece los proyectos y las jugadas fuertes: de seca a húmeda. También se habla de lo coordinada que está la mesa.","top-pair":"Pareja con la carta más alta de la mesa, p. ej., K♠ Q♦ en un flop K-7-2.","second-pair":"Pareja con la segunda carta más alta de la mesa, p. ej., 7♠ 6♠ en un flop K-7-2.","overpair":"Pareja de mano más alta que cualquier carta de la mesa, p. ej., Q-Q en un flop J-7-2.","c-bet":"Apuesta de continuación: apuesta del jugador que fue el agresor en la ronda anterior, p. ej., una apuesta en el flop tras abrir preflop.","aggressor":"El jugador que apostó o subió el último en la ronda de apuestas anterior.","initiative":"El papel del último agresor: normalmente es él quien hace la siguiente apuesta.","range-advantage":"Situación en la que el rango de un jugador tiene, en una mesa concreta, más equity total que el rango del rival.","nuts-advantage":"Situación en la que un jugador tiene en su rango, proporcionalmente, más manos de las más fuertes que el rival.","nuts":"La mano más fuerte posible en una mesa concreta en un momento dado. Ejemplo: en la mesa K♥ 9♥ 4♥ 2♣ es el color al as de corazones.","polarized":"Dicho de un rango: formado sobre todo por manos muy fuertes y faroles, casi sin manos medias.","polarization":"Construir un rango con los extremos: manos fuertes para valor y faroles, sin manos medias.","linear":"Dicho de un rango: construido de arriba abajo, desde las manos más fuertes, sin un grupo aparte de faroles. También verás el término relacionado «merged range» (rango no polarizado); según análisis de solver publicados, merged es una forma intermedia entre este rango y uno polarizado.","condensed":"Dicho de un rango: sin las manos más fuertes (limitado por arriba) y formado sobre todo por manos medias; lo contrario de polarizado.","value":"Apostar con una mano fuerte para que el rival iguale con una mano peor.","value-bet":"Una apuesta concreta por valor: se hace con una mano fuerte para que la igualen manos peores.","bluff":"Apuesta con una mano débil que difícilmente ganará en el showdown, para que el rival se retire con una mano mejor.","semi-bluff":"Apuesta con una mano todavía débil, pero con opciones de mejorar (p. ej., con un proyecto): ganas si el rival se retira o si ligas.","blocker":"Carta de tu mano que reduce la probabilidad de que el rival tenga determinadas manos. Ejemplo: si tienes el as de corazones, el rival no puede tener el color al as de corazones.","bluff-catcher":"Mano que solo gana a los faroles del rival y pierde contra sus apuestas de valor.","barrel":"Otra apuesta en la siguiente ronda de apuestas después de tu propia apuesta en la ronda anterior.","second-barrel":"Segunda apuesta seguida: tras un c-bet en el flop, el jugador vuelve a apostar en el turn.","probe-bet":"Apuesta en el turn del jugador fuera de posición después de que el agresor preflop pasara en el flop en lugar de hacer c-bet.","donk-bet":"Apuesta de un jugador que apuesta antes de que el agresor de la ronda anterior haya podido actuar.","overbet":"Apuesta después del flop mayor que todo el bote.","effective-stack":"En una mano entre dos jugadores: el menor de sus stacks, es decir, lo máximo que se puede ganar o perder realmente. Con varios jugadores, se calcula por separado para cada pareja de jugadores.","spr":"El stack efectivo dividido entre el bote al inicio de una calle (para planificar la mano se calcula en el flop); indica lo profundos que son los stacks en relación con el bote (cuanto más bajo es el SPR, antes acaba todo en el bote).","mdf":"La parte más pequeña del rango que hay que defender ante una apuesta para que un farol del rival con una mano sin opciones no sea rentable automáticamente.","alpha":"Con qué frecuencia tiene que retirarse el rival para que un farol con una mano sin opciones quede a cero; depende del tamaño de la apuesta respecto al bote.","variance":"La dispersión de los resultados alrededor del valor esperado: incluso jugando bien, las rachas cortas pueden ser muy negativas o muy positivas.","buy-in":"Lo que cuesta entrar en un torneo o sentarse en una partida de cash.","bankroll":"Toda la reserva destinada exclusivamente a jugar al póker; en esta app se cuenta en buy-ins, no en dinero.","tilt":"Estado en el que las emociones (enfado, frustración, euforia) empeoran tus decisiones en la mesa.","winrate":"El resultado medio de un jugador en una muestra larga; en las partidas de cash normalmente en bb/100, es decir, ciegas grandes por cada cien manos.","downswing":"Periodo de resultados claramente peores, normalmente con pérdidas mayores de lo que correspondería a la habilidad; lo contrario de un upswing.","session":"Un rato de póker, desde que empiezas a jugar hasta que lo dejas.","stakes":"El tamaño de las ciegas en una partida de cash o del buy-in en un torneo; los «microlímites» son los niveles más bajos.","standard-deviation":"Medida de la dispersión de los resultados (la raíz cuadrada de la varianza); en póker suele darse en bb/100.","risk-of-ruin":"La probabilidad de que llegues a perder todo tu bankroll si sigues jugando en los mismos límites.","mental-game":"La parte psicológica del póker: gestionar el tilt, las emociones y la concentración en la mesa.","tournament":"Formato en el que las ciegas suben cada cierto tiempo y se juega hasta que un jugador tiene todas las fichas; los premios son para los mejor clasificados.","push-fold":"Estrategia simplificada para stacks cortos: antes del flop, o vas all-in o te retiras.","shove":"Jugada de all-in, normalmente como subida antes del flop.","icm":"Modelo que convierte las fichas de torneo en valor en dinero teniendo en cuenta la estructura de pagos y los stacks de todos los jugadores.","bubble":"La fase del torneo justo antes de los puestos pagados, cuando faltan unas pocas eliminaciones para entrar en premios.","bubble-factor":"Indicador del ICM: cuánto más duele en un torneo perder una cantidad de fichas que lo que alegra ganar esa misma cantidad.","cover":"Tener al menos tantas fichas como el rival. Si el rival te cubre, perder un all-in contra él termina tu torneo.","risk-premium":"Equity extra, por encima de lo que exigen las pot odds, que necesitas en un torneo para arriesgar un all-in, porque perder cuesta más de lo que aporta ganar.","m-ratio":"Tu stack dividido entre la suma de las ciegas y el ante de una mano: para cuántas vueltas completas (órbitas) te llegan las fichas sin jugar.","red-zone":"La zona de M muy baja: te queda sobre todo ir all-in o retirarte.","green-zone":"La zona de M alta: tu stack te permite jugar con libertad, de forma conservadora o agresiva.","ante":"Pequeño pago obligatorio al bote antes del reparto que hacen todos los jugadores (sobre todo en torneos).","bb-ante":"Formato de ante en el que, en lugar de todos los jugadores, el jugador de la ciega grande paga el ante de toda la mesa.","fold-equity":"La parte del valor de una jugada que viene de la posibilidad de que el rival se retire.","gap-concept":"Principio según el cual para igualar una apertura hace falta una mano más fuerte que para abrir tú.","chip-ev":"El valor esperado de una jugada calculado en fichas, sin convertirlas en dinero (sin ICM).","tournament-equity":"Tu parte esperada de la bolsa de premios según la estructura de pagos y los stacks. También se llama «$EV».","prize-pool":"El total de dinero que se reparte entre los jugadores premiados de un torneo.","payout":"El premio por un puesto concreto en un torneo; todos juntos forman la distribución de premios.","pay-jump":"La diferencia de pago entre puestos contiguos en un torneo; los saltos grandes aumentan la prima de riesgo.","final-table":"La última mesa de un torneo, en la que se juegan los premios más altos.","short-stack":"Stack pequeño en relación con las ciegas; en torneos, normalmente uno al que le quedan pocas ciegas grandes.","nash-equilibrium":"Conjunto de estrategias en el que ningún jugador gana nada cambiando solo su propia estrategia.","overcall":"Igualar una apuesta que alguien antes que tú ya ha igualado.","heads-up":"Juego uno contra uno: en la mesa o en la mano solo quedan dos jugadores.","dead-money":"Fichas del bote de jugadores que ya no pueden ganarlo, p. ej., de los que se han retirado.","stack-off":"Meter todo el stack en el bote en una sola mano, es decir, ir all-in o igualar un all-in.","exploit":"Desviarse a propósito de la estrategia base para aprovechar un error concreto de un rival o de toda la población de jugadores.","hud":"Capa sobre la mesa en el juego online que muestra estadísticas de los rivales a partir de manos ya jugadas.","vpip":"Estadística del HUD: en qué porcentaje de manos un jugador mete dinero voluntariamente en el bote antes del flop (iguala o sube).","pfr":"Estadística del HUD: en qué porcentaje de manos un jugador sube antes del flop.","wtsd":"Estadística del HUD: con qué frecuencia un jugador que ha visto el flop llega al showdown.","nit":"Jugador muy cerrado (tight) que entra en el bote casi solo con manos fuertes.","regular":"Jugador habitual de un límite concreto que juega muchas manos; en el curso se contrapone al jugador recreativo.","tag":"Estilo tight agresivo: pocas manos, pero jugadas de forma agresiva (apuestas y subidas).","lag":"Estilo loose agresivo: muchas manos, jugadas de forma agresiva.","recreational":"Jugador que juega por diversión y normalmente peor que los habituales; en jerga, de forma despectiva, «fish».","calling-station":"Término despectivo para un jugador que iguala muchísimo, incluso con manos débiles o proyectos.","maniac":"Término despectivo para un jugador muy suelto (loose) y agresivo que apuesta y sube con cualquier cosa.","rake":"La comisión que el casino o la sala online se queda del bote por organizar la partida.","rake-cap":"La cantidad máxima de rake que la sala puede cobrar en una sola mano."},
  "fr": {"royal-flush":"La combinaison la plus forte au poker : as, roi, dame, valet et dix de la même couleur, p. ex. A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Cinq cartes consécutives de la même couleur, p. ex. 5♥ 6♥ 7♥ 8♥ 9♥. La version la plus haute (de l'as au dix) porte un nom à part et c'est la combinaison la plus forte du jeu.","four-of-a-kind":"Quatre cartes de même valeur, p. ex. quatre sept. Entre deux carrés de même valeur, c'est la cinquième carte la plus haute (le kicker) qui l'emporte.","full-house":"Un brelan et une paire dans la même main, p. ex. trois dames et deux cinq. Entre deux fulls, le brelan le plus haut l'emporte.","flush":"Cinq cartes du même symbole (♠, ♥, ♦ ou ♣) qui ne se suivent pas. Entre deux mains de ce type, celle qui a la carte la plus haute l'emporte ; à égalité, c'est la carte suivante qui décide.","straight":"Cinq cartes consécutives, pas toutes de la même couleur, p. ex. 5-6-7-8-9. L'as peut être la carte la plus haute (A-K-Q-J-T) ou la plus basse (A-2-3-4-5).","three-of-a-kind":"Trois cartes de même valeur et deux autres cartes. Au hold'em, il en existe deux variantes qui ont leur propre nom : le set, quand la paire est dans votre main et la troisième carte sur le board, et les trips, quand la paire est sur le board et la troisième carte dans votre main.","set":"Brelan formé d'une paire en main et d'une carte du board, p. ex. 7♣ 7♦ sur un flop K-7-2.","two-pair":"Deux paires différentes et une cinquième carte, p. ex. K-K-8-8-3. En cas d'égalité, on compare d'abord la paire la plus haute, puis la plus basse, et enfin la cinquième carte.","pair":"Deux cartes de même valeur et trois autres cartes, p. ex. deux neuf. Seule la carte haute est plus faible.","high-card":"Main sans paire ni meilleure combinaison ; sa force dépend de la carte la plus haute, puis des suivantes en cas d'égalité.","kicker":"La carte la plus haute en dehors de la combinaison, qui départage une égalité. Exemple : une paire d'as avec un roi bat une paire d'as avec une dame.","wheel":"La quinte la plus basse : A-2-3-4-5, où l'as compte comme la carte la plus basse.","check":"Continuer sans mettre de jetons, ce qui n'est possible que si vous n'avez rien à ajouter : personne n'a encore misé dans ce tour d'enchères (avant le flop, la grosse blinde peut le faire si personne n'a relancé). À ne pas confondre avec « suivre » (call), qui consiste à ajouter des jetons pour égaler la mise d'un adversaire.","bet":"Premiers jetons mis dans un tour d'enchères où personne n'a encore misé (au sens large, on appelle mise tous les jetons placés dans le pot).","call":"Mettre dans le pot le montant de la mise ou de la relance d'un adversaire pour continuer à jouer. À ne pas confondre avec le check, qui consiste à continuer sans miser quand personne n'a misé.","raise":"Augmenter le montant au-delà de la mise d'un adversaire ; les autres joueurs doivent ajouter la différence, relancer à leur tour ou se coucher. On dit aussi « raise ».","fold":"Abandonner la main : vous jetez vos cartes et perdez ce que vous avez déjà mis dans le pot.","check-raise":"Vous checkez d'abord, puis, quand un adversaire mise, vous le relancez dans le même tour d'enchères.","all-in":"Miser tous vos jetons. Vous ne pouvez alors gagner de chaque adversaire, au maximum, que ce que vous avez vous-même mis ; le reste se joue dans un pot secondaire.","pot":"Tous les jetons misés dans la main en cours. Ils reviennent au joueur qui a la meilleure main au showdown (avec des pots secondaires, chaque pot est attribué séparément) ou au joueur qui reste quand tous les autres se sont couchés.","side-pot":"Pot séparé créé quand un joueur est all-in : seuls les joueurs qui ont mis plus que lui le disputent, donc le joueur all-in ne peut pas le gagner.","split-pot":"Situation où des joueurs ayant des mains égales se partagent le pot, p. ex. quand tous deux jouent la même quinte présente sur le board.","playing-the-board":"Situation où votre meilleure main de cinq cartes n'est composée que de cartes communes ; vos cartes privatives n'apportent rien, donc au mieux vous partagez le pot.","board":"Les cartes communes visibles au centre (flop, turn, river), utilisées par tous les joueurs. Le terme désigne les cartes, pas la table où l'on joue (s'asseoir à la table, table finale).","community-cards":"Cartes posées face visible au centre, que chaque joueur peut utiliser pour former sa main ; au hold'em, il y en a cinq.","hole-cards":"Les deux cartes face cachée que vous recevez au début d'une main au hold'em ; vous seul les voyez.","small-blind":"La plus petite mise obligatoire, posée avant la donne par le joueur à gauche du bouton (à deux joueurs, par le bouton lui-même) ; c'est aussi le nom de cette place à la table.","big-blind":"La plus grosse mise obligatoire, posée avant la donne par le deuxième joueur à gauche du bouton (à deux joueurs, par le joueur face au bouton) ; c'est aussi le nom de cette place. Elle sert aussi d'unité pour mesurer les stacks et les résultats.","chips":"Les disques avec lesquels on joue à la table ; en cash game, ils représentent de l'argent, en tournoi, des points de tournoi.","stack":"Tous les jetons qu'un joueur a devant lui ; on l'exprime généralement en grosses blindes (p. ex. 100 grosses blindes).","street":"Nom familier d'un tour d'enchères : le preflop, le flop, le turn et la river sont les quatre streets. Exemple : « de la value sur trois streets » désigne des mises de value au flop, au turn et à la river.","betting-round":"Étape de la main où les joueurs, chacun leur tour, checkent, misent, suivent, relancent ou se couchent ; au hold'em, il y en a quatre : preflop, flop, turn et river.","preflop":"Le premier tour d'enchères : après la distribution des cartes privatives, avant l'arrivée du flop.","flop":"Les trois premières cartes communes, posées ensemble après les enchères du preflop ; c'est aussi le nom du deuxième tour d'enchères.","turn":"La quatrième carte commune et le troisième tour d'enchères.","river":"La cinquième et dernière carte commune, et le dernier tour d'enchères avant le showdown.","showdown":"Le moment où l'on dévoile les cartes après le dernier tour d'enchères, quand au moins deux joueurs sont encore dans la main ; la meilleure main remporte le pot.","position":"Votre place à la table par rapport au bouton, qui fixe l'ordre de parole. Celui qui parle plus tard voit davantage d'actions adverses avant de décider.","in-position":"Situation du joueur qui parle en dernier après le flop et voit donc l'action de l'adversaire avant de décider.","out-of-position":"Situation du joueur qui parle avant l'adversaire après le flop et décide donc sans connaître son action.","early-position":"Les premières places à parler avant le flop (p. ex. UTG) ; beaucoup de joueurs doivent encore parler après vous.","late-position":"Les places qui parlent en dernier : le bouton et les places juste avant lui, surtout le cutoff.","utg":"Le premier joueur à parler avant le flop, assis juste à gauche de la grosse blinde.","hijack":"La place juste avant le cutoff, c'est-à-dire la deuxième à droite du bouton.","cutoff":"La place juste à droite du bouton, qui parle juste avant lui.","button":"La place du donneur, marquée par un disque « dealer ». Après le flop, elle parle en dernier à chaque tour d'enchères.","outs":"Carte encore dans le paquet qui améliorera votre main, généralement en complétant un tirage. Exemple : avec un tirage couleur, vos outs sont les cartes restantes de votre couleur.","draw":"Main qui n'est pas encore une combinaison forte mais peut le devenir avec les prochaines cartes communes, p. ex. quand il vous manque une carte pour une couleur ou une quinte.","flush-draw":"Quatre cartes de la même couleur (en main et sur le board réunis) ; il en manque une pour avoir une couleur.","straight-draw":"Quatre cartes auxquelles il en manque une pour faire une quinte. Variantes : OESD (la carte manquante peut être à l'un des deux bouts) et gutshot (la carte manque au milieu).","oesd":"Abréviation de open-ended straight draw : tirage quinte formé de quatre cartes consécutives, complété par une carte à l'un ou l'autre bout, p. ex. 5-6-7-8 attend un quatre ou un neuf.","gutshot":"Tirage quinte auquel il manque une valeur précise au milieu, p. ex. 5-6-8-9 n'attend qu'un sept.","backdoor":"Tirage au flop qui a besoin de deux cartes favorables d'affilée, au turn et à la river, p. ex. trois cartes de la même couleur après le flop.","pot-odds":"Rapport entre le montant que vous devez payer et le pot que vous pouvez gagner (mise adverse comprise). Il indique à quelle fréquence vous devez gagner pour que suivre soit rentable.","implied-odds":"La cote du pot augmentée des jetons que vous comptez gagner sur les streets suivantes si vous touchez votre main.","equity":"Votre chance de remporter le pot si toutes les cartes restantes étaient distribuées sans autres enchères ; généralement exprimée en pourcentage.","equity-realization":"La mesure dans laquelle une main transforme son équité en gains quand les enchères continuent (elle peut en réaliser moins ou plus que son équité) ; cela dépend notamment de la position et de la facilité à jouer la main.","expected-value":"Le résultat moyen d'une action si on la répétait de nombreuses fois. Une action positive en moyenne rapporte sur le long terme, même si elle perd cette fois-ci.","combo":"Une combinaison précise de deux cartes avec leurs couleurs, p. ex. A♠ K♥. Compter ces combinaisons montre combien de mains d'un type donné figurent réellement dans une range.","range":"L'ensemble des mains qu'un joueur peut avoir dans une situation donnée, ou des mains avec lesquelles il ferait une action donnée.","mixed-hand":"Main avec laquelle la stratégie d'équilibre choisit tantôt une action, tantôt une autre (p. ex. parfois une relance, parfois un call) ; les deux actions sont correctes. On dit aussi qu'une telle main se joue en stratégie mixte.","open":"Entrer dans le pot avant le flop par une relance quand tous les joueurs avant vous se sont couchés.","suited":"Deux cartes privatives de la même couleur, p. ex. A♥ K♥ (notation AKs).","offsuit":"Deux cartes privatives de couleurs différentes, p. ex. A♥ K♣ (notation AKo).","pocket-pair":"Paire formée par vos deux cartes privatives, p. ex. 8♣ 8♦ avant le flop.","connectors":"Cartes privatives de valeurs voisines, p. ex. 8-7 ou 9-8 ; elles forment plus facilement une quinte.","3-bet":"La première relance d'une ouverture avant le flop ; le nom compte la grosse blinde comme première mise et l'ouverture comme deuxième.","4-bet":"Relance d'un 3-bet, c'est-à-dire la quatrième mise du tour d'enchères.","limp":"Entrer dans le pot avant le flop en se contentant de suivre la grosse blinde, quand personne n'a encore relancé.","isolation":"Relance après un ou plusieurs limps, pour jouer contre le limpeur (souvent un joueur plus faible) en tête-à-tête.","texture":"Le caractère des cartes communes : combien de couleurs il y a, si les cartes sont proches les unes des autres, s'il y a une paire. Cela détermine les mains et les tirages possibles.","dry":"Board sur lequel peu de tirages et de mains fortes sont possibles, p. ex. K♠ 7♦ 2♣.","wet":"Board sur lequel de nombreux tirages et mains fortes sont possibles, p. ex. J♥ T♥ 8♣.","rainbow":"Flop dont les trois cartes sont de trois couleurs différentes, si bien que personne n'a de tirage couleur au flop.","two-tone":"Flop dont deux cartes sont de la même couleur, si bien que des tirages couleur sont possibles.","monotone":"Flop dont les trois cartes sont de la même couleur, si bien qu'une couleur peut déjà être faite.","paired":"Board sur lequel il y a une paire (deux cartes de même valeur), p. ex. 8-8-3.","connected":"Board sur lequel quelqu'un a déjà pu faire une quinte, p. ex. 9-8-7.","disconnected":"Board aux cartes éloignées les unes des autres, avec lequel il est difficile de former une quinte ou un tirage quinte, p. ex. K-7-2.","semi-connected":"Board sur lequel il existe des tirages quinte, mais où aucune quinte n'est encore possible, p. ex. T-8-3 (classification adoptée dans ce cours).","wetness":"Le degré auquel un board favorise les tirages et les mains fortes : de sec à wet. On parle aussi du degré de coordination du board.","top-pair":"Paire formée avec la carte la plus haute du board, p. ex. K♠ Q♦ sur un flop K-7-2.","second-pair":"Paire formée avec la deuxième carte la plus haute du board, p. ex. 7♠ 6♠ sur un flop K-7-2.","overpair":"Paire servie supérieure à toutes les cartes du board, p. ex. Q-Q sur un flop J-7-2.","c-bet":"Mise de continuation : mise du joueur qui était l'agresseur au tour précédent, p. ex. une mise au flop après avoir ouvert au preflop.","aggressor":"Le joueur qui a misé ou relancé en dernier au tour d'enchères précédent.","initiative":"Le rôle du dernier agresseur : c'est généralement lui qui fait la mise suivante.","range-advantage":"Situation où la range d'un joueur a, sur un board donné, une équité totale supérieure à celle de la range adverse.","nuts-advantage":"Situation où un joueur a proportionnellement plus de mains parmi les plus fortes dans sa range que l'adversaire.","nuts":"La main la plus forte possible sur un board donné à un moment donné. Exemple : sur le board K♥ 9♥ 4♥ 2♣, c'est la couleur à l'as de cœur.","polarized":"Se dit d'une range composée surtout de mains très fortes et de bluffs, presque sans mains moyennes.","polarization":"Construire une range à partir des extrêmes : mains fortes pour la value et bluffs, sans mains moyennes.","linear":"Se dit d'une range construite par le haut, des mains les plus fortes vers le bas, sans groupe de bluffs à part. On rencontre aussi le terme apparenté « merged range » (range non polarisée) ; selon les analyses de solveur publiées, merged est une forme intermédiaire entre cette range et une range polarisée.","condensed":"Se dit d'une range sans les mains les plus fortes (plafonnée) et composée surtout de mains moyennes ; le contraire d'une range polarisée.","value":"Miser avec une main forte pour que l'adversaire suive avec une main plus faible.","value-bet":"Une seule mise pour la value : faite avec une main forte pour que des mains plus faibles la suivent.","bluff":"Mise avec une main faible qui a peu de chances de gagner au showdown, pour que l'adversaire couche une meilleure main.","semi-bluff":"Mise avec une main encore faible mais qui peut s'améliorer (p. ex. avec un tirage) : vous gagnez si l'adversaire se couche ou si vous touchez.","blocker":"Carte de votre main qui réduit la probabilité que l'adversaire ait certaines mains. Exemple : si vous avez l'as de cœur, l'adversaire ne peut pas avoir la couleur à l'as de cœur.","bluff-catcher":"Main qui ne bat que les bluffs de l'adversaire et perd contre ses mises de value.","barrel":"Nouvelle mise au tour d'enchères suivant, après votre propre mise au tour précédent.","second-barrel":"Deuxième mise d'affilée : après un c-bet au flop, le joueur mise de nouveau au turn.","probe-bet":"Mise au turn du joueur hors de position après que l'agresseur preflop a checké le flop au lieu de faire un c-bet.","donk-bet":"Mise d'un joueur qui mise avant que l'agresseur du tour précédent ait pu agir.","overbet":"Mise après le flop supérieure à la totalité du pot.","effective-stack":"Dans une main entre deux joueurs : le plus petit de leurs deux stacks, c'est-à-dire le maximum qui peut réellement être gagné ou perdu. Avec plusieurs joueurs, on le calcule séparément pour chaque paire.","spr":"Le stack effectif divisé par le pot au début d'une street (pour planifier la main, on le calcule au flop) ; il indique la profondeur des stacks par rapport au pot (plus le SPR est bas, plus vite tout finit dans le pot).","mdf":"La plus petite part de la range qu'il faut défendre face à une mise pour qu'un bluff adverse avec une main sans chance ne soit pas automatiquement rentable.","alpha":"La fréquence à laquelle l'adversaire doit se coucher pour qu'un bluff avec une main sans chance ne soit ni gagnant ni perdant ; elle dépend de la taille de la mise par rapport au pot.","variance":"La dispersion des résultats autour de l'espérance de gain : même en jouant bien, les courtes séries peuvent être fortement négatives ou positives.","buy-in":"Le montant à payer pour entrer dans un tournoi ou s'asseoir à une table de cash game.","bankroll":"Toute la réserve consacrée uniquement au poker ; dans cette application, elle se compte en buy-ins, pas en argent.","tilt":"État dans lequel les émotions (colère, frustration, euphorie) dégradent vos décisions à la table.","winrate":"Résultat moyen d'un joueur sur un long échantillon ; en cash game, généralement en bb/100, c'est-à-dire en grosses blindes pour cent mains.","downswing":"Période de résultats nettement moins bons, généralement des pertes plus fortes que ce que justifierait le niveau de jeu ; le contraire d'un upswing.","session":"Une séance de poker, du début à la fin du jeu.","stakes":"Le niveau des blindes en cash game ou du buy-in en tournoi ; les « micro-limites » sont les niveaux les plus bas.","standard-deviation":"Mesure de la dispersion des résultats (racine carrée de la variance) ; au poker, généralement exprimée en bb/100.","risk-of-ruin":"Probabilité de perdre un jour toute votre bankroll si vous continuez à jouer à la même limite.","mental-game":"Le côté psychologique du poker : gérer le tilt, les émotions et la concentration à la table.","tournament":"Format de jeu où les blindes augmentent à intervalles réguliers et où la partie dure jusqu'à ce qu'un joueur ait tous les jetons ; les mieux classés reçoivent des prix.","push-fold":"Stratégie simplifiée pour les short stacks : avant le flop, soit on part all-in, soit on se couche.","shove":"Le fait de partir all-in, généralement sous forme de relance avant le flop.","icm":"Modèle qui convertit les jetons de tournoi en valeur monétaire en tenant compte de la structure des gains et des stacks de tous les joueurs.","bubble":"Phase d'un tournoi juste avant les places payées, quand il ne reste que quelques joueurs à éliminer avant d'atteindre les prix.","bubble-factor":"Indicateur issu de l'ICM : à quel point, en tournoi, perdre un nombre de jetons fait plus mal que gagner le même nombre ne fait du bien.","cover":"Avoir au moins autant de jetons que l'adversaire. Quand un adversaire vous couvre, perdre un all-in contre lui met fin à votre tournoi.","risk-premium":"Équité supplémentaire, au-delà de ce qu'exige la cote du pot, nécessaire en tournoi pour risquer un all-in, car perdre coûte plus que gagner ne rapporte.","m-ratio":"Le stack divisé par la somme des blindes et des antes d'une main : le nombre de tours de table complets (orbites) que vos jetons permettent de tenir sans jouer.","red-zone":"Zone de M très bas : il ne reste guère que le choix entre all-in et se coucher.","green-zone":"Zone de M élevé : le stack permet de jouer librement, de façon prudente ou agressive.","ante":"Petite contribution obligatoire au pot versée avant la donne par tous les joueurs (surtout en tournoi).","bb-ante":"Format d'ante dans lequel, au lieu de tous les joueurs, c'est le joueur en grosse blinde qui paie l'ante pour toute la table.","fold-equity":"Part de la valeur d'une action qui vient de la possibilité que l'adversaire se couche.","gap-concept":"Principe selon lequel il faut une main plus forte pour suivre une ouverture que pour ouvrir soi-même.","chip-ev":"Espérance de gain d'une action comptée en jetons, sans les convertir en argent (sans ICM).","tournament-equity":"Votre part attendue du prize pool compte tenu de la structure des gains et des stacks. On l'appelle aussi « $EV ».","prize-pool":"Somme d'argent à répartir entre les joueurs primés d'un tournoi.","payout":"Le prix attribué à une place précise dans un tournoi ; l'ensemble forme la répartition des prix.","pay-jump":"Différence de gains entre deux places voisines d'un tournoi ; les gros sauts augmentent la prime de risque.","final-table":"La dernière table d'un tournoi, où se jouent les plus gros prix.","short-stack":"Stack petit par rapport aux blindes ; en tournoi, généralement un stack qui ne représente plus que peu de grosses blindes.","nash-equilibrium":"Ensemble de stratégies dans lequel aucun joueur ne peut gagner en modifiant uniquement sa propre stratégie.","overcall":"Suivre une mise qu'un joueur avant vous a déjà suivie.","heads-up":"Jeu en tête-à-tête : il ne reste que deux joueurs à la table ou dans la main.","dead-money":"Jetons du pot provenant de joueurs qui ne peuvent plus le gagner, p. ex. de ceux qui se sont couchés.","stack-off":"Mettre tout son stack dans le pot au cours d'une main, c'est-à-dire partir all-in ou suivre un all-in.","exploit":"Écart volontaire par rapport à la stratégie de base pour profiter d'une erreur précise d'un adversaire ou de l'ensemble des joueurs.","hud":"Affichage superposé à la table en ligne, qui montre les statistiques des adversaires sur les mains jouées précédemment.","vpip":"Statistique du HUD : le pourcentage de mains où un joueur met volontairement de l'argent dans le pot avant le flop (en suivant ou en relançant).","pfr":"Statistique du HUD : le pourcentage de mains où un joueur relance avant le flop.","wtsd":"Statistique du HUD : la fréquence à laquelle un joueur qui a vu le flop va jusqu'au showdown.","nit":"Joueur très serré qui n'entre dans le pot pratiquement qu'avec des mains fortes.","regular":"Habitué d'une limite donnée, qui joue beaucoup de mains ; dans ce cours, il est opposé au joueur récréatif.","tag":"Style serré-agressif : peu de mains, mais jouées agressivement (mises et relances).","lag":"Style large-agressif : beaucoup de mains, jouées agressivement.","recreational":"Joueur qui joue pour le plaisir et généralement moins bien que les habitués ; en argot, péjorativement, « fish ».","calling-station":"Terme péjoratif pour un joueur qui suit très souvent, même avec des mains faibles ou des tirages.","maniac":"Terme péjoratif pour un joueur très large et agressif, qui mise et relance avec n'importe quoi.","rake":"Commission que le casino ou la salle en ligne prélève sur le pot pour organiser la partie.","rake-cap":"Montant maximal de rake qu'une salle peut prélever sur une seule main."},
  "it": {"royal-flush":"La combinazione più alta del poker: asso, re, donna, fante e dieci dello stesso seme, ad es. A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Cinque carte consecutive dello stesso seme, ad es. 5♥ 6♥ 7♥ 8♥ 9♥. La versione più alta (dall'asso al dieci) ha un nome a parte ed è la combinazione più forte del gioco.","four-of-a-kind":"Quattro carte dello stesso valore, ad es. quattro sette. Se due giocatori hanno un poker dello stesso valore, vince la quinta carta più alta (il kicker).","full-house":"Un tris e una coppia nella stessa combinazione, ad es. tre donne e due cinque. Tra due full vince quello con il tris più alto.","flush":"Cinque carte dello stesso seme (♠, ♥, ♦ o ♣) che non sono in sequenza. Tra due colori vince quello con la carta più alta; a parità, decide la carta successiva.","straight":"Cinque carte consecutive, non tutte dello stesso seme, ad es. 5-6-7-8-9. L'asso può essere la carta più alta (A-K-Q-J-T) o la più bassa (A-2-3-4-5).","three-of-a-kind":"Tre carte dello stesso valore e due carte diverse. Nell'hold'em ha due varianti con un nome proprio: il set, quando la coppia è in mano e la terza carta è sul board, e i trips, quando la coppia è sul board e la terza carta è in mano.","set":"Tris formato da una coppia in mano e da una carta sul board, ad es. 7♣ 7♦ su un flop K-7-2.","two-pair":"Due coppie diverse e una quinta carta, ad es. K-K-8-8-3. In caso di parità decide prima la coppia più alta, poi quella più bassa e infine la quinta carta.","pair":"Due carte dello stesso valore e tre carte diverse, ad es. due nove. È più debole solo la carta alta.","high-card":"Combinazione senza coppia né niente di meglio; la forza dipende dalla carta più alta e, a parità, dalle successive.","kicker":"La carta più alta fuori dalla combinazione, che decide in caso di parità. Esempio: una coppia d'assi con il re batte una coppia d'assi con la donna.","wheel":"La scala più bassa: A-2-3-4-5, in cui l'asso conta come carta più bassa.","check":"Continuare senza mettere fiches, possibile solo quando non devi aggiungere nulla: in questo giro di puntate nessuno ha ancora puntato (prima del flop può farlo il big blind, se nessuno ha rilanciato). Da non confondere con il call, cioè aggiungere fiches per pareggiare la puntata dell'avversario.","bet":"Le prime fiches messe in un giro di puntate in cui nessuno ha ancora puntato (in senso più ampio si chiama puntata qualsiasi quantità di fiches messa nel piatto).","call":"Mettere nel piatto l'importo della puntata o del rilancio dell'avversario per continuare a giocare. Da non confondere con il check, cioè continuare senza puntare quando nessuno ha puntato.","raise":"Alzare l'importo oltre la puntata dell'avversario; gli altri devono aggiungere la differenza, rilanciare ancora o fare fold.","fold":"Rinunciare alla mano: butti le carte e perdi ciò che hai già messo nel piatto.","check-raise":"Prima fai check e, quando l'avversario punta, lo rilanci nello stesso giro di puntate.","all-in":"Puntare tutte le tue fiches. Da ogni avversario puoi vincere al massimo quanto hai messo tu; per il resto si gioca nel piatto secondario.","pot":"Tutte le fiches puntate nella mano in corso. Le prende il giocatore con la combinazione migliore allo showdown (con piatti secondari, ogni piatto si assegna separatamente) oppure il giocatore rimasto quando tutti gli altri hanno fatto fold.","side-pot":"Un piatto separato che si crea quando qualcuno è all-in: se lo giocano solo i giocatori che hanno messo più del giocatore all-in, quindi lui non può vincerlo.","split-pot":"Situazione in cui i giocatori con combinazioni uguali si dividono il piatto, ad es. quando entrambi giocano la stessa scala presente sul board.","playing-the-board":"Situazione in cui la tua migliore combinazione di cinque carte è fatta solo di carte comuni; le tue carte personali non aggiungono nulla, quindi nel migliore dei casi dividi il piatto.","board":"Le carte comuni scoperte al centro (flop, turn, river) che usano tutti i giocatori. Indica le carte, non il tavolo da gioco.","community-cards":"Carte scoperte al centro che ogni giocatore può usare per la propria combinazione; nell'hold'em sono cinque.","hole-cards":"Le due carte coperte che ricevi all'inizio della mano nell'hold'em; le vedi solo tu.","small-blind":"La puntata obbligatoria più piccola, versata prima della distribuzione dal giocatore alla sinistra del Button (in due giocatori, dal Button stesso); si chiama così anche quel posto al tavolo.","big-blind":"La puntata obbligatoria più grande, versata prima della distribuzione dal secondo giocatore alla sinistra del Button (in due giocatori, dal giocatore di fronte al Button); si chiama così anche quel posto. Serve anche come unità di misura per stack e risultati.","chips":"I gettoni con cui si gioca al tavolo; nel cash game rappresentano denaro, nei tornei punti di torneo.","stack":"Tutte le fiches che un giocatore ha davanti a sé; di solito si indicano in big blind (ad es. 100 big blind).","street":"Nome gergale del giro di puntate: preflop, flop, turn e river sono le quattro street. Esempio: «value su tre street» significa puntate per valore al flop, al turn e al river.","betting-round":"Fase della mano in cui i giocatori, a turno, fanno check, puntano, fanno call, rilanciano o fanno fold; nell'hold'em sono quattro: preflop, flop, turn e river.","preflop":"Il primo giro di puntate: dopo la distribuzione delle carte personali, prima che arrivi il flop.","flop":"Le prime tre carte comuni, scoperte insieme dopo le puntate preflop; si chiama così anche il secondo giro di puntate.","turn":"La quarta carta comune e il terzo giro di puntate.","river":"La quinta e ultima carta comune e l'ultimo giro di puntate prima dello showdown.","showdown":"La scoperta delle carte dopo l'ultimo giro di puntate, quando nella mano restano almeno due giocatori; il piatto va alla combinazione migliore.","position":"Il tuo posto al tavolo rispetto al Button, che stabilisce l'ordine di azione. Chi agisce più tardi vede più azioni degli avversari prima di decidere.","in-position":"Situazione del giocatore che dopo il flop agisce per ultimo, quindi vede l'azione dell'avversario prima di decidere.","out-of-position":"Situazione del giocatore che dopo il flop agisce prima dell'avversario, quindi decide senza conoscerne l'azione.","early-position":"I primi posti ad agire prima del flop (ad es. UTG); dopo di te devono ancora agire molti giocatori.","late-position":"I posti che agiscono per ultimi: il Button e i posti subito prima, soprattutto il Cutoff.","utg":"Il primo giocatore ad agire prima del flop, seduto subito alla sinistra del big blind.","hijack":"Il posto subito prima del Cutoff, cioè il secondo alla destra del Button.","cutoff":"Il posto subito alla destra del Button, che agisce appena prima di lui.","button":"Il posto del mazziere, segnato da un dischetto «dealer». Dopo il flop agisce per ultimo in ogni giro di puntate.","outs":"Una carta ancora nel mazzo che migliora la tua mano, di solito completando un progetto. Esempio: con un progetto di colore, i tuoi out sono le carte rimanenti del tuo seme.","draw":"Una mano che non è ancora una combinazione forte ma può diventarlo con le prossime carte comuni, ad es. quando ti manca una carta per il colore o la scala.","flush-draw":"Quattro carte dello stesso seme (in mano e sul board insieme); te ne manca una per fare colore.","straight-draw":"Quattro carte a cui ne manca una per fare scala. Varianti: OESD (manca una carta a una delle due estremità) e gutshot (manca una carta in mezzo).","oesd":"Abbreviazione di open-ended straight draw: progetto di scala di quattro carte consecutive, completato da una carta a entrambe le estremità, ad es. 5-6-7-8 aspetta un quattro o un nove.","gutshot":"Progetto di scala a cui manca un solo valore preciso in mezzo, ad es. 5-6-8-9 aspetta solo un sette.","backdoor":"Progetto al flop che ha bisogno di due carte utili di fila, al turn e al river, ad es. tre carte dello stesso seme dopo il flop.","pot-odds":"Il rapporto tra l'importo che devi mettere e il piatto che puoi vincere (compresa la puntata dell'avversario). Ti dice quanto spesso devi vincere perché il call sia conveniente.","implied-odds":"Pot odds aumentate delle fiches che ti aspetti di vincere nelle street successive se chiudi la tua combinazione.","equity":"La tua probabilità di vincere il piatto se tutte le carte rimanenti venissero scoperte senza altre puntate; di solito in percentuale.","equity-realization":"Quanto una mano trasforma la sua equity in vincita quando le puntate continuano (può realizzare meno o più della sua equity); dipende tra l'altro dalla posizione e da quanto è facile giocare la mano.","expected-value":"Il risultato medio di una giocata se la ripetessi molte volte. Una giocata in positivo in media guadagna nel lungo periodo, anche se questa volta perde.","combo":"Una specifica combinazione di due carte con i semi, ad es. A♠ K♥. Contare queste combinazioni mostra quante mani di un certo tipo ci sono davvero in un range.","range":"L'insieme di tutte le mani che un giocatore può avere in una data situazione, oppure delle mani con cui farebbe una data giocata.","mixed-hand":"Una mano con cui la strategia di equilibrio sceglie a volte una giocata, a volte un'altra (ad es. a volte rilancio, a volte call); entrambe le giocate sono corrette. Si dice anche che la mano si gioca con una strategia mista.","open":"Entrare nel piatto prima del flop con un rilancio quando tutti prima di te hanno fatto fold.","suited":"Due carte personali dello stesso seme, ad es. A♥ K♥ (si scrive AKs).","offsuit":"Due carte personali di semi diversi, ad es. A♥ K♣ (si scrive AKo).","pocket-pair":"Una coppia formata dalle due carte personali, ad es. 8♣ 8♦ prima del flop.","connectors":"Carte personali di valori adiacenti, ad es. 8-7 o 9-8; con esse è più facile fare scala.","3-bet":"Il primo rilancio di un'apertura prima del flop; il nome conta il big blind come prima puntata e l'apertura come seconda.","4-bet":"Il rilancio di un 3-bet, cioè la quarta puntata del giro di puntate.","limp":"Entrare nel piatto prima del flop solo pareggiando il big blind, quando nessuno ha ancora rilanciato.","isolation":"Un rilancio dopo uno o più limp, per giocare contro il limper (spesso un giocatore più debole) uno contro uno.","texture":"Il carattere delle carte comuni: quanti semi ci sono, se le carte sono vicine tra loro, se c'è una coppia. Da questo dipende quali combinazioni e progetti sono possibili.","dry":"Un board su cui sono possibili pochi progetti e poche combinazioni forti, ad es. K♠ 7♦ 2♣.","wet":"Un board su cui sono possibili molti progetti e molte combinazioni forti, ad es. J♥ T♥ 8♣.","rainbow":"Un flop con tre carte di tre semi diversi, quindi al flop nessuno ha un progetto di colore.","two-tone":"Un flop con due carte dello stesso seme, quindi sono possibili progetti di colore.","monotone":"Un flop con tre carte dello stesso seme, quindi il colore può essere già fatto.","paired":"Un board su cui c'è una coppia (due carte dello stesso valore), ad es. 8-8-3.","connected":"Un board su cui qualcuno può aver già fatto scala, ad es. 9-8-7.","disconnected":"Un board con carte lontane tra loro, con cui è difficile fare una scala o un progetto di scala, ad es. K-7-2.","semi-connected":"Un board con progetti di scala, ma su cui la scala non è ancora possibile, ad es. T-8-3 (classificazione adottata nel corso).","wetness":"Quanto un board favorisce progetti e combinazioni forti: da secco a bagnato. Si parla anche di quanto il board è coordinato.","top-pair":"Una coppia con la carta più alta del board, ad es. K♠ Q♦ su un flop K-7-2.","second-pair":"Una coppia con la seconda carta più alta del board, ad es. 7♠ 6♠ su un flop K-7-2.","overpair":"Una coppia servita più alta di ogni carta del board, ad es. Q-Q su un flop J-7-2.","c-bet":"Puntata di continuazione: la puntata del giocatore che era l'aggressore nel giro precedente, ad es. una puntata al flop dopo un'apertura preflop.","aggressor":"Il giocatore che per ultimo ha puntato o rilanciato nel giro di puntate precedente.","initiative":"Il ruolo dell'ultimo aggressore: di solito è lui a fare la puntata successiva.","range-advantage":"Situazione in cui il range di un giocatore ha, su un dato board, un'equity complessiva maggiore del range dell'avversario.","nuts-advantage":"Situazione in cui un giocatore ha nel range, in proporzione, più mani fortissime dell'avversario.","nuts":"La mano più forte possibile su un dato board in un dato momento. Esempio: sul board K♥ 9♥ 4♥ 2♣ è il colore all'asso di cuori.","polarized":"Detto di un range: composto soprattutto da mani molto forti e da bluff, quasi senza mani medie.","polarization":"Costruire un range dagli estremi: mani forti per valore e bluff, senza mani medie.","linear":"Detto di un range: costruito dall'alto, dalle mani più forti in giù, senza un gruppo separato di bluff. Si incontra anche il termine affine «merged range» (range non polarizzato); secondo le analisi pubblicate con i solver, merged è una forma intermedia tra questo range e quello polarizzato.","condensed":"Detto di un range: senza le mani più forti (limitato dall'alto) e composto soprattutto da mani medie; il contrario di polarizzato.","value":"Puntare con una mano forte perché l'avversario faccia call con una mano più debole.","value-bet":"Una singola puntata per valore: fatta con una mano forte perché la chiamino mani più deboli.","bluff":"Una puntata con una mano debole che difficilmente vincerà allo showdown, per far fare fold all'avversario con una mano migliore.","semi-bluff":"Una puntata con una mano ancora debole ma che può migliorare (ad es. con un progetto): vinci se l'avversario fa fold oppure se chiudi il progetto.","blocker":"Una carta nella tua mano che riduce la probabilità che l'avversario abbia certe mani. Esempio: se hai l'asso di cuori, l'avversario non può avere il colore all'asso di cuori.","bluff-catcher":"Una mano che batte solo i bluff dell'avversario e perde contro le sue puntate per valore.","barrel":"Un'altra puntata nel giro di puntate successivo, dopo la tua puntata nel giro precedente.","second-barrel":"La seconda puntata di fila: dopo una c-bet al flop, il giocatore punta di nuovo al turn.","probe-bet":"Una puntata al turn del giocatore fuori posizione dopo che l'aggressore preflop ha fatto check al flop invece di fare una c-bet.","donk-bet":"Una puntata di un giocatore che punta prima che l'aggressore del giro precedente abbia potuto agire.","overbet":"Una puntata dopo il flop più grande dell'intero piatto.","effective-stack":"In una mano tra due giocatori: il più piccolo dei loro stack, cioè il massimo che si può realmente vincere o perdere. Con più giocatori si calcola separatamente per ogni coppia.","spr":"Lo stack effettivo diviso per il piatto all'inizio di una street (per pianificare la mano si calcola al flop); indica quanto sono profondi gli stack rispetto al piatto (più basso è l'SPR, più in fretta tutto finisce nel piatto).","mdf":"La parte più piccola del range che devi difendere contro una puntata perché il bluff dell'avversario con una mano senza possibilità non sia automaticamente conveniente.","alpha":"Quanto spesso l'avversario deve fare fold perché un bluff con una mano senza possibilità vada in pareggio; dipende dalla dimensione della puntata rispetto al piatto.","variance":"La dispersione dei risultati attorno al valore atteso: anche giocando bene, brevi serie possono essere molto in negativo o in positivo.","buy-in":"L'importo per entrare in un torneo o per sedersi a un tavolo cash.","bankroll":"Tutta la riserva destinata esclusivamente al poker; in questa app si conta in buy-in, non in denaro.","tilt":"Uno stato in cui le emozioni (rabbia, frustrazione, euforia) peggiorano le tue decisioni al tavolo.","winrate":"Il risultato medio di un giocatore su un campione lungo; nel cash game di solito in bb/100, cioè big blind ogni cento mani.","downswing":"Un periodo di risultati nettamente peggiori, di solito perdite più grandi di quanto farebbe pensare l'abilità; il contrario dell'upswing.","session":"Una singola seduta di poker, da quando inizi a giocare a quando smetti.","stakes":"L'entità dei blind nel cash game o del buy-in nei tornei; i «microlimiti» sono i livelli più bassi.","standard-deviation":"Misura della dispersione dei risultati (la radice quadrata della varianza); nel poker di solito si indica in bb/100.","risk-of-ruin":"La probabilità di perdere prima o poi tutto il bankroll, se continui a giocare allo stesso limite.","mental-game":"Il lato psicologico del poker: gestire il tilt, le emozioni e la concentrazione al tavolo.","tournament":"Formato di gioco in cui i blind aumentano a intervalli e si gioca finché un giocatore non ha tutte le fiches; i premi vanno ai meglio classificati.","push-fold":"Strategia semplificata per short stack: prima del flop si va all-in oppure si fa fold.","shove":"Una giocata all-in, di solito come rilancio prima del flop.","icm":"Un modello che converte le fiches del torneo in valore monetario, tenendo conto della struttura dei premi e degli stack di tutti i giocatori.","bubble":"La fase del torneo subito prima dei posti a premio, quando mancano poche eliminazioni per arrivare ai premi.","bubble-factor":"Un indicatore dell'ICM: quanto in un torneo perdere un certo numero di fiches fa più male di quanto faccia bene vincerne lo stesso numero.","cover":"Avere almeno tante fiches quante l'avversario. Se un avversario ti copre, perdere un all-in contro di lui chiude il tuo torneo.","risk-premium":"Equity extra oltre quella richiesta dalle pot odds, necessaria in un torneo per rischiare un all-in, perché perdere costa più di quanto vincere faccia guadagnare.","m-ratio":"Lo stack diviso per la somma di blind e ante di una mano: per quanti giri completi (orbite) bastano le fiches senza giocare.","red-zone":"La zona di M molto basso: restano soprattutto l'all-in o il fold.","green-zone":"La zona di M alto: lo stack ti permette di giocare liberamente, in modo prudente o aggressivo.","ante":"Un piccolo versamento obbligatorio nel piatto prima della distribuzione, da parte di tutti i giocatori (soprattutto nei tornei).","bb-ante":"Un formato di ante in cui, invece di tutti i giocatori, è il giocatore di big blind a versare l'ante per tutto il tavolo.","fold-equity":"La parte del valore di una giocata che deriva dalla possibilità che l'avversario faccia fold.","gap-concept":"Il principio secondo cui per fare call contro un'apertura serve una mano più forte che per aprire.","chip-ev":"Il valore atteso di una giocata calcolato in fiches, senza convertirle in denaro (senza ICM).","tournament-equity":"La tua quota attesa del montepremi, data la struttura dei premi e gli stack. Si chiama anche «$EV».","prize-pool":"La somma di denaro da dividere tra i giocatori premiati di un torneo.","payout":"Il premio per un determinato piazzamento in un torneo; tutti insieme formano la distribuzione dei premi.","pay-jump":"La differenza di premio tra piazzamenti consecutivi in un torneo; salti grandi aumentano il risk premium.","final-table":"L'ultimo tavolo di un torneo, dove si giocano i premi più alti.","short-stack":"Uno stack piccolo rispetto ai blind; nei tornei di solito uno con pochi big blind rimasti.","nash-equilibrium":"Un insieme di strategie in cui nessun giocatore guadagna cambiando soltanto la propria strategia.","overcall":"Fare call a una puntata che qualcuno prima di te ha già chiamato.","heads-up":"Gioco uno contro uno: al tavolo o nella mano sono rimasti solo due giocatori.","dead-money":"Fiches nel piatto di giocatori che non possono più vincerlo, ad es. di quelli che hanno fatto fold.","stack-off":"Mettere nel piatto tutto lo stack in una sola mano, cioè andare all-in o fare call a un all-in.","exploit":"Un allontanamento consapevole dalla strategia di base per sfruttare un errore specifico di un avversario o dell'intera popolazione di giocatori.","hud":"Un overlay sul tavolo nel gioco online che mostra le statistiche degli avversari dalle mani giocate in precedenza.","vpip":"Statistica dell'HUD: in quale percentuale di mani un giocatore mette volontariamente denaro nel piatto prima del flop (call o rilancio).","pfr":"Statistica dell'HUD: in quale percentuale di mani un giocatore rilancia prima del flop.","wtsd":"Statistica dell'HUD: quanto spesso un giocatore che ha visto il flop arriva allo showdown.","nit":"Un giocatore molto tight, che entra nel piatto quasi solo con mani forti.","regular":"Un frequentatore abituale di un dato limite che gioca un grande volume di mani; nel corso è contrapposto al giocatore ricreativo.","tag":"Stile tight-aggressivo: poche mani, ma giocate in modo aggressivo (puntate e rilanci).","lag":"Stile loose-aggressivo: molte mani, giocate in modo aggressivo.","recreational":"Un giocatore che gioca per divertimento ed è di solito più debole dei regular; nel gergo, in modo dispregiativo, «fish».","calling-station":"Termine dispregiativo per un giocatore che fa call molto spesso, anche con mani deboli o progetti.","maniac":"Termine dispregiativo per un giocatore molto loose e aggressivo, che punta e rilancia con qualsiasi cosa.","rake":"La commissione che un casinò o una poker room online preleva dal piatto per gestire il gioco.","rake-cap":"L'importo massimo di rake che la poker room può prelevare da una singola mano."},
  "ja": {"royal-flush":"ポーカーで最も強い役です。同じスートのエース、キング、クイーン、ジャック、10の5枚で、例：A♠ K♠ Q♠ J♠ T♠。","straight-flush":"同じスートで連続する5枚のカードです。例：5♥ 6♥ 7♥ 8♥ 9♥。最も高いもの（エースから10まで）には別の名前があり、ゲームで最も強い役です。","four-of-a-kind":"同じランクのカード4枚です。例：7が4枚。同じランクのフォーカード同士では、5枚目のカード（キッカー）が高いほうが勝ちます。","full-house":"スリーカードとペアを組み合わせた役です。例：クイーン3枚と5が2枚。フルハウス同士では、スリーカードが高いほうが勝ちます。","flush":"同じスート（♠、♥、♦、♣のいずれか）の5枚で、連続していないものです。フラッシュ同士では最も高いカードが高いほうが勝ち、同じなら次に高いカードで決まります。","straight":"連続する5枚のカードで、すべてが同じスートではないものです。例：5-6-7-8-9。エースは最も高いカード（A-K-Q-J-T）にも、最も低いカード（A-2-3-4-5）にもなります。","three-of-a-kind":"同じランクのカード3枚とほかのカード2枚です。ホールデムでは別の名前を持つ2種類があります。ペアが手札にあり3枚目がボードにあるときはセット、ペアがボードにあり3枚目が手札にあるときはトリップスです。","set":"手札のペアとボードの1枚でできたスリーカードです。例：K-7-2のフロップで7♣ 7♦。","two-pair":"異なる2組のペアと5枚目のカードです。例：K-K-8-8-3。同じ場合は、まず高いほうのペア、次に低いほうのペア、最後に5枚目のカードで決まります。","pair":"同じランクのカード2枚とほかのカード3枚です。例：9が2枚。これより弱いのはハイカードだけです。","high-card":"ペア以上の組み合わせがない役です。強さは最も高いカードで決まり、同じなら次のカードで決まります。","kicker":"役に含まれないカードのうち最も高いもので、同じ役どうしの勝敗を決めます。例：エースのペアにキングがある手は、エースのペアにクイーンがある手に勝ちます。","wheel":"最も低いストレートで、A-2-3-4-5です。エースは最も低いカードとして数えます。","check":"チップを出さずにプレイを続けることです。追加で払う必要がないとき、つまりこのベッティングラウンドでまだ誰もベットしていないときだけできます（フロップ前は、誰もレイズしていなければビッグブラインドがチェックできます）。相手のベットに額を合わせるコールと混同しないでください。","bet":"まだ誰もベットしていないベッティングラウンドで、最初にチップを出すことです（広い意味では、ポットにチップを入れることすべてをベットと呼びます）。","call":"プレイを続けるために、相手のベットまたはレイズと同じ額をポットに入れることです。誰もベットしていないときにベットせずに続けるチェックと混同しないでください。","raise":"相手のベットより額を引き上げることです。ほかのプレイヤーは差額を出すか、さらにレイズするか、フォールドしなければなりません。","fold":"そのハンドを降りることです。カードを捨て、すでにポットに入れたチップは失います。","check-raise":"まずチェックし、相手がベットしたら、同じベッティングラウンドでレイズすることです。","all-in":"自分のチップをすべて賭けることです。各相手から勝てるのは最大で自分が入れた額までで、残りはサイドポットで争われます。","pot":"現在のハンドで賭けられたチップすべてです。ショーダウンで最も強い役のプレイヤー（サイドポットがあればポットごとに別々に決まります）か、ほかの全員がフォールドしたときに残ったプレイヤーが獲得します。","side-pot":"誰かがオールインしたときにできる別のポットです。オールインしたプレイヤーより多く入れたプレイヤーだけがこれを争うため、オールインしたプレイヤー自身は獲得できません。","split-pot":"同じ強さの役を持つプレイヤーがポットを分け合う状況です。例：2人ともボード上の同じストレートでプレイしている場合。","playing-the-board":"自分の最も強い5枚の役がコミュニティカードだけでできている状況です。ホールカードが何も加えないため、よくてもポットを分け合うことになります。","board":"中央に表向きに置かれ、全プレイヤーが使うコミュニティカード（フロップ、ターン、リバー）です。プレイする卓（テーブル）ではなく、カードのことを指します。","community-cards":"中央に表向きに配られ、どのプレイヤーも自分の役に使えるカードです。ホールデムでは5枚あります。","hole-cards":"ホールデムでハンドの最初に配られる裏向きの2枚のカードです。見られるのは自分だけです。","small-blind":"配る前に、ボタンの左隣のプレイヤー（2人のときはボタン自身）が出す小さいほうの強制ベットです。その席もこう呼びます。","big-blind":"配る前に、ボタンから左に2番目のプレイヤー（2人のときはボタンの相手）が出す大きいほうの強制ベットです。その席もこう呼びます。スタックの大きさや成績の単位にも使われます。","chips":"テーブルでプレイに使う円盤です。キャッシュゲームではお金を、トーナメントではトーナメントのポイントを表します。","stack":"プレイヤーが目の前に持っているチップすべてです。通常はビッグブラインドの数で表します（例：100ビッグブラインド）。","street":"ベッティングラウンドの俗称で、プリフロップ、フロップ、ターン、リバーが4つのストリートです。例：「3ストリートでバリュー」とは、フロップ、ターン、リバーでバリューのためにベットすることです。","betting-round":"プレイヤーが順番にチェック、ベット、コール、レイズ、フォールドするハンドの段階です。ホールデムではプリフロップ、フロップ、ターン、リバーの4つがあります。","preflop":"最初のベッティングラウンドです。ホールカードが配られた後、フロップが出る前に行います。","flop":"プリフロップのベットの後にまとめて配られる最初の3枚のコミュニティカードです。2番目のベッティングラウンドもこう呼びます。","turn":"4枚目のコミュニティカードで、3番目のベッティングラウンドでもあります。","river":"5枚目で最後のコミュニティカードで、ショーダウン前の最後のベッティングラウンドでもあります。","showdown":"最後のベットの後、2人以上のプレイヤーが残っているときにカードを公開することです。最も強い役がポットを獲得します。","position":"ボタンを基準にしたテーブル上の席で、アクションの順番を決めます。後にアクションするプレイヤーほど、判断の前に相手のプレイを多く見られます。","in-position":"フロップ後に最後にアクションするプレイヤーの状況です。判断の前に相手のプレイを見られます。","out-of-position":"フロップ後に相手より先にアクションするプレイヤーの状況です。相手のプレイを知らずに判断します。","early-position":"フロップ前に最初にアクションする席です（例：UTG）。後ろにまだ多くのプレイヤーがいます。","late-position":"最後にアクションする席で、ボタンとそのすぐ前の席、特にカットオフです。","utg":"フロップ前に最初にアクションするプレイヤーで、ビッグブラインドのすぐ左に座ります。","hijack":"カットオフのすぐ前、つまりボタンから右に2番目の席です。","cutoff":"ボタンのすぐ右の席で、ボタンの直前にアクションします。","button":"「ディーラー」の円盤で示されるディーラーの席です。フロップ後はすべてのベッティングラウンドで最後にアクションします。","outs":"まだデッキに残っていて、自分の手を強くするカードです。多くの場合、ドローを完成させます。例：フラッシュドローなら、自分のスートの残りのカードがアウツです。","draw":"まだ強い役ではないものの、次のコミュニティカードで強い役になりうる手です。例：フラッシュやストレートにあと1枚足りないとき。","flush-draw":"同じスートのカードが4枚（手札とボードを合わせて）ある状態です。フラッシュにはあと1枚必要です。","straight-draw":"ストレートにあと1枚足りない4枚のカードです。種類はOESD（両端のどちらかのカードが足りない）とガットショット（中のカードが足りない）です。","oesd":"open-ended straight drawの略です。連続する4枚のストレートドローで、両端どちらのカードでも完成します。例：5-6-7-8は4か9を待っています。","gutshot":"中の特定の1ランクが足りないストレートドローです。例：5-6-8-9は7だけを待っています。","backdoor":"ターンとリバーで続けて合うカードが2枚必要な、フロップでのドローです。例：フロップ後に同じスートが3枚ある場合。","pot-odds":"出さなければならない額と、獲得できるポット（相手のベットを含む）の比率です。コールが得になるために、どのくらいの頻度で勝つ必要があるかがわかります。","implied-odds":"役が完成したときに後のストリートで獲得できると見込めるチップを加えたポットオッズです。","equity":"これ以上ベットせずに残りのカードをすべて配った場合に、ポットを獲得できる確率です。通常はパーセントで表します。","equity-realization":"ベットが続く中で、手がエクイティをどの程度勝ちに変えられるかを示します（エクイティより少なくも多くも実現しえます）。ポジションや手のプレイしやすさなどで変わります。","expected-value":"あるプレイを何度も繰り返したときの平均的な結果です。平均でプラスになるプレイは、今回負けたとしても長期的には利益を生みます。","combo":"スートを含めた2枚のカードの具体的な組み合わせ1つです。例：A♠ K♥。これを数えると、ある手が実際にレンジにいくつあるかがわかります。","range":"ある状況でプレイヤーが持ちうるすべての手、またはあるプレイをするときの手の集まりです。","mixed-hand":"均衡戦略があるときは一方のプレイ、あるときは別のプレイを選ぶ手です（例：レイズするときもあれば、コールするときもある）。どちらのプレイも正しい選択です。こうした手は混合戦略でプレイすると言います。","open":"前のプレイヤー全員がフォールドしたとき、フロップ前にレイズでポットに参加することです。","suited":"同じスートの2枚のホールカードです。例：A♥ K♥（表記はAKs）。","offsuit":"スートが異なる2枚のホールカードです。例：A♥ K♣（表記はAKo）。","pocket-pair":"2枚のホールカードでできたペアです。例：フロップ前の8♣ 8♦。","connectors":"ランクが隣り合うホールカードです。例：8-7や9-8。ストレートを作りやすい手です。","3-bet":"フロップ前のオープンに対する最初のレイズです。ビッグブラインドを1回目、オープンを2回目のベットと数えるため、この名前になっています。","4-bet":"3ベットに対するレイズで、ベッティングラウンドで4回目のベットにあたります。","limp":"まだ誰もレイズしていないとき、フロップ前にビッグブラインドにコールするだけでポットに参加することです。","isolation":"1人以上がリンプした後にするレイズで、リンプしたプレイヤー（弱いプレイヤーであることが多い）と1対1でプレイすることを狙います。","texture":"コミュニティカードの性質です。スートがいくつあるか、カードのランクが近いか、ペアがあるかなどを指します。これによって、どの役やドローがありうるかが決まります。","dry":"ありうるドローや強い役が少ないボードです。例：K♠ 7♦ 2♣。","wet":"ありうるドローや強い役が多いボードです。例：J♥ T♥ 8♣。","rainbow":"3枚がすべて異なるスートのフロップで、フロップの時点では誰もフラッシュドローを持っていません。","two-tone":"2枚が同じスートのフロップで、フラッシュドローがありえます。","monotone":"3枚がすべて同じスートのフロップで、すでにフラッシュができている可能性があります。","paired":"ペア（同じランクのカード2枚）があるボードです。例：8-8-3。","connected":"誰かがすでにストレートを作っている可能性があるボードです。例：9-8-7。","disconnected":"カードのランクが離れていて、ストレートやストレートドローを作りにくいボードです。例：K-7-2。","semi-connected":"ストレートドローはあるものの、まだストレートはできないボードです。例：T-8-3（このコースでの分類）。","wetness":"ボードがドローや強い役をどれだけ生みやすいかの度合いで、ドライからウェットまであります。ボードがどれだけコーディネートしているか、とも表現します。","top-pair":"ボードで最も高いカードとのペアです。例：K-7-2のフロップでK♠ Q♦。","second-pair":"ボードで2番目に高いカードとのペアです。例：K-7-2のフロップで7♠ 6♠。","overpair":"ボードのどのカードよりも高いポケットペアです。例：J-7-2のフロップでQ-Q。","c-bet":"継続ベット（コンティニュエーションベット）です。前のラウンドでアグレッサーだったプレイヤーのベットで、例：プリフロップでオープンした後のフロップでのベット。","aggressor":"前のベッティングラウンドで最後にベットまたはレイズしたプレイヤーです。","initiative":"最後のアグレッサーが持つ役割で、通常は次のベットもそのプレイヤーがします。","range-advantage":"あるボードで、一方のプレイヤーのレンジが全体として相手のレンジより高いエクイティを持つ状況です。","nuts-advantage":"一方のプレイヤーのレンジに、相手より割合として多くの最も強い手が含まれる状況です。","nuts":"そのボードでその時点でありうる最も強いハンドです。例：K♥ 9♥ 4♥ 2♣のボードでは、ハートのエースを使ったフラッシュがナッツです。","polarized":"レンジについて：主にとても強い手とブラフでできていて、中くらいの手がほとんどない状態です。","polarization":"両極端でレンジを組むことです。バリューのための強い手とブラフで構成し、中くらいの手は含めません。","linear":"レンジについて：最も強い手から順に上から組まれ、ブラフの独立したグループがない状態です。関連する用語として「マージドレンジ」（ポラライズされていないレンジ）もあり、公開されたソルバー分析によれば、マージドはこのレンジとポラライズドレンジの中間の形です。","condensed":"レンジについて：最も強い手がなく（上限があり）、主に中くらいの手でできている状態です。ポラライズドの反対です。","value":"相手に弱い手でコールさせるために、強い手でベットすることです。","value-bet":"バリューのための1回のベットです。弱い手にコールさせるために、強い手で行います。","bluff":"ショーダウンでは勝てそうにない弱い手でベットし、相手に強い手をフォールドさせることです。","semi-bluff":"まだ弱いものの強くなる可能性がある手（例：ドロー）でするベットです。相手がフォールドするか、カードが当たれば勝てます。","blocker":"相手が特定の手を持つ可能性を下げる、自分の手札のカードです。例：自分がハートのエースを持っていれば、相手はハートのエースを使ったフラッシュを持てません。","bluff-catcher":"相手のブラフにだけ勝ち、相手のバリューベットには負ける手です。","barrel":"前のラウンドで自分がベットした後、次のベッティングラウンドでさらにするベットです。","second-barrel":"2回連続のベットです。フロップでCベットした後、ターンでもう一度ベットします。","probe-bet":"プリフロップのアグレッサーがフロップでCベットせずにチェックした後、アウトオブポジションのプレイヤーがターンでするベットです。","donk-bet":"前のラウンドのアグレッサーがアクションする前に、ほかのプレイヤーがするベットです。","overbet":"フロップ以降のベットで、ポット全体より大きいものです。","effective-stack":"2人のハンドでは、2人のスタックのうち小さいほうで、実際に勝ったり負けたりできる最大額です。プレイヤーが3人以上いるときは、2人の組ごとに別々に計算します。","spr":"エフェクティブスタックをストリート開始時のポットで割った値です（ハンドの計画にはフロップで計算します）。ポットに対してスタックがどれだけ深いかを示し、SPRが低いほど早くすべてがポットに入ります。","mdf":"勝ち目のない手での相手のブラフが自動的に得にならないように、ベットに対して守る必要があるレンジの最小の割合です。","alpha":"勝ち目のない手でのブラフが損益ゼロになるために、相手がフォールドしなければならない頻度です。ポットに対するベットの大きさで決まります。","variance":"期待値を中心とした結果のばらつきです。よいプレイをしていても、短い期間では大きなマイナスやプラスになることがあります。","buy-in":"トーナメント、またはキャッシュゲームのテーブルに参加するための金額です。","bankroll":"ポーカーのプレイだけに充てる資金全体です。このアプリではお金ではなく、バイインの数で数えます。","tilt":"感情（怒り、苛立ち、高揚感）のせいで、テーブルでの判断が悪くなる状態です。","winrate":"長めのサンプルでのプレイヤーの平均的な成績です。キャッシュゲームでは通常bb/100、つまり100ハンドあたりのビッグブラインドで表します。","downswing":"成績がはっきり悪い期間で、通常は実力から考えられるより大きな負けが続きます。アップスイングの反対です。","session":"ポーカーのプレイ1回分で、始めてから終えるまでです。","stakes":"キャッシュゲームのブラインドの額、またはトーナメントのバイインの額です。「マイクロステークス」は最も低いレベルです。","standard-deviation":"結果のばらつきを示す尺度（分散の平方根）です。ポーカーでは通常bb/100で表します。","risk-of-ruin":"同じステークスでプレイを続けた場合に、いつかバンクロールをすべて失う確率です。","mental-game":"ポーカーの心理面で、ティルト、感情、テーブルでの集中への対処を指します。","tournament":"一定時間ごとにブラインドが上がり、1人のプレイヤーがすべてのチップを集めるまで続く形式です。賞金は上位のプレイヤーが受け取ります。","push-fold":"ショートスタック向けの単純化した戦略で、フロップ前はオールインかフォールドのどちらかだけを選びます。","shove":"オールインするプレイで、通常はフロップ前のレイズとして行います。","icm":"賞金構造と全プレイヤーのスタックを考慮して、トーナメントのチップを金銭的な価値に換算するモデルです。","bubble":"トーナメントで入賞圏のすぐ手前の段階で、賞金圏に入るまであと数人の脱落が必要なときです。","bubble-factor":"ICMから得られる指標で、トーナメントで同じ数のチップを失う痛手が、得る利益よりどれだけ大きいかを示します。","cover":"相手と同じかそれ以上のチップを持っていることです。相手にカバーされているとき、その相手にオールインで負けるとトーナメントが終わります。","risk-premium":"トーナメントでオールインのリスクを取るために、ポットオッズが求める以上に必要な追加のエクイティです。負けたときの損失が、勝ったときの利益より大きいためです。","m-ratio":"スタックを1ハンドのブラインドとアンティの合計で割った値で、プレイしなくてもチップが何周（オービット）分もつかを示します。","red-zone":"Mがとても低いゾーンで、主にオールインかフォールドしか残りません。","green-zone":"Mが高いゾーンで、スタックに余裕があり、自由に、慎重にも積極的にもプレイできます。","ante":"配る前に全プレイヤーがポットに入れる、少額の強制的な支払いです（主にトーナメント）。","bb-ante":"全プレイヤーの代わりに、ビッグブラインドのプレイヤーがテーブル全体のアンティを払う形式です。","fold-equity":"相手がフォールドする可能性から生まれる、プレイの価値の一部です。","gap-concept":"オープンにコールするには、自分でオープンするより強い手が必要だという原則です。","chip-ev":"お金に換算せずに（ICMなしで）チップで計算した、プレイの期待値です。","tournament-equity":"その賞金構造とスタックのもとで期待できる、プライズプールの自分の取り分です。「$EV」とも呼ばれます。","prize-pool":"トーナメントで賞金を得るプレイヤーの間で分けられるお金の合計です。","payout":"トーナメントの特定の順位に対する賞金です。すべて合わせて賞金の配分になります。","pay-jump":"トーナメントで隣り合う順位の間の賞金の差です。差が大きいほどリスクプレミアムが大きくなります。","final-table":"トーナメントの最後のテーブルで、最も高い賞金を争います。","short-stack":"ブラインドに比べて小さいスタックです。トーナメントでは通常、ビッグブラインドがわずかしか残っていない状態を指します。","nash-equilibrium":"どのプレイヤーも自分の戦略だけを変えても得をしない、戦略の組み合わせです。","overcall":"前のプレイヤーがすでにコールしたベットにコールすることです。","heads-up":"1対1のプレイで、テーブルまたはハンドに2人のプレイヤーだけが残った状態です。","dead-money":"もうポットを獲得できないプレイヤーがポットに入れたチップです。例：フォールドしたプレイヤーのチップ。","stack-off":"1つのハンドでスタックをすべてポットに入れること、つまりオールインするか、オールインにコールすることです。","exploit":"相手、またはプレイヤー層全体の特定のミスを突くために、基本の戦略から意図的に外れることです。","hud":"オンラインプレイでテーブルに重ねて表示され、以前にプレイしたハンドから相手の統計を示すツールです。","vpip":"HUDの統計で、フロップ前にプレイヤーが自分の意思でポットにお金を入れる（コールまたはレイズする）ハンドの割合です。","pfr":"HUDの統計で、プレイヤーがフロップ前にレイズするハンドの割合です。","wtsd":"HUDの統計で、フロップを見たプレイヤーがショーダウンまで行く頻度です。","nit":"とてもタイトなプレイヤーで、ほぼ強い手だけでポットに参加します。","regular":"そのステークスに常にいて、多くのハンドをプレイするプレイヤーです。このコースではレクリエーショナルプレイヤーと対比します。","tag":"タイトアグレッシブなスタイルで、プレイする手は少ないものの、積極的に（ベットやレイズで）プレイします。","lag":"ルースアグレッシブなスタイルで、多くの手を積極的にプレイします。","recreational":"楽しみのためにプレイし、通常はレギュラーより弱いプレイヤーです。俗語では見下して「フィッシュ」と呼ばれます。","calling-station":"弱い手やドローでも、とても頻繁にコールするプレイヤーを見下した呼び方です。","maniac":"何でもベットやレイズする、とてもルースでアグレッシブなプレイヤーを見下した呼び方です。","rake":"カジノやオンラインのポーカールームが、ゲーム運営の対価としてポットから取る手数料です。","rake-cap":"ポーカールームが1つのハンドから取れるレーキの上限額です。"},
  "ko": {"royal-flush":"포커에서 가장 높은 족보입니다. 같은 무늬의 에이스, 킹, 퀸, 잭, 10으로 이루어집니다(예: A♠ K♠ Q♠ J♠ T♠).","straight-flush":"같은 무늬로 된 연속된 카드 다섯 장입니다(예: 5♥ 6♥ 7♥ 8♥ 9♥). 가장 높은 형태(에이스부터 10까지)는 따로 부르는 이름이 있으며, 게임에서 가장 강한 족보입니다.","four-of-a-kind":"같은 숫자의 카드 네 장입니다(예: 7 네 장). 같은 숫자의 포카드끼리 맞붙으면 다섯 번째 카드(키커)가 높은 쪽이 이깁니다.","full-house":"트리플과 페어가 한 족보에 함께 있는 것입니다(예: 퀸 세 장과 5 두 장). 풀하우스끼리는 트리플이 높은 쪽이 이깁니다.","flush":"같은 무늬(♠, ♥, ♦ 또는 ♣)의 카드 다섯 장으로, 숫자가 연속되지 않습니다. 플러시끼리는 가장 높은 카드가 높은 쪽이 이기고, 같으면 그다음 카드로 가립니다.","straight":"연속된 카드 다섯 장으로, 모두 같은 무늬는 아닙니다(예: 5-6-7-8-9). 에이스는 가장 높은 카드(A-K-Q-J-T)도, 가장 낮은 카드(A-2-3-4-5)도 될 수 있습니다.","three-of-a-kind":"같은 숫자의 카드 세 장과 다른 카드 두 장입니다. 홀덤에서는 따로 부르는 이름이 있는 두 가지 형태가 있습니다. 페어가 손에 있고 세 번째 카드가 보드에 있으면 셋, 페어가 보드에 있고 세 번째 카드가 손에 있으면 트립스입니다.","set":"손에 든 페어와 보드의 카드 한 장으로 만든 트리플입니다(예: K-7-2 플롭에서 7♣ 7♦).","two-pair":"서로 다른 페어 두 개와 다섯 번째 카드입니다(예: K-K-8-8-3). 동점이면 먼저 높은 페어, 다음으로 낮은 페어, 마지막으로 다섯 번째 카드로 가립니다.","pair":"같은 숫자의 카드 두 장과 다른 카드 세 장입니다(예: 9 두 장). 이보다 약한 족보는 하이카드뿐입니다.","high-card":"페어나 그보다 좋은 조합이 없는 족보입니다. 가장 높은 카드로 강도가 정해지고, 같으면 그다음 카드들로 가립니다.","kicker":"족보에 포함되지 않은 카드 중 가장 높은 카드로, 동점을 가립니다. 예: 킹을 곁들인 에이스 페어는 퀸을 곁들인 에이스 페어를 이깁니다.","wheel":"가장 낮은 스트레이트인 A-2-3-4-5로, 에이스가 가장 낮은 카드로 계산됩니다.","check":"칩을 더 내지 않고 계속 진행하는 것으로, 더 낼 금액이 없을 때만 할 수 있습니다. 즉 이번 베팅 라운드에서 아직 아무도 베팅하지 않았을 때입니다(프리플롭에서는 아무도 레이즈하지 않았을 때 빅 블라인드가 할 수 있습니다). 상대의 베팅에 맞춰 칩을 더 내는 콜과 혼동하지 마세요.","bet":"아직 아무도 베팅하지 않은 베팅 라운드에서 처음으로 칩을 거는 것입니다(넓은 의미로는 팟에 칩을 넣는 모든 행위를 베팅이라고 합니다).","call":"계속 플레이하기 위해 상대의 베팅이나 레이즈 금액만큼 팟에 넣는 것입니다. 아무도 베팅하지 않았을 때 베팅 없이 계속 진행하는 체크와 혼동하지 마세요.","raise":"상대의 베팅보다 금액을 올리는 것입니다. 다른 플레이어는 차액을 넣거나, 다시 레이즈하거나, 폴드해야 합니다.","fold":"핸드를 포기하는 것입니다. 카드를 내려놓고 이미 팟에 넣은 칩을 잃습니다.","check-raise":"먼저 체크한 뒤 상대가 베팅하면 같은 베팅 라운드에서 레이즈하는 것입니다.","all-in":"가진 칩을 모두 거는 것입니다. 이때 각 상대에게서 최대 자신이 넣은 만큼만 이길 수 있으며, 나머지는 사이드 팟에서 겨룹니다.","pot":"현재 핸드에 걸린 모든 칩입니다. 쇼다운에서 가장 좋은 족보를 가진 플레이어(사이드 팟이 있으면 팟마다 따로)나, 나머지가 모두 폴드해 혼자 남은 플레이어가 가져갑니다.","side-pot":"누군가 올인했을 때 생기는 별도의 팟입니다. 올인한 플레이어보다 더 많이 넣은 플레이어들만 이 팟을 두고 겨루므로, 올인한 플레이어는 이 팟을 이길 수 없습니다.","split-pot":"족보가 같은 플레이어들이 팟을 나누는 상황입니다. 예를 들어 두 사람 모두 보드에 깔린 같은 스트레이트를 쓰는 경우입니다.","playing-the-board":"가장 좋은 다섯 장 족보가 커뮤니티 카드로만 이루어진 상황입니다. 홀 카드가 아무것도 더해 주지 않으므로, 잘해야 팟을 나눕니다.","board":"가운데에 공개된 커뮤니티 카드(플롭, 턴, 리버)로, 모든 플레이어가 사용합니다. 게임하는 테이블이 아니라 카드를 뜻합니다.","community-cards":"가운데에 앞면이 보이게 놓이는 카드로, 모든 플레이어가 자기 족보를 만드는 데 쓸 수 있습니다. 홀덤에서는 다섯 장입니다.","hole-cards":"홀덤에서 핸드를 시작할 때 엎어서 받는 카드 두 장입니다. 본인만 볼 수 있습니다.","small-blind":"카드를 나누기 전에 버튼 왼쪽 플레이어(두 명일 때는 버튼 자신)가 내는 더 작은 의무 베팅입니다. 그 자리도 이렇게 부릅니다.","big-blind":"카드를 나누기 전에 버튼 왼쪽 두 번째 플레이어(두 명일 때는 버튼 맞은편 플레이어)가 내는 더 큰 의무 베팅입니다. 그 자리도 이렇게 부릅니다. 스택 크기와 결과를 나타내는 단위로도 쓰입니다.","chips":"테이블에서 게임할 때 쓰는 원판입니다. 캐시 게임에서는 돈을, 토너먼트에서는 토너먼트 점수를 나타냅니다.","stack":"플레이어가 앞에 가진 모든 칩입니다. 보통 빅 블라인드 단위로 나타냅니다(예: 빅 블라인드 100개).","street":"베팅 라운드를 가리키는 은어입니다. 프리플롭, 플롭, 턴, 리버가 네 개의 스트리트입니다. 예: “세 스트리트 밸류”는 플롭, 턴, 리버에서 밸류를 위해 베팅하는 것입니다.","betting-round":"플레이어들이 차례로 체크, 베팅, 콜, 레이즈 또는 폴드하는 핸드의 단계입니다. 홀덤에는 프리플롭, 플롭, 턴, 리버의 네 라운드가 있습니다.","preflop":"첫 번째 베팅 라운드로, 홀 카드를 나눈 뒤 보드에 플롭이 깔리기 전입니다.","flop":"프리플롭 베팅 후 한꺼번에 깔리는 첫 세 장의 커뮤니티 카드입니다. 두 번째 베팅 라운드도 이렇게 부릅니다.","turn":"네 번째 커뮤니티 카드이자 세 번째 베팅 라운드입니다.","river":"다섯 번째이자 마지막 커뮤니티 카드이며, 쇼다운 전 마지막 베팅 라운드입니다.","showdown":"마지막 베팅이 끝난 뒤 두 명 이상의 플레이어가 남아 있을 때 카드를 공개하는 것입니다. 가장 좋은 족보가 팟을 가져갑니다.","position":"버튼을 기준으로 한 테이블에서의 자리로, 행동 순서를 정합니다. 나중에 행동하는 사람일수록 결정하기 전에 상대의 행동을 더 많이 봅니다.","in-position":"플롭 이후 마지막으로 행동하는 플레이어의 상황으로, 결정하기 전에 상대의 행동을 봅니다.","out-of-position":"플롭 이후 상대보다 먼저 행동하는 플레이어의 상황으로, 상대의 행동을 모른 채 결정합니다.","early-position":"프리플롭에서 가장 먼저 행동하는 자리들입니다(예: UTG). 뒤에 아직 행동할 플레이어가 많습니다.","late-position":"마지막으로 행동하는 자리들입니다. 버튼과 바로 앞 자리들, 특히 컷오프가 해당합니다.","utg":"프리플롭에서 가장 먼저 행동하는 플레이어로, 빅 블라인드 바로 왼쪽에 앉습니다.","hijack":"컷오프 바로 앞 자리, 즉 버튼 오른쪽 두 번째 자리입니다.","cutoff":"버튼 바로 오른쪽 자리로, 버튼 바로 앞에 행동합니다.","button":"딜러 자리로, “딜러” 원판으로 표시합니다. 플롭 이후 모든 베팅 라운드에서 마지막으로 행동합니다.","outs":"덱에 아직 남아 있으며 핸드를 개선해 주는 카드로, 보통 드로우를 완성해 줍니다. 예: 플러시 드로우라면 내 무늬의 남은 카드들이 아웃입니다.","draw":"아직 강한 족보는 아니지만 다음 커뮤니티 카드에 따라 강한 족보가 될 수 있는 핸드입니다. 예를 들어 플러시나 스트레이트까지 카드 한 장이 부족한 경우입니다.","flush-draw":"같은 무늬의 카드 네 장(손과 보드를 합쳐서)으로, 한 장만 더 오면 플러시가 됩니다.","straight-draw":"스트레이트까지 한 장이 부족한 카드 네 장입니다. 종류: OESD(양쪽 끝 중 어느 한쪽 카드가 부족한 경우)와 거트샷(가운데 카드가 부족한 경우).","oesd":"OESD는 open-ended straight draw의 약자로, 연속된 카드 네 장으로 된 스트레이트 드로우이며 양쪽 끝 어느 카드로든 완성됩니다. 예: 5-6-7-8은 4나 9를 기다립니다.","gutshot":"가운데 특정 숫자 하나가 빠진 스트레이트 드로우입니다. 예: 5-6-8-9는 7만 기다립니다.","backdoor":"플롭에서 턴과 리버에 연달아 맞는 카드 두 장이 필요한 드로우입니다. 예: 플롭 이후 같은 무늬 카드 세 장.","pot-odds":"내야 할 금액과 이길 수 있는 팟(상대 베팅 포함)의 비율입니다. 콜이 이득이 되려면 얼마나 자주 이겨야 하는지 알려 줍니다.","implied-odds":"족보를 맞혔을 때 이후 스트리트에서 더 얻을 것으로 예상되는 칩까지 더한 팟 오즈입니다.","equity":"더 이상 베팅 없이 남은 카드를 모두 깔았을 때 팟을 이길 확률입니다. 보통 백분율로 나타냅니다.","equity-realization":"베팅이 계속될 때 핸드가 자신의 에퀴티를 실제 승리로 얼마나 바꾸는지를 뜻합니다(에퀴티보다 적게도, 많게도 실현할 수 있습니다). 포지션, 핸드를 플레이하기 쉬운 정도 등에 따라 달라집니다.","expected-value":"같은 플레이를 여러 번 반복했을 때의 평균 결과입니다. 평균적으로 플러스인 플레이는 이번에 지더라도 장기적으로 돈을 법니다.","combo":"무늬까지 정해진 구체적인 두 장 조합 하나입니다(예: A♠ K♥). 이런 조합을 세면 특정 핸드가 레인지에 실제로 몇 개 있는지 알 수 있습니다.","range":"특정 상황에서 플레이어가 가질 수 있는 모든 핸드의 집합, 또는 특정 플레이를 할 핸드의 집합입니다.","mixed-hand":"균형 전략이 어떤 때는 한 플레이를, 어떤 때는 다른 플레이를 선택하는 핸드입니다(예: 때로는 레이즈, 때로는 콜). 두 플레이 모두 올바릅니다. 이런 핸드는 혼합 전략으로 플레이한다고도 합니다.","open":"앞의 모든 플레이어가 폴드했을 때 프리플롭에서 레이즈로 팟에 처음 들어가는 것입니다.","suited":"같은 무늬의 홀 카드 두 장입니다(예: A♥ K♥, 표기 AKs).","offsuit":"서로 다른 무늬의 홀 카드 두 장입니다(예: A♥ K♣, 표기 AKo).","pocket-pair":"홀 카드 두 장으로 된 페어입니다(예: 프리플롭의 8♣ 8♦).","connectors":"숫자가 이웃한 홀 카드입니다(예: 8-7, 9-8). 스트레이트를 만들기 쉽습니다.","3-bet":"프리플롭에서 오픈에 대한 첫 레이즈입니다. 이 이름은 빅 블라인드를 첫 번째 베팅, 오픈을 두 번째 베팅으로 셉니다.","4-bet":"3벳에 대한 레이즈, 즉 베팅 라운드의 네 번째 베팅입니다.","limp":"아직 아무도 레이즈하지 않았을 때 프리플롭에서 빅 블라인드를 콜만 해서 팟에 들어가는 것입니다.","isolation":"한 명 이상이 림프한 뒤 림퍼(종종 약한 플레이어)와 일대일로 플레이하기 위해 하는 레이즈입니다.","texture":"커뮤니티 카드의 특성입니다. 무늬가 몇 가지인지, 카드 숫자가 서로 가까운지, 페어가 있는지를 봅니다. 이에 따라 가능한 족보와 드로우가 정해집니다.","dry":"가능한 드로우와 강한 족보가 적은 보드입니다(예: K♠ 7♦ 2♣).","wet":"가능한 드로우와 강한 족보가 많은 보드입니다(예: J♥ T♥ 8♣).","rainbow":"세 장이 모두 다른 무늬인 플롭으로, 플롭에서는 아무도 플러시 드로우를 갖지 못합니다.","two-tone":"두 장이 같은 무늬인 플롭으로, 플러시 드로우가 가능합니다.","monotone":"세 장이 모두 같은 무늬인 플롭으로, 이미 플러시가 완성되었을 수 있습니다.","paired":"페어(같은 숫자의 카드 두 장)가 깔린 보드입니다(예: 8-8-3).","connected":"누군가 이미 스트레이트를 완성했을 수 있는 보드입니다(예: 9-8-7).","disconnected":"카드 숫자가 서로 멀어서 스트레이트나 스트레이트 드로우를 만들기 어려운 보드입니다(예: K-7-2).","semi-connected":"스트레이트 드로우는 있지만 아직 스트레이트는 불가능한 보드입니다(예: T-8-3, 이 과정에서 쓰는 분류).","wetness":"보드가 드로우와 강한 족보에 얼마나 유리한지를 나타내는 정도로, 드라이부터 웻까지입니다. 보드가 얼마나 서로 맞물려 있는지(코디네이션)로 표현하기도 합니다.","top-pair":"보드에서 가장 높은 카드로 만든 페어입니다(예: K-7-2 플롭에서 K♠ Q♦).","second-pair":"보드에서 두 번째로 높은 카드로 만든 페어입니다(예: K-7-2 플롭에서 7♠ 6♠).","overpair":"보드의 모든 카드보다 높은 포켓 페어입니다(예: J-7-2 플롭에서 Q-Q).","c-bet":"컨티뉴에이션 베팅으로, 이전 라운드에서 어그레서였던 플레이어의 베팅입니다. 예: 프리플롭에서 오픈한 뒤 플롭에서 하는 베팅.","aggressor":"이전 베팅 라운드에서 마지막으로 베팅하거나 레이즈한 플레이어입니다.","initiative":"마지막 어그레서의 역할로, 보통 이 플레이어가 다음 베팅을 합니다.","range-advantage":"특정 보드에서 한 플레이어의 레인지가 상대 레인지보다 전체 에퀴티가 더 큰 상황입니다.","nuts-advantage":"한 플레이어의 레인지에 가장 강한 핸드가 상대보다 비율상 더 많은 상황입니다.","nuts":"특정 순간에 해당 보드에서 가능한 가장 강한 핸드입니다. 예: K♥ 9♥ 4♥ 2♣ 보드에서는 하트 에이스가 포함된 플러시입니다.","polarized":"레인지에 대해: 주로 매우 강한 핸드와 블러프로 이루어지고, 중간 핸드가 거의 없는 상태입니다.","polarization":"양극단으로 레인지를 구성하는 것입니다. 밸류용 강한 핸드와 블러프로 채우고, 중간 핸드는 넣지 않습니다.","linear":"레인지에 대해: 위에서부터, 즉 가장 강한 핸드부터 아래로 구성하며 별도의 블러프 그룹이 없는 상태입니다. 관련 용어로 “머지드 레인지”(폴라라이즈드가 아닌 레인지)도 볼 수 있으며, 공개된 솔버 분석에 따르면 머지드는 이 레인지와 폴라라이즈드 레인지의 중간 형태입니다.","condensed":"레인지에 대해: 가장 강한 핸드가 없고(위쪽이 막혀 있고) 주로 중간 핸드로 이루어진 상태로, 폴라라이즈드의 반대입니다.","value":"상대가 더 약한 핸드로 콜하도록 강한 핸드로 베팅하는 것입니다.","value-bet":"밸류를 위한 한 번의 베팅으로, 더 약한 핸드가 콜하도록 강한 핸드로 합니다.","bluff":"쇼다운에서 이기기 어려운 약한 핸드로, 상대가 더 좋은 핸드를 폴드하도록 하는 베팅입니다.","semi-bluff":"아직 약하지만 좋아질 가능성이 있는 핸드(예: 드로우)로 하는 베팅입니다. 상대가 폴드하거나 카드가 맞으면 이깁니다.","blocker":"내 손에 있어 상대가 특정 핸드를 가질 확률을 낮추는 카드입니다. 예: 내가 하트 에이스를 들고 있으면 상대는 하트 에이스가 포함된 플러시를 가질 수 없습니다.","bluff-catcher":"상대의 블러프만 이기고 상대의 밸류 베팅에는 지는 핸드입니다.","barrel":"이전 라운드에서 직접 베팅한 뒤 다음 베팅 라운드에서 다시 하는 베팅입니다.","second-barrel":"연속된 두 번째 베팅입니다. 플롭에서 C벳을 한 뒤 턴에서 다시 베팅하는 것입니다.","probe-bet":"프리플롭 어그레서가 플롭에서 C벳 대신 체크한 뒤, 아웃 오브 포지션 플레이어가 턴에서 하는 베팅입니다.","donk-bet":"이전 라운드의 어그레서가 행동하기 전에 먼저 하는 베팅입니다.","overbet":"플롭 이후 팟 전체보다 큰 베팅입니다.","effective-stack":"두 플레이어 간 핸드에서 두 스택 중 작은 쪽으로, 실제로 이기거나 잃을 수 있는 최대 금액입니다. 여러 명일 때는 각 쌍마다 따로 계산합니다.","spr":"스트리트 시작 시점의 유효 스택을 팟으로 나눈 값입니다(핸드 계획에는 플롭 기준으로 계산합니다). 팟에 비해 스택이 얼마나 깊은지 보여 줍니다(SPR이 낮을수록 모든 칩이 더 빨리 팟에 들어갑니다).","mdf":"승산이 없는 핸드로 하는 상대의 블러프가 자동으로 이득이 되지 않도록, 베팅에 맞서 지켜야 하는 레인지의 최소 비율입니다.","alpha":"승산이 없는 핸드로 하는 블러프가 본전이 되려면 상대가 얼마나 자주 폴드해야 하는지를 나타냅니다. 팟 대비 베팅 크기에 따라 달라집니다.","variance":"기댓값을 중심으로 한 결과의 흩어짐입니다. 잘 플레이해도 짧은 기간에는 크게 지거나 크게 이길 수 있습니다.","buy-in":"토너먼트에 참가하거나 캐시 게임 테이블에 앉기 위한 금액입니다.","bankroll":"포커에만 쓰기로 따로 떼어 둔 자금 전체입니다. 이 앱에서는 돈이 아니라 바이인 단위로 셉니다.","tilt":"감정(분노, 좌절, 들뜸)이 테이블에서의 결정을 나쁘게 만드는 상태입니다.","winrate":"긴 표본에서의 플레이어 평균 결과입니다. 캐시 게임에서는 보통 bb/100, 즉 100핸드당 빅 블라인드로 나타냅니다.","downswing":"결과가 눈에 띄게 나빠지는 기간으로, 보통 실력에 비해 손실이 더 큽니다. 업스윙의 반대입니다.","session":"게임을 시작해서 끝낼 때까지 한 번 앉아서 하는 포커입니다.","stakes":"캐시 게임의 블라인드 크기나 토너먼트의 바이인 크기입니다. “마이크로 스테이크”는 가장 낮은 단계입니다.","standard-deviation":"결과의 흩어짐을 나타내는 척도(분산의 제곱근)로, 포커에서는 보통 bb/100으로 나타냅니다.","risk-of-ruin":"같은 스테이크에서 계속 플레이할 때 언젠가 뱅크롤 전체를 잃을 확률입니다.","mental-game":"포커의 심리적 측면으로, 테이블에서 틸트, 감정, 집중력을 다루는 것입니다.","tournament":"일정 시간마다 블라인드가 오르고, 한 플레이어가 모든 칩을 모을 때까지 계속되는 게임 형식입니다. 상위 순위 플레이어가 상금을 받습니다.","push-fold":"숏 스택을 위한 단순화된 전략으로, 프리플롭에서 올인하거나 폴드만 합니다.","shove":"올인하는 플레이로, 보통 프리플롭 레이즈로 합니다.","icm":"상금 구조와 모든 플레이어의 스택을 고려해 토너먼트 칩을 금전 가치로 환산하는 모델입니다.","bubble":"상금권 직전의 토너먼트 단계로, 몇 명만 더 탈락하면 상금권에 들어갑니다.","bubble-factor":"ICM에서 나온 지표로, 토너먼트에서 같은 수의 칩을 잃는 고통이 얻는 기쁨보다 얼마나 더 큰지를 나타냅니다.","cover":"상대보다 칩이 같거나 많은 것입니다. 상대가 나를 커버하면, 그 상대와의 올인에서 지는 순간 토너먼트가 끝납니다.","risk-premium":"토너먼트에서 올인 위험을 감수하려면 팟 오즈가 요구하는 것보다 더 필요한 추가 에퀴티입니다. 지면 잃는 것이 이기면 얻는 것보다 크기 때문입니다.","m-ratio":"스택을 한 핸드의 블라인드와 앤티 합계로 나눈 값으로, 플레이하지 않고 칩이 몇 바퀴(오빗) 버틸 수 있는지를 나타냅니다.","red-zone":"M이 매우 낮은 구간으로, 주로 올인 아니면 폴드만 남습니다.","green-zone":"M이 높은 구간으로, 스택이 넉넉해 자유롭게, 신중하게 또는 공격적으로 플레이할 수 있습니다.","ante":"카드를 나누기 전에 모든 플레이어가 팟에 내는 작은 의무 금액입니다(주로 토너먼트).","bb-ante":"모든 플레이어 대신 빅 블라인드 자리의 플레이어가 테이블 전체의 앤티를 내는 앤티 방식입니다.","fold-equity":"상대가 폴드할 수 있다는 점에서 나오는 플레이 가치의 일부입니다.","gap-concept":"오픈을 콜하려면 직접 오픈할 때보다 더 강한 핸드가 필요하다는 원칙입니다.","chip-ev":"칩을 돈으로 환산하지 않고(ICM 없이) 칩 단위로 계산한 플레이의 기댓값입니다.","tournament-equity":"주어진 상금 구조와 스택에서 기대되는 상금 풀의 내 몫입니다. “$EV”라고도 합니다.","prize-pool":"토너먼트에서 상금을 받는 플레이어들이 나눠 가질 돈의 합계입니다.","payout":"토너먼트의 특정 순위에 주어지는 상금으로, 이를 모두 합치면 상금 분배가 됩니다.","pay-jump":"토너먼트에서 이웃한 순위 간 상금 차이입니다. 차이가 크면 리스크 프리미엄이 커집니다.","final-table":"토너먼트의 마지막 테이블로, 가장 큰 상금을 놓고 겨룹니다.","short-stack":"블라인드에 비해 작은 스택입니다. 토너먼트에서는 보통 빅 블라인드가 몇 개 남지 않은 스택입니다.","nash-equilibrium":"어떤 플레이어도 자기 전략만 바꿔서는 이득을 볼 수 없는 전략의 조합입니다.","overcall":"앞의 누군가가 이미 콜한 베팅을 콜하는 것입니다.","heads-up":"일대일 게임으로, 테이블이나 핸드에 플레이어가 두 명만 남은 상황입니다.","dead-money":"더 이상 팟을 이길 수 없는 플레이어들이 넣은 칩입니다(예: 폴드한 플레이어의 칩).","stack-off":"한 핸드에서 스택 전체를 팟에 넣는 것, 즉 올인하거나 올인을 콜하는 것입니다.","exploit":"상대 또는 플레이어 풀 전체의 특정 실수를 이용하기 위해 기본 전략에서 의도적으로 벗어나는 것입니다.","hud":"온라인 게임에서 테이블 위에 표시되어, 이전에 플레이한 핸드를 바탕으로 상대의 통계를 보여 주는 오버레이입니다.","vpip":"HUD 통계로, 플레이어가 프리플롭에서 자발적으로 팟에 돈을 넣는(콜이나 레이즈) 핸드의 비율입니다.","pfr":"HUD 통계로, 플레이어가 프리플롭에서 레이즈하는 핸드의 비율입니다.","wtsd":"HUD 통계로, 플롭을 본 플레이어가 쇼다운까지 가는 빈도입니다.","nit":"거의 강한 핸드로만 팟에 들어가는 매우 타이트한 플레이어입니다.","regular":"해당 스테이크에서 꾸준히 많은 핸드를 소화하는 단골 플레이어입니다. 이 과정에서는 레크리에이션 플레이어와 대비됩니다.","tag":"타이트하고 공격적인 스타일로, 적은 핸드를 공격적으로(베팅과 레이즈로) 플레이합니다.","lag":"루즈하고 공격적인 스타일로, 많은 핸드를 공격적으로 플레이합니다.","recreational":"재미로 플레이하며 보통 레귤러보다 약한 플레이어입니다. 은어로는 낮춰서 “피시”라고 부릅니다.","calling-station":"약한 핸드나 드로우로도 매우 자주 콜하는 플레이어를 낮춰 부르는 말입니다.","maniac":"아무 핸드로나 베팅하고 레이즈하는 매우 루즈하고 공격적인 플레이어를 낮춰 부르는 말입니다.","rake":"카지노나 온라인 포커룸이 게임 운영 대가로 팟에서 떼어 가는 수수료입니다.","rake-cap":"포커룸이 한 핸드에서 가져갈 수 있는 레이크의 최대 금액입니다."},
  "pt": {"royal-flush":"A mão mais alta do póquer: ás, rei, dama, valete e dez do mesmo naipe, por exemplo A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Cinco cartas consecutivas do mesmo naipe, por exemplo 5♥ 6♥ 7♥ 8♥ 9♥. A variante mais alta (do ás ao dez) tem nome próprio e é a mão mais forte do jogo.","four-of-a-kind":"Quatro cartas do mesmo valor, por exemplo quatro setes. Entre duas quadras do mesmo valor, ganha a quinta carta mais alta (kicker).","full-house":"Um trio e um par na mesma mão, por exemplo três damas e dois cincos. Entre dois full house, ganha o trio mais alto.","flush":"Cinco cartas do mesmo naipe (♠, ♥, ♦ ou ♣) que não são consecutivas. Entre duas destas mãos, ganha a que tiver a carta de topo mais alta; se esta for igual, ganha a que tiver a seguinte mais alta.","straight":"Cinco cartas consecutivas, nem todas do mesmo naipe, por exemplo 5-6-7-8-9. O ás pode ser a carta mais alta (A-K-Q-J-T) ou a mais baixa (A-2-3-4-5).","three-of-a-kind":"Três cartas do mesmo valor e duas outras. No hold'em tem duas variantes com nome próprio: set, quando o par está na mão e a terceira carta na mesa, e trips, quando o par está na mesa e a terceira carta na mão.","set":"Trio formado por um par na mão e uma carta da mesa, por exemplo 7♣ 7♦ num flop K-7-2.","two-pair":"Dois pares diferentes e uma quinta carta, por exemplo K-K-8-8-3. Em caso de empate, decide primeiro o par mais alto, depois o mais baixo e, por fim, a quinta carta.","pair":"Duas cartas do mesmo valor e três outras, por exemplo dois noves. Só a carta alta é mais fraca.","high-card":"Mão sem par nem combinação melhor; a força é decidida pela carta mais alta e, em caso de empate, pelas seguintes.","kicker":"A carta mais alta fora da combinação, que decide o empate. Exemplo: um par de ases com rei ganha a um par de ases com dama.","wheel":"A sequência mais baixa: A-2-3-4-5, em que o ás conta como a carta mais baixa.","check":"Continuar no jogo sem pôr fichas, só possível quando não tem de pagar nada: nesta ronda de apostas ainda ninguém apostou (antes do flop, o big blind pode fazê-lo quando ninguém aumentou). Não confundir com pagar, que é igualar a aposta do adversário.","bet":"A primeira colocação de fichas numa ronda de apostas em que ainda ninguém apostou (em sentido lato, chama-se aposta a qualquer entrada de fichas no pote).","call":"Pôr no pote o valor da aposta ou do aumento do adversário para continuar a jogar. Não confundir com passar, que é continuar sem apostar quando ninguém apostou.","raise":"Elevar o valor acima da aposta do adversário; os restantes têm de pôr a diferença, voltar a aumentar ou desistir. Também se diz «subir».","fold":"Abandonar a mão: entrega as cartas e perde o que já pôs no pote.","check-raise":"Primeiro passa e, quando o adversário aposta, aumenta a aposta dele na mesma ronda de apostas.","all-in":"Apostar todas as suas fichas. De cada adversário pode então ganhar, no máximo, tanto quanto pôs; o resto é disputado num pote secundário.","pot":"Todas as fichas apostadas na mão em curso. Leva-as o jogador com a melhor mão no showdown (com potes secundários, cada pote é disputado à parte) ou o jogador perante o qual todos os outros desistiram.","side-pot":"Pote separado que se forma quando alguém joga all-in: só o disputam os jogadores que puseram mais do que o jogador all-in, por isso este não o pode ganhar.","split-pot":"Situação em que jogadores com mãos iguais dividem o pote, por exemplo quando ambos jogam a mesma sequência que está na mesa.","playing-the-board":"Situação em que a sua melhor mão de cinco cartas é formada só pelas cartas comunitárias; as suas cartas privadas não acrescentam nada, por isso, na melhor das hipóteses, divide o pote.","board":"As cartas comunitárias viradas para cima no centro (flop, turn, river), que todos os jogadores usam. Neste sentido, «mesa» são as cartas, não o local de jogo (à mesa, mesa final).","community-cards":"Cartas colocadas viradas para cima no centro, que qualquer jogador pode usar para formar a sua mão; no hold'em são cinco.","hole-cards":"As duas cartas viradas para baixo que recebe no início da mão no hold'em; só o próprio as vê.","small-blind":"A aposta obrigatória menor, colocada antes da distribuição pelo jogador à esquerda do button (com dois jogadores, pelo próprio button); é também o nome desse lugar à mesa.","big-blind":"A aposta obrigatória maior, colocada antes da distribuição pelo segundo jogador à esquerda do button (com dois jogadores, pelo jogador em frente ao button); é também o nome desse lugar. Serve ainda de unidade para medir stacks e resultados.","chips":"Os discos com que se joga à mesa; nos jogos a dinheiro representam dinheiro, nos torneios pontos de torneio.","stack":"Todas as fichas que um jogador tem à sua frente; costuma indicar-se em big blinds (por exemplo, 100 big blinds).","street":"Nome de gíria para uma ronda de apostas: preflop, flop, turn e river são as quatro streets. Exemplo: «value em três streets» são apostas de valor no flop, no turn e no river.","betting-round":"Fase da mão em que os jogadores, à vez, passam, apostam, pagam, aumentam ou desistem; no hold'em há quatro: preflop, flop, turn e river.","preflop":"A primeira ronda de apostas: depois de distribuídas as cartas privadas, antes de o flop chegar à mesa.","flop":"As três primeiras cartas comunitárias, colocadas de uma vez após as apostas preflop; é também o nome da segunda ronda de apostas.","turn":"A quarta carta comunitária e a terceira ronda de apostas.","river":"A quinta e última carta comunitária e a última ronda de apostas antes do showdown.","showdown":"Revelação das cartas após a última ronda de apostas, quando restam pelo menos dois jogadores na mão; a melhor mão leva o pote.","position":"O lugar à mesa em relação ao button, que define a ordem de ação. Quem age mais tarde vê mais ações dos adversários antes de decidir.","in-position":"Situação do jogador que, depois do flop, age em último lugar e, por isso, vê a ação do adversário antes de decidir.","out-of-position":"Situação do jogador que, depois do flop, age antes do adversário e, por isso, decide sem conhecer a ação dele.","early-position":"Os primeiros lugares a agir antes do flop (por exemplo, UTG); depois de si ainda há muitos jogadores por agir.","late-position":"Os lugares que agem em último: o button e os lugares imediatamente antes dele, sobretudo o cutoff.","utg":"O primeiro jogador a agir antes do flop, sentado imediatamente à esquerda do big blind.","hijack":"O lugar imediatamente antes do cutoff, ou seja, o segundo à direita do button.","cutoff":"O lugar imediatamente à direita do button, que age logo antes dele.","button":"O lugar de quem dá as cartas, marcado com o disco «dealer». Depois do flop, age em último lugar em todas as rondas de apostas.","outs":"Carta que ainda está no baralho e que melhora a sua mão, normalmente completando um draw. Exemplo: com um flush draw, os outs são as restantes cartas do seu naipe.","draw":"Mão que ainda não é uma combinação forte, mas que pode vir a sê-lo com as próximas cartas comunitárias, por exemplo quando falta uma carta para o flush ou para a sequência.","flush-draw":"Quatro cartas do mesmo naipe (na mão e na mesa, em conjunto); falta uma para ter flush.","straight-draw":"Quatro cartas a que falta uma para a sequência. Variantes: OESD (falta uma carta numa de duas pontas) e gutshot (falta uma carta no meio).","oesd":"Abreviatura de open-ended straight draw: draw de sequência com quatro cartas consecutivas, completado por uma carta em qualquer das pontas; por exemplo, 5-6-7-8 espera um quatro ou um nove.","gutshot":"Draw de sequência a que falta um valor específico no meio; por exemplo, 5-6-8-9 só espera um sete.","backdoor":"Draw no flop que precisa de duas cartas favoráveis seguidas, no turn e no river; por exemplo, três cartas do mesmo naipe após o flop.","pot-odds":"Relação entre o valor que tem de pagar e o pote que pode ganhar (incluindo a aposta do adversário). Indica com que frequência tem de ganhar para que pagar compense.","implied-odds":"Pot odds acrescidas das fichas que espera ganhar nas rondas seguintes se completar a sua mão.","equity":"A sua probabilidade de ganhar o pote se todas as cartas restantes fossem dadas sem mais apostas; normalmente em percentagem.","equity-realization":"Em que medida uma mão converte a sua equity em ganhos quando as apostas continuam (pode realizar menos ou mais do que a sua equity); depende, entre outros fatores, da posição e da facilidade com que a mão se joga.","expected-value":"O resultado médio de uma jogada se fosse repetida muitas vezes. Uma jogada com resultado médio positivo dá lucro a longo prazo, mesmo que desta vez perca.","combo":"Uma disposição concreta de duas cartas com naipes, por exemplo A♠ K♥. Contar estas disposições mostra quantas combinações de determinada mão existem realmente num range.","range":"O conjunto de todas as mãos que um jogador pode ter numa dada situação, ou das mãos com que faria determinada jogada.","mixed-hand":"Mão com que a estratégia de equilíbrio escolhe ora uma jogada, ora outra (por exemplo, por vezes aumentar, por vezes pagar); ambas as jogadas são corretas. Diz-se também que a mão é jogada com uma estratégia mista.","open":"Primeira entrada no pote antes do flop com um aumento, quando todos antes de si desistiram.","suited":"Duas cartas privadas do mesmo naipe, por exemplo A♥ K♥ (notação AKs).","offsuit":"Duas cartas privadas de naipes diferentes, por exemplo A♥ K♣ (notação AKo).","pocket-pair":"Par formado pelas duas cartas privadas, por exemplo 8♣ 8♦ antes do flop.","connectors":"Cartas privadas de valores vizinhos, por exemplo 8-7 ou 9-8; com elas é mais fácil formar uma sequência.","3-bet":"O primeiro aumento sobre uma abertura antes do flop; o nome conta o big blind como primeira aposta e a abertura como segunda.","4-bet":"Aumento sobre um 3-bet, ou seja, a quarta aposta na ronda de apostas.","limp":"Entrada no pote antes do flop pagando apenas o big blind, quando ainda ninguém aumentou.","isolation":"Aumento após um ou mais limps, para jogar contra o limper (muitas vezes um jogador mais fraco) um contra um.","texture":"O carácter das cartas comunitárias: quantos naipes há, se as cartas estão próximas umas das outras, se há um par. Disso depende que mãos e draws são possíveis.","dry":"Mesa em que são possíveis poucos draws e poucas mãos fortes, por exemplo K♠ 7♦ 2♣.","wet":"Mesa em que são possíveis muitos draws e mãos fortes, por exemplo J♥ T♥ 8♣.","rainbow":"Flop com três cartas de três naipes diferentes, pelo que no flop ninguém tem flush draw.","two-tone":"Flop com duas cartas do mesmo naipe, pelo que são possíveis draws de flush.","monotone":"Flop com três cartas do mesmo naipe, pelo que o flush pode já estar feito.","paired":"Mesa com um par (duas cartas do mesmo valor), por exemplo 8-8-3.","connected":"Mesa em que alguém pode já ter feito uma sequência, por exemplo 9-8-7.","disconnected":"Mesa com cartas afastadas entre si, com a qual é difícil formar uma sequência ou um draw de sequência, por exemplo K-7-2.","semi-connected":"Mesa com draw de sequência, mas em que a sequência ainda não é possível, por exemplo T-8-3 (classificação adotada no curso).","wetness":"O grau em que a mesa favorece draws e mãos fortes: de seca a molhada. Também se fala do grau de coordenação da mesa.","top-pair":"Par com a carta mais alta da mesa, por exemplo K♠ Q♦ num flop K-7-2.","second-pair":"Par com a segunda carta mais alta da mesa, por exemplo 7♠ 6♠ num flop K-7-2.","overpair":"Par de mão mais alto do que todas as cartas da mesa, por exemplo Q-Q num flop J-7-2.","c-bet":"Aposta de continuação: aposta do jogador que foi o agressor na ronda anterior, por exemplo uma aposta no flop depois de abrir preflop.","aggressor":"O jogador que apostou ou aumentou em último lugar na ronda de apostas anterior.","initiative":"O papel do último agressor: normalmente é ele que faz a aposta seguinte.","range-advantage":"Situação em que o range de um jogador tem, numa dada mesa, mais equity no total do que o range do adversário.","nuts-advantage":"Situação em que um jogador tem no range, proporcionalmente, mais das mãos mais fortes do que o adversário.","nuts":"A mão mais forte possível numa dada mesa, num dado momento. Exemplo: na mesa K♥ 9♥ 4♥ 2♣ é o flush com o ás de copas.","polarized":"Diz-se de um range: composto sobretudo por mãos muito fortes e bluffs, quase sem mãos médias.","polarization":"Construção do range a partir dos extremos: mãos fortes para valor e bluffs, sem mãos médias.","linear":"Diz-se de um range: construído de cima para baixo, das mãos mais fortes para as mais fracas, sem um grupo separado de bluffs. Encontra-se também o termo próximo «merged range» (range não polarizado); segundo análises publicadas de solvers, o merged é uma forma intermédia entre este range e o polarizado.","condensed":"Diz-se de um range: sem as mãos mais fortes (limitado por cima) e composto sobretudo por mãos médias; o oposto do polarizado.","value":"Apostar com uma mão forte para que o adversário pague com uma mão mais fraca.","value-bet":"Uma aposta individual de valor: feita com uma mão forte para que mãos mais fracas a paguem.","bluff":"Aposta com uma mão fraca, que dificilmente ganhará no showdown, para levar o adversário a desistir com uma mão melhor.","semi-bluff":"Aposta com uma mão ainda fraca, mas com hipóteses de melhorar (por exemplo, com um draw): ganha se o adversário desistir ou se completar a mão.","blocker":"Carta na sua mão que reduz a probabilidade de o adversário ter determinadas mãos. Exemplo: se tiver o ás de copas, o adversário não pode ter o flush de copas com ás.","bluff-catcher":"Mão que só bate os bluffs do adversário e perde para as apostas de valor dele.","barrel":"Nova aposta na ronda de apostas seguinte, depois de ter apostado na ronda anterior.","second-barrel":"A segunda aposta seguida: depois de um c-bet no flop, o jogador volta a apostar no turn.","probe-bet":"Aposta no turn do jogador fora de posição depois de o agressor preflop ter passado no flop em vez de fazer c-bet.","donk-bet":"Aposta de um jogador que aposta antes de o agressor da ronda anterior ter tido oportunidade de agir.","overbet":"Aposta depois do flop maior do que todo o pote.","effective-stack":"Numa mão entre dois jogadores: o menor dos dois stacks, ou seja, o máximo que se pode realmente ganhar ou perder. Com vários jogadores, calcula-se separadamente para cada par.","spr":"O stack efetivo dividido pelo pote no início de uma ronda (para planear a mão, calcula-se no flop); indica a profundidade dos stacks em relação ao pote (quanto mais baixo o SPR, mais depressa tudo vai para o pote).","mdf":"A menor parte do range que é preciso defender contra uma aposta para que o bluff do adversário com uma mão sem hipóteses não seja automaticamente lucrativo.","alpha":"Com que frequência o adversário tem de desistir para que um bluff com uma mão sem hipóteses não ganhe nem perca; depende do tamanho da aposta em relação ao pote.","variance":"A dispersão dos resultados em torno do valor esperado: mesmo jogando bem, séries curtas podem ficar muito no negativo ou no positivo.","buy-in":"O valor de entrada num torneio ou num jogo a dinheiro à mesa.","bankroll":"Toda a reserva destinada exclusivamente a jogar póquer; nesta aplicação é contada em buy-ins, não em dinheiro.","tilt":"Estado em que as emoções (raiva, frustração, euforia) pioram as suas decisões à mesa.","winrate":"O resultado médio de um jogador numa amostra mais longa; nos jogos a dinheiro, normalmente em bb/100, ou seja, big blinds por cem mãos.","downswing":"Período de resultados claramente piores, normalmente perdas maiores do que a habilidade faria prever; o oposto de um upswing.","session":"Um período de jogo de póquer, desde o início até ao fim do jogo.","stakes":"O valor dos blinds num jogo a dinheiro ou do buy-in num torneio; os «micro stakes» são os níveis mais baixos.","standard-deviation":"Medida da dispersão dos resultados (raiz quadrada da variância); no póquer, normalmente indicada em bb/100.","risk-of-ruin":"Probabilidade de vir a perder todo o bankroll se continuar a jogar nos mesmos stakes.","mental-game":"O lado psicológico do póquer: lidar com o tilt, as emoções e a concentração à mesa.","tournament":"Formato em que os blinds sobem periodicamente e o jogo continua até um jogador reunir todas as fichas; os prémios vão para os mais bem classificados.","push-fold":"Estratégia simplificada para short stacks: antes do flop, joga-se all-in ou desiste-se.","shove":"Jogada all-in, normalmente como aumento antes do flop.","icm":"Modelo que converte as fichas de torneio em valor monetário, tendo em conta a estrutura de pagamentos e os stacks de todos os jogadores.","bubble":"Fase do torneio imediatamente antes dos lugares pagos, quando faltam poucas eliminações para chegar aos prémios.","bubble-factor":"Indicador do ICM: quanto mais dói, num torneio, perder um certo número de fichas do que compensa ganhar o mesmo número.","cover":"Ter pelo menos tantas fichas como o adversário. Quando o adversário o cobre, perder um all-in contra ele termina o seu torneio.","risk-premium":"Equity adicional, acima do que as pot odds exigem, necessária num torneio para arriscar um all-in, porque perder custa mais do que ganhar rende.","m-ratio":"O stack dividido pela soma dos blinds e dos antes de uma mão: para quantas voltas completas (órbitas) as fichas chegam sem jogar.","red-zone":"Zona de M muito baixo: resta sobretudo jogar all-in ou desistir.","green-zone":"Zona de M alto: o stack permite jogar livremente, de forma conservadora ou agressiva.","ante":"Pequena contribuição obrigatória para o pote, feita por todos os jogadores antes da distribuição (sobretudo em torneios).","bb-ante":"Formato de ante em que, em vez de todos os jogadores, é o jogador no big blind que paga o ante por toda a mesa.","fold-equity":"A parte do valor de uma jogada que resulta de o adversário poder desistir.","gap-concept":"Princípio segundo o qual é preciso uma mão mais forte para pagar uma abertura do que para abrir.","chip-ev":"Valor esperado de uma jogada calculado em fichas, sem as converter em dinheiro (sem ICM).","tournament-equity":"A sua parte esperada da bolsa de prémios, dada a estrutura de pagamentos e os stacks. O mesmo também se designa por «$EV».","prize-pool":"Soma do dinheiro a repartir pelos jogadores premiados de um torneio.","payout":"O prémio por um lugar concreto no torneio; todos juntos formam a distribuição de prémios.","pay-jump":"Diferença de pagamento entre lugares vizinhos num torneio; saltos grandes aumentam o risk premium.","final-table":"A última mesa de um torneio, onde se disputam os prémios mais altos.","short-stack":"Stack pequeno em relação aos blinds; nos torneios, normalmente um com poucos big blinds.","nash-equilibrium":"Conjunto de estratégias em que nenhum jogador ganha ao alterar apenas a sua própria estratégia.","overcall":"Pagar uma aposta que alguém antes de si já pagou.","heads-up":"Jogo um contra um: à mesa ou na mão restam apenas dois jogadores.","dead-money":"Fichas no pote de jogadores que já não o podem ganhar, por exemplo dos que desistiram.","stack-off":"Pôr todo o stack no pote numa só mão, ou seja, jogar all-in ou pagar um all-in.","exploit":"Desvio deliberado da estratégia base para tirar partido de um erro concreto de um adversário ou de toda a população de jogadores.","hud":"Sobreposição na mesa, no jogo online, que mostra estatísticas dos adversários a partir de mãos jogadas anteriormente.","vpip":"Estatística do HUD: em que percentagem das mãos o jogador põe voluntariamente dinheiro no pote antes do flop (paga ou aumenta).","pfr":"Estatística do HUD: em que percentagem das mãos o jogador aumenta antes do flop.","wtsd":"Estatística do HUD: com que frequência o jogador que viu o flop chega ao showdown.","nit":"Jogador muito apertado, que entra no pote quase só com mãos fortes.","regular":"Frequentador habitual de um dado nível de stakes, que joga muitas mãos; no curso, contrapõe-se ao jogador recreativo.","tag":"Estilo apertado e agressivo: poucas mãos, mas jogadas de forma agressiva (apostas e aumentos).","lag":"Estilo solto e agressivo: muitas mãos, jogadas de forma agressiva.","recreational":"Jogador que joga por diversão e, em regra, pior do que os regulares; na gíria, pejorativamente, «fish».","calling-station":"Termo pejorativo para um jogador que paga com muita frequência, mesmo com mãos fracas ou draws.","maniac":"Termo pejorativo para um jogador muito solto e agressivo, que aposta e aumenta com qualquer coisa.","rake":"Comissão que o casino ou a sala online cobra do pote pela organização do jogo.","rake-cap":"Valor máximo de rake que a sala pode cobrar numa única mão."},
  "pt-BR": {"royal-flush":"A mão mais alta do pôquer: ás, rei, dama, valete e dez do mesmo naipe, por exemplo, A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Cinco cartas em sequência do mesmo naipe, por exemplo, 5♥ 6♥ 7♥ 8♥ 9♥. A versão mais alta (do ás ao dez) tem nome próprio e é a mão mais forte do jogo.","four-of-a-kind":"Quatro cartas do mesmo valor, por exemplo, quatro setes. Entre duas quadras do mesmo valor, vence a quinta carta (o kicker) mais alta.","full-house":"Uma trinca e um par na mesma mão, por exemplo, três damas e dois cincos. Entre dois full houses, vence a trinca mais alta.","flush":"Cinco cartas do mesmo naipe (♠, ♥, ♦ ou ♣) que não estão em sequência. Entre duas mãos assim, vence a que tem a carta mais alta; se elas forem iguais, decide a carta seguinte.","straight":"Cinco cartas em sequência, nem todas do mesmo naipe, por exemplo, 5-6-7-8-9. O ás pode ser a carta mais alta (A-K-Q-J-T) ou a mais baixa (A-2-3-4-5).","three-of-a-kind":"Três cartas do mesmo valor e duas outras. No hold'em, há duas variantes com nomes próprios: set, quando o par está na sua mão e a terceira carta no board, e trips, quando o par está no board e a terceira carta na sua mão.","set":"Trinca formada por um par na sua mão e uma carta do board, por exemplo, 7♣ 7♦ num flop K-7-2.","two-pair":"Dois pares diferentes e uma quinta carta, por exemplo, K-K-8-8-3. O empate é decidido primeiro pelo par mais alto, depois pelo mais baixo e, por fim, pela quinta carta.","pair":"Duas cartas do mesmo valor e três outras, por exemplo, dois noves. Só a carta alta é mais fraca.","high-card":"Mão sem par nem combinação melhor; a força é definida pela carta mais alta e, em caso de empate, pelas seguintes.","kicker":"A carta mais alta fora da combinação, que desempata. Exemplo: um par de ases com rei vence um par de ases com dama.","wheel":"A sequência mais baixa: A-2-3-4-5, em que o ás conta como a carta mais baixa.","check":"Continuar sem colocar fichas, possível só quando você não precisa pagar nada: ninguém apostou ainda nesta rodada de apostas (antes do flop, o big blind pode fazer isso quando ninguém aumentou). Não confunda com call, que é colocar fichas para igualar a aposta do adversário.","bet":"As primeiras fichas colocadas numa rodada de apostas em que ninguém apostou ainda (em sentido mais amplo, chama-se aposta qualquer colocação de fichas no pote).","call":"Colocar no pote o valor da aposta ou do aumento do adversário para continuar jogando. Não confunda com check, que é continuar sem apostar quando ninguém apostou.","raise":"Aumentar o valor acima da aposta do adversário; os outros jogadores precisam completar a diferença, aumentar de novo ou dar fold.","fold":"Desistir da mão: você descarta as cartas e perde o que já colocou no pote.","check-raise":"Primeiro você dá check e, quando o adversário aposta, aumenta na mesma rodada de apostas.","all-in":"Apostar todas as suas fichas. Assim, de cada adversário você pode ganhar no máximo o que você mesmo colocou; o restante é disputado num pote paralelo.","pot":"Todas as fichas apostadas na mão atual. Elas vão para o jogador com a melhor mão no showdown (com potes paralelos, cada pote é decidido separadamente) ou para o jogador que sobra quando todos os outros dão fold.","side-pot":"Pote separado criado quando alguém está all-in: só disputam esse pote os jogadores que colocaram mais que o jogador all-in, por isso ele não pode ganhá-lo.","split-pot":"Situação em que jogadores com mãos iguais dividem o pote, por exemplo, quando ambos jogam a mesma sequência que está no board.","playing-the-board":"Situação em que sua melhor mão de cinco cartas é formada só pelas cartas comunitárias; suas cartas fechadas não acrescentam nada, então, na melhor das hipóteses, você divide o pote.","board":"As cartas comunitárias abertas no centro (flop, turn, river), usadas por todos os jogadores. O termo se refere às cartas, não à mesa onde se joga.","community-cards":"Cartas colocadas abertas no centro, que qualquer jogador pode usar para formar sua mão; no hold'em são cinco.","hole-cards":"As duas cartas fechadas que você recebe no início da mão no hold'em; só você as vê.","small-blind":"A aposta obrigatória menor, feita antes da distribuição pelo jogador à esquerda do button (no heads-up, pelo próprio button); esse lugar na mesa também tem esse nome.","big-blind":"A aposta obrigatória maior, feita antes da distribuição pelo segundo jogador à esquerda do button (no heads-up, pelo jogador oposto ao button); esse lugar também tem esse nome. Também serve de unidade para o tamanho dos stacks e para os resultados.","chips":"Os discos usados para jogar na mesa; nos cash games representam dinheiro e, nos torneios, pontos do torneio.","stack":"Todas as fichas que um jogador tem à sua frente; geralmente indicadas em big blinds (por exemplo, 100 big blinds).","street":"Nome informal de uma rodada de apostas: preflop, flop, turn e river são as quatro streets. Exemplo: “value em três streets” significa apostas de valor no flop, no turn e no river.","betting-round":"Etapa da mão em que os jogadores, cada um na sua vez, dão check, apostam, dão call, aumentam ou dão fold; no hold'em são quatro: preflop, flop, turn e river.","preflop":"A primeira rodada de apostas: depois que as cartas fechadas são distribuídas e antes de o flop ir para a mesa.","flop":"As três primeiras cartas comunitárias, abertas juntas após as apostas do preflop; a segunda rodada de apostas também tem esse nome.","turn":"A quarta carta comunitária e a terceira rodada de apostas.","river":"A quinta e última carta comunitária e a última rodada de apostas antes do showdown.","showdown":"A revelação das cartas depois da última rodada de apostas, quando pelo menos dois jogadores continuam na mão; a melhor mão leva o pote.","position":"Seu lugar na mesa em relação ao button, que define a ordem de ação. Quem age depois vê mais ações dos adversários antes de decidir.","in-position":"Situação do jogador que age por último depois do flop e, por isso, vê a ação do adversário antes de decidir.","out-of-position":"Situação do jogador que age antes do adversário depois do flop e, por isso, decide sem conhecer a ação dele.","early-position":"Os primeiros lugares a agir antes do flop (por exemplo, UTG); ainda há muitos jogadores para agir depois de você.","late-position":"Os lugares que agem por último: o button e os lugares logo antes dele, principalmente o cutoff.","utg":"O primeiro jogador a agir antes do flop, sentado imediatamente à esquerda do big blind.","hijack":"O lugar imediatamente antes do cutoff, ou seja, o segundo à direita do button.","cutoff":"O lugar imediatamente à direita do button, que age logo antes dele.","button":"O lugar do dealer, marcado com um disco “dealer”. Depois do flop, age por último em todas as rodadas de apostas.","outs":"Carta que ainda está no baralho e vai melhorar sua mão, geralmente completando um draw. Exemplo: com um flush draw, seus outs são as cartas restantes do seu naipe.","draw":"Mão que ainda não é forte, mas pode se tornar forte com as próximas cartas comunitárias, por exemplo, quando falta uma carta para um flush ou uma sequência.","flush-draw":"Quatro cartas do mesmo naipe (somando a mão e o board); falta uma para completar o flush.","straight-draw":"Quatro cartas às quais falta uma para formar uma sequência. Tipos: OESD (falta uma carta em uma das duas pontas) e gutshot (falta uma carta no meio).","oesd":"Sigla de open-ended straight draw: straight draw de quatro cartas em sequência, completado por uma carta em qualquer das duas pontas, por exemplo, 5-6-7-8 espera um quatro ou um nove.","gutshot":"Straight draw ao qual falta um valor específico no meio, por exemplo, 5-6-8-9 espera só um sete.","backdoor":"Draw no flop que precisa de duas cartas favoráveis seguidas, no turn e no river, por exemplo, três cartas do mesmo naipe depois do flop.","pot-odds":"A relação entre o valor que você precisa colocar e o pote que pode ganhar (incluindo a aposta do adversário). Mostra com que frequência você precisa ganhar para que o call valha a pena.","implied-odds":"Pot odds acrescidas das fichas que você espera ganhar nas streets seguintes se acertar sua mão.","equity":"Sua chance de ganhar o pote se todas as cartas restantes fossem abertas sem mais apostas; geralmente em porcentagem.","equity-realization":"Quanto da sua equity uma mão transforma em ganho quando as apostas continuam (pode realizar menos ou mais do que sua equity); depende, entre outras coisas, da posição e da facilidade de jogar a mão.","expected-value":"O resultado médio de uma jogada se ela fosse repetida muitas vezes. Uma jogada positiva na média dá lucro no longo prazo, mesmo que perca desta vez.","combo":"Uma combinação específica de duas cartas com naipes, por exemplo, A♠ K♥. Contar essas combinações mostra quantas mãos de um tipo há de fato num range.","range":"O conjunto de todas as mãos que um jogador pode ter numa situação, ou das mãos com as quais ele faria determinada jogada.","mixed-hand":"Mão com a qual a estratégia de equilíbrio escolhe ora uma jogada, ora outra (por exemplo, às vezes aumento, às vezes call); as duas jogadas são corretas. Também se diz que essa mão é jogada com estratégia mista.","open":"Entrar no pote antes do flop com um aumento quando todos antes de você deram fold.","suited":"Duas cartas fechadas do mesmo naipe, por exemplo, A♥ K♥ (notação AKs).","offsuit":"Duas cartas fechadas de naipes diferentes, por exemplo, A♥ K♣ (notação AKo).","pocket-pair":"Par formado pelas duas cartas fechadas, por exemplo, 8♣ 8♦ antes do flop.","connectors":"Cartas fechadas de valores vizinhos, por exemplo, 8-7 ou 9-8; com elas é mais fácil formar uma sequência.","3-bet":"O primeiro aumento sobre uma abertura antes do flop; o nome conta o big blind como a primeira aposta e a abertura como a segunda.","4-bet":"Um aumento sobre um 3-bet, ou seja, a quarta aposta na rodada de apostas.","limp":"Entrar no pote antes do flop apenas pagando o big blind, quando ninguém aumentou ainda.","isolation":"Aumento depois de um ou mais limps, para jogar contra o limper (muitas vezes um jogador mais fraco) no mano a mano.","texture":"As características das cartas comunitárias: quantos naipes há, se as cartas são próximas entre si, se há um par. Isso define quais mãos e draws são possíveis.","dry":"Board em que poucos draws e mãos fortes são possíveis, por exemplo, K♠ 7♦ 2♣.","wet":"Board em que muitos draws e mãos fortes são possíveis, por exemplo, J♥ T♥ 8♣.","rainbow":"Flop com três cartas de três naipes diferentes, então ninguém tem flush draw no flop.","two-tone":"Flop com duas cartas do mesmo naipe, então flush draws são possíveis.","monotone":"Flop com três cartas do mesmo naipe, então um flush pode já estar formado.","paired":"Board com um par (duas cartas do mesmo valor), por exemplo, 8-8-3.","connected":"Board em que alguém pode já ter formado uma sequência, por exemplo, 9-8-7.","disconnected":"Board com cartas distantes entre si, em que é difícil formar uma sequência ou um straight draw, por exemplo, K-7-2.","semi-connected":"Board com straight draws possíveis, mas ainda sem sequência possível, por exemplo, T-8-3 (classificação adotada neste curso).","wetness":"O quanto um board favorece draws e mãos fortes: de seco a molhado. Também se descreve como o grau de coordenação do board.","top-pair":"Par com a carta mais alta do board, por exemplo, K♠ Q♦ num flop K-7-2.","second-pair":"Par com a segunda carta mais alta do board, por exemplo, 7♠ 6♠ num flop K-7-2.","overpair":"Par de mão mais alto que todas as cartas do board, por exemplo, Q-Q num flop J-7-2.","c-bet":"Aposta de continuação: aposta do jogador que foi o agressor na rodada anterior, por exemplo, uma aposta no flop depois de abrir no preflop.","aggressor":"O jogador que apostou ou aumentou por último na rodada de apostas anterior.","initiative":"O papel do último agressor: geralmente é ele quem faz a próxima aposta.","range-advantage":"Situação em que o range de um jogador tem, no total, mais equity num determinado board do que o range do adversário.","nuts-advantage":"Situação em que um jogador tem no range, proporcionalmente, mais das mãos mais fortes do que o adversário.","nuts":"A mão mais forte possível num determinado board naquele momento. Exemplo: no board K♥ 9♥ 4♥ 2♣, é o flush com o ás de copas.","polarized":"Sobre um range: formado principalmente por mãos muito fortes e por blefes, quase sem mãos médias.","polarization":"Montar um range com os extremos: mãos fortes para valor e blefes, sem mãos médias.","linear":"Sobre um range: montado de cima para baixo, das mãos mais fortes em diante, sem um grupo separado de blefes. Você também verá o termo relacionado “merged range” (range não polarizado); segundo análises de solver publicadas, o merged é um formato intermediário entre este range e o polarizado.","condensed":"Sobre um range: sem as mãos mais fortes (limitado por cima) e formado principalmente por mãos médias; o oposto do polarizado.","value":"Apostar com uma mão forte para que o adversário pague com uma mão mais fraca.","value-bet":"Uma aposta única por valor: feita com uma mão forte para que mãos mais fracas paguem.","bluff":"Aposta com uma mão fraca, que dificilmente vence no showdown, para que o adversário dê fold com uma mão melhor.","semi-bluff":"Aposta com uma mão ainda fraca, mas com chance de melhorar (por exemplo, com um draw): você ganha se o adversário der fold ou se acertar.","blocker":"Carta na sua mão que reduz a chance de o adversário ter certas mãos. Exemplo: com o ás de copas, o adversário não pode ter o flush de copas com ás.","bluff-catcher":"Mão que vence apenas os blefes do adversário e perde para as apostas de valor dele.","barrel":"Mais uma aposta na rodada de apostas seguinte, depois da sua própria aposta na rodada anterior.","second-barrel":"Segunda aposta seguida: depois de um c-bet no flop, o jogador aposta de novo no turn.","probe-bet":"Aposta no turn do jogador fora de posição depois que o agressor do preflop deu check no flop em vez de fazer c-bet.","donk-bet":"Aposta de um jogador que aposta antes de o agressor da rodada anterior ter tido a chance de agir.","overbet":"Aposta depois do flop maior que o pote inteiro.","effective-stack":"Numa mão entre dois jogadores: o menor dos dois stacks, ou seja, o máximo que se pode realmente ganhar ou perder. Com vários jogadores, é calculado separadamente para cada par.","spr":"O stack efetivo dividido pelo pote no início de uma street (para planejar a mão, é calculado no flop); mostra quão profundos são os stacks em relação ao pote (quanto menor o SPR, mais rápido tudo vai para o pote).","mdf":"A menor parte do range que você precisa defender contra uma aposta para que o blefe do adversário com uma mão sem chances não seja automaticamente lucrativo.","alpha":"Com que frequência o adversário precisa dar fold para que um blefe com uma mão sem chances fique no zero a zero; depende do tamanho da aposta em relação ao pote.","variance":"A dispersão dos resultados em torno do valor esperado: mesmo jogando bem, sequências curtas podem ter grandes perdas ou grandes ganhos.","buy-in":"O valor de entrada num torneio ou para sentar num cash game.","bankroll":"Toda a reserva destinada exclusivamente a jogar pôquer; neste app, é contada em buy-ins, não em dinheiro.","tilt":"Estado em que as emoções (raiva, frustração, euforia) pioram suas decisões na mesa.","winrate":"O resultado médio de um jogador numa amostra maior; nos cash games, geralmente em bb/100, ou seja, big blinds por cem mãos.","downswing":"Período de resultados claramente piores, geralmente perdas maiores do que a habilidade justificaria; o oposto de um upswing.","session":"Uma sentada de pôquer, do início ao fim do jogo.","stakes":"O valor dos blinds num cash game ou do buy-in num torneio; “microlimites” são os níveis mais baixos.","standard-deviation":"Medida da dispersão dos resultados (a raiz quadrada da variância); no pôquer, geralmente em bb/100.","risk-of-ruin":"A probabilidade de você um dia perder todo o seu bankroll se continuar jogando no mesmo limite.","mental-game":"O lado psicológico do pôquer: lidar com o tilt, as emoções e a concentração na mesa.","tournament":"Formato em que os blinds sobem de tempos em tempos e o jogo continua até um jogador ficar com todas as fichas; os prêmios vão para os mais bem colocados.","push-fold":"Estratégia simplificada para short stacks: antes do flop, você ou vai all-in, ou dá fold.","shove":"Jogada all-in, geralmente como aumento antes do flop.","icm":"Modelo que converte fichas de torneio em valor em dinheiro, considerando a estrutura de premiação e os stacks de todos os jogadores.","bubble":"Fase do torneio logo antes das posições premiadas, quando ainda faltam algumas eliminações para chegar aos prêmios.","bubble-factor":"Indicador do ICM: quanto, num torneio, perder uma certa quantidade de fichas dói mais do que ganhar a mesma quantidade ajuda.","cover":"Ter pelo menos tantas fichas quanto o adversário. Quando um adversário cobre você, perder um all-in contra ele encerra seu torneio.","risk-premium":"Equity extra, além do que as pot odds exigem, necessária num torneio para arriscar um all-in, porque perder custa mais do que ganhar rende.","m-ratio":"Seu stack dividido pela soma dos blinds e dos antes de uma mão: quantas voltas completas (órbitas) suas fichas aguentam sem jogar.","red-zone":"Zona de M muito baixo: sobra principalmente ir all-in ou dar fold.","green-zone":"Zona de M alto: o stack permite jogar livremente, de forma conservadora ou agressiva.","ante":"Pequena contribuição obrigatória ao pote antes da distribuição, feita por todos os jogadores (principalmente em torneios).","bb-ante":"Formato de ante em que, em vez de todos os jogadores, o jogador no big blind paga o ante da mesa inteira.","fold-equity":"A parte do valor de uma jogada que vem da possibilidade de o adversário dar fold.","gap-concept":"O princípio de que é preciso uma mão mais forte para pagar uma abertura do que para abrir.","chip-ev":"O valor esperado de uma jogada calculado em fichas, sem convertê-las em dinheiro (sem ICM).","tournament-equity":"Sua parte esperada da premiação total, dadas a estrutura de premiação e os stacks. Também é chamada de “$EV”.","prize-pool":"O total de dinheiro a ser dividido entre os jogadores premiados de um torneio.","payout":"O prêmio por uma colocação específica no torneio; juntos, eles formam a distribuição dos prêmios.","pay-jump":"A diferença de prêmio entre colocações vizinhas num torneio; saltos grandes aumentam o prêmio de risco.","final-table":"A última mesa de um torneio, onde se disputam os maiores prêmios.","short-stack":"Stack pequeno em relação aos blinds; nos torneios, geralmente um com poucos big blinds restantes.","nash-equilibrium":"Conjunto de estratégias em que nenhum jogador ganha nada mudando apenas a própria estratégia.","overcall":"Pagar uma aposta que alguém antes de você já pagou.","heads-up":"Jogo mano a mano: só restam dois jogadores na mesa ou na mão.","dead-money":"Fichas no pote de jogadores que já não podem ganhá-lo, por exemplo, dos que deram fold.","stack-off":"Colocar o stack inteiro no pote numa única mão, ou seja, ir all-in ou pagar um all-in.","exploit":"Desvio deliberado da estratégia base para aproveitar um erro específico de um adversário ou de toda a população de jogadores.","hud":"Sobreposição na mesa do jogo online que mostra estatísticas dos adversários a partir de mãos jogadas anteriormente.","vpip":"Estatística do HUD: em que porcentagem das mãos o jogador coloca dinheiro voluntariamente no pote antes do flop (dá call ou aumenta).","pfr":"Estatística do HUD: em que porcentagem das mãos o jogador aumenta antes do flop.","wtsd":"Estatística do HUD: com que frequência um jogador que viu o flop chega ao showdown.","nit":"Jogador muito tight, que entra no pote quase só com mãos fortes.","regular":"Jogador frequente num determinado limite, que joga um grande volume de mãos; no curso, é contraposto ao jogador recreativo.","tag":"Estilo tight agressivo: poucas mãos, mas jogadas de forma agressiva (apostas e aumentos).","lag":"Estilo loose agressivo: muitas mãos, jogadas de forma agressiva.","recreational":"Jogador que joga por diversão e geralmente é mais fraco que os regulares; no jargão, de forma pejorativa, “fish”.","calling-station":"Termo pejorativo para um jogador que paga com muita frequência, mesmo com mãos fracas ou draws.","maniac":"Termo pejorativo para um jogador muito loose e agressivo, que aposta e aumenta com qualquer coisa.","rake":"A taxa que o cassino ou a sala online cobra do pote para organizar o jogo.","rake-cap":"O valor máximo de rake que a sala pode cobrar de uma única mão."},
  "vi": {"royal-flush":"Tay bài cao nhất trong poker: A, K, Q, J và 10 cùng chất, ví dụ A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Năm lá liên tiếp cùng chất, ví dụ 5♥ 6♥ 7♥ 8♥ 9♥. Dạng cao nhất (từ A xuống 10) có tên riêng và là tay bài mạnh nhất trong trò chơi.","four-of-a-kind":"Bốn lá cùng hạng, ví dụ bốn lá 7. Khi hai người có tứ quý cùng hạng, người có lá thứ năm (kicker) cao hơn thắng.","full-house":"Bộ ba và một đôi trong cùng một tay bài, ví dụ ba lá Q và hai lá 5. Giữa hai cù lũ, cù lũ có bộ ba cao hơn thắng.","flush":"Năm lá cùng chất (♠, ♥, ♦ hoặc ♣) không liên tiếp nhau. Giữa hai tay bài như vậy, tay có lá cao nhất lớn hơn thắng; nếu bằng nhau thì xét lá cao tiếp theo.","straight":"Năm lá liên tiếp, không phải cả năm cùng một chất, ví dụ 5-6-7-8-9. Lá A có thể là lá cao nhất (A-K-Q-J-T) hoặc thấp nhất (A-2-3-4-5).","three-of-a-kind":"Ba lá cùng hạng và hai lá khác. Trong hold'em có hai dạng mang tên riêng: set, khi đôi nằm trên tay và lá thứ ba trên board, và trips, khi đôi nằm trên board và lá thứ ba trên tay.","set":"Bộ ba tạo từ một đôi trên tay và một lá trên board, ví dụ 7♣ 7♦ trên flop K-7-2.","two-pair":"Hai đôi khác nhau và một lá thứ năm, ví dụ K-K-8-8-3. Khi hòa, xét đôi cao hơn trước, rồi đến đôi thấp hơn, cuối cùng là lá thứ năm.","pair":"Hai lá cùng hạng và ba lá khác, ví dụ hai lá 9. Chỉ có mậu thầu là yếu hơn.","high-card":"Tay bài không có đôi hay tổ hợp nào tốt hơn; sức mạnh do lá cao nhất quyết định, nếu hòa thì xét các lá tiếp theo.","kicker":"Lá cao nhất nằm ngoài tổ hợp bài, dùng để phân định khi hòa. Ví dụ: đôi A kèm K thắng đôi A kèm Q.","wheel":"Sảnh thấp nhất: A-2-3-4-5, trong đó A được tính là lá thấp nhất.","check":"Tiếp tục chơi mà không bỏ thêm chip, chỉ được khi bạn không phải bù thêm gì: chưa ai cược trong vòng cược này (trước flop, big blind có thể check khi không ai tố). Đừng nhầm với theo (call), tức là bỏ chip để theo cược của đối thủ.","bet":"Lần bỏ chip đầu tiên trong một vòng cược mà chưa ai cược (theo nghĩa rộng, mọi lần bỏ chip vào pot đều gọi là cược).","call":"Bỏ vào pot đúng bằng mức cược hoặc mức tố của đối thủ để tiếp tục chơi. Đừng nhầm với check, tức là tiếp tục chơi mà không cược khi chưa ai cược.","raise":"Nâng mức cược lên trên lần cược của đối thủ; những người còn lại phải bù phần chênh lệch, tố tiếp hoặc bỏ bài.","fold":"Bỏ ván bài: bạn trả bài và mất những gì đã bỏ vào pot.","check-raise":"Bạn check trước, rồi khi đối thủ cược thì bạn tố trong cùng vòng cược.","all-in":"Đặt toàn bộ chip của mình. Khi đó từ mỗi đối thủ bạn chỉ có thể thắng tối đa bằng số bạn đã bỏ vào; phần còn lại được tranh trong side pot.","pot":"Toàn bộ chip đã đặt trong ván bài hiện tại. Người có tay bài tốt nhất ở showdown nhận pot (khi có side pot thì từng pot được phân định riêng), hoặc người còn lại khi tất cả những người khác đã bỏ bài.","side-pot":"Pot riêng hình thành khi có người all-in: chỉ những người bỏ vào nhiều hơn người all-in mới tranh pot này, nên người all-in không thể thắng nó.","split-pot":"Tình huống những người có tay bài bằng nhau chia nhau pot, ví dụ khi cả hai cùng chơi một sảnh nằm sẵn trên board.","playing-the-board":"Tình huống tay bài năm lá tốt nhất của bạn chỉ gồm các lá bài chung; bài tẩy không thêm được gì, nên tốt nhất bạn chỉ chia pot.","board":"Các lá bài chung ngửa ở giữa bàn (flop, turn, river) mà mọi người chơi đều dùng. Board ở đây là các lá bài, không phải chiếc bàn bạn ngồi chơi.","community-cards":"Các lá bài được chia ngửa ở giữa bàn, mọi người chơi đều có thể dùng để tạo tay bài; trong hold'em có năm lá.","hole-cards":"Hai lá bài úp bạn nhận khi bắt đầu ván trong hold'em; chỉ mình bạn nhìn thấy chúng.","small-blind":"Khoản cược bắt buộc nhỏ hơn, do người ngồi bên trái button đặt trước khi chia bài (khi chỉ có hai người chơi thì do chính button đặt); vị trí này cũng mang tên đó.","big-blind":"Khoản cược bắt buộc lớn hơn, do người thứ hai bên trái button đặt trước khi chia bài (khi chỉ có hai người chơi thì do người đối diện button đặt); vị trí này cũng mang tên đó. Nó còn được dùng làm đơn vị đo stack và kết quả.","chips":"Những đĩa tròn nhỏ dùng để chơi tại bàn; trong cash game chúng đại diện cho tiền, trong giải đấu là điểm giải đấu.","stack":"Toàn bộ chip người chơi có trước mặt; thường tính bằng big blind (ví dụ 100 big blind).","street":"Tên gọi lóng của vòng cược: preflop, flop, turn và river là bốn street. Ví dụ: “value ba street” là các lần cược lấy giá trị ở flop, turn và river.","betting-round":"Giai đoạn của ván bài trong đó người chơi lần lượt check, cược, theo, tố hoặc bỏ bài; trong hold'em có bốn vòng: preflop, flop, turn và river.","preflop":"Vòng cược đầu tiên: sau khi chia bài tẩy, trước khi flop được lật ra.","flop":"Ba lá bài chung đầu tiên, lật cùng lúc sau vòng cược preflop; vòng cược thứ hai cũng gọi là flop.","turn":"Lá bài chung thứ tư và vòng cược thứ ba.","river":"Lá bài chung thứ năm, cũng là lá cuối cùng, và vòng cược cuối cùng trước showdown.","showdown":"Lật bài sau vòng cược cuối khi còn ít nhất hai người trong ván; tay bài tốt nhất nhận pot.","position":"Chỗ ngồi tại bàn so với button, quyết định thứ tự hành động. Ai hành động sau thì thấy được nhiều hành động của đối thủ hơn trước khi quyết định.","in-position":"Tình huống của người chơi hành động cuối cùng sau flop, nên thấy hành động của đối thủ trước khi quyết định.","out-of-position":"Tình huống của người chơi hành động trước đối thủ sau flop, nên phải quyết định mà chưa biết đối thủ sẽ làm gì.","early-position":"Các vị trí hành động đầu tiên trước flop (ví dụ UTG); phía sau bạn còn nhiều người chơi.","late-position":"Các vị trí hành động cuối cùng: button và các vị trí ngay trước nó, nhất là cutoff.","utg":"Người hành động đầu tiên trước flop, ngồi ngay bên trái big blind.","hijack":"Vị trí ngay trước cutoff, tức là vị trí thứ hai bên phải button.","cutoff":"Vị trí ngay bên phải button, hành động ngay trước button.","button":"Vị trí của người chia bài, được đánh dấu bằng nút tròn “dealer”. Sau flop, vị trí này hành động cuối cùng trong mọi vòng cược.","outs":"Lá bài còn trong bộ bài sẽ cải thiện tay bài của bạn, thường là hoàn thành một bài chờ. Ví dụ: với bài chờ thùng, out là những lá còn lại cùng chất với bạn.","draw":"Tay bài chưa phải tổ hợp mạnh nhưng có thể thành tổ hợp mạnh với các lá bài chung tiếp theo, ví dụ khi còn thiếu một lá để có thùng hoặc sảnh.","flush-draw":"Bốn lá cùng chất (tính chung trên tay và trên board); còn thiếu một lá để có thùng.","straight-draw":"Bốn lá còn thiếu một lá để thành sảnh. Các dạng: OESD (thiếu một lá ở một trong hai đầu) và gutshot (thiếu một lá ở giữa).","oesd":"Viết tắt của open-ended straight draw: bài chờ sảnh gồm bốn lá liên tiếp, được hoàn thành bởi lá ở một trong hai đầu, ví dụ 5-6-7-8 chờ lá 4 hoặc lá 9.","gutshot":"Bài chờ sảnh thiếu đúng một hạng cụ thể ở giữa, ví dụ 5-6-8-9 chỉ chờ lá 7.","backdoor":"Bài chờ ở flop cần hai lá phù hợp liên tiếp, ở turn và ở river, ví dụ ba lá cùng chất sau flop.","pot-odds":"Tỷ lệ giữa số chip bạn phải bỏ thêm và pot bạn có thể thắng (tính cả lần cược của đối thủ). Nó cho biết bạn cần thắng thường xuyên đến mức nào để việc theo có lời.","implied-odds":"Pot odds cộng thêm số chip bạn dự kiến thắng ở các street sau nếu bạn ra được tay bài của mình.","equity":"Cơ hội thắng pot của bạn nếu tất cả các lá còn lại được chia ra mà không cược thêm; thường tính bằng phần trăm.","equity-realization":"Mức độ một tay bài biến equity của nó thành tiền thắng khi việc cược còn tiếp diễn (có thể hiện thực hóa ít hơn hoặc nhiều hơn equity của nó); phụ thuộc vào vị trí, độ dễ chơi của tay bài và các yếu tố khác.","expected-value":"Kết quả trung bình của một nước đi nếu lặp lại nó nhiều lần. Nước đi có lời trung bình sẽ kiếm tiền về lâu dài, kể cả khi lần này thua.","combo":"Một tổ hợp cụ thể của hai lá bài kèm chất, ví dụ A♠ K♥. Đếm các tổ hợp này cho thấy thực sự có bao nhiêu tay bài nhất định trong range.","range":"Tập hợp tất cả các tay bài mà người chơi có thể có trong một tình huống, hoặc các tay bài mà họ sẽ dùng để thực hiện một nước đi nhất định.","mixed-hand":"Tay bài mà chiến lược cân bằng lúc chọn nước đi này, lúc chọn nước đi khác (ví dụ lúc tố, lúc theo); cả hai nước đi đều đúng. Người ta cũng nói tay bài đó được chơi bằng chiến lược hỗn hợp.","open":"Vào pot trước flop bằng một lần tố khi tất cả những người trước bạn đã bỏ bài.","suited":"Hai lá bài tẩy cùng chất, ví dụ A♥ K♥ (ký hiệu AKs).","offsuit":"Hai lá bài tẩy khác chất, ví dụ A♥ K♣ (ký hiệu AKo).","pocket-pair":"Đôi tạo từ hai lá bài tẩy, ví dụ 8♣ 8♦ trước flop.","connectors":"Bài tẩy có hai hạng liền kề, ví dụ 8-7 hoặc 9-8; dễ tạo sảnh hơn.","3-bet":"Lần tố đầu tiên lên trên một lần mở cược trước flop; tên gọi tính big blind là lần cược thứ nhất và lần mở cược là lần thứ hai.","4-bet":"Tố lên trên một 3-bet, tức là lần cược thứ tư trong vòng cược.","limp":"Vào pot trước flop chỉ bằng cách theo big blind khi chưa ai tố.","isolation":"Tố sau một hoặc vài lần limp, để chơi tay đôi với người limp (thường là người chơi yếu hơn).","texture":"Đặc điểm của các lá bài chung: có bao nhiêu chất, các lá có gần nhau không, có đôi không. Điều này quyết định những tay bài và bài chờ nào có thể xảy ra.","dry":"Board trên đó có thể có ít bài chờ và ít tay bài mạnh, ví dụ K♠ 7♦ 2♣.","wet":"Board trên đó có thể có nhiều bài chờ và tay bài mạnh, ví dụ J♥ T♥ 8♣.","rainbow":"Flop có ba lá thuộc ba chất khác nhau, nên ở flop không ai có bài chờ thùng.","two-tone":"Flop có hai lá cùng chất, nên có thể có bài chờ thùng.","monotone":"Flop có ba lá cùng chất, nên thùng có thể đã thành.","paired":"Board có một đôi (hai lá cùng hạng), ví dụ 8-8-3.","connected":"Board mà trên đó ai đó có thể đã có sảnh, ví dụ 9-8-7.","disconnected":"Board có các lá cách xa nhau, khó tạo sảnh hoặc bài chờ sảnh, ví dụ K-7-2.","semi-connected":"Board có bài chờ sảnh nhưng chưa thể có sảnh, ví dụ T-8-3 (cách phân loại dùng trong khóa học).","wetness":"Mức độ board thuận lợi cho bài chờ và tay bài mạnh: từ khô đến ướt. Người ta cũng mô tả nó là mức độ phối hợp của board.","top-pair":"Đôi với lá cao nhất trên board, ví dụ K♠ Q♦ trên flop K-7-2.","second-pair":"Đôi với lá cao thứ hai trên board, ví dụ 7♠ 6♠ trên flop K-7-2.","overpair":"Pocket pair cao hơn mọi lá trên board, ví dụ Q-Q trên flop J-7-2.","c-bet":"Continuation bet (cược tiếp tục): lần cược của người chơi là người tấn công ở vòng trước, ví dụ cược ở flop sau khi mở cược preflop.","aggressor":"Người chơi cược hoặc tố sau cùng ở vòng cược trước.","initiative":"Vai trò của người tấn công sau cùng: người này thường là người thực hiện lần cược tiếp theo.","range-advantage":"Tình huống range của một người chơi có tổng equity trên board đó lớn hơn range của đối thủ.","nuts-advantage":"Tình huống một người chơi có tỷ lệ tay bài mạnh nhất trong range nhiều hơn đối thủ.","nuts":"Tay bài mạnh nhất có thể có trên một board tại một thời điểm. Ví dụ: trên board K♥ 9♥ 4♥ 2♣, đó là thùng có A cơ.","polarized":"Nói về range: chủ yếu gồm các tay bài rất mạnh và bluff, gần như không có tay bài trung bình.","polarization":"Xây dựng range từ hai thái cực: tay bài mạnh để lấy giá trị và bluff, không có tay bài trung bình.","linear":"Nói về range: xây từ trên xuống, từ các tay bài mạnh nhất trở xuống, không có nhóm bluff riêng. Bạn cũng sẽ gặp thuật ngữ liên quan “merged range” (range không phân cực); theo các phân tích solver đã công bố, merged là dạng trung gian giữa range này và range phân cực.","condensed":"Nói về range: không có các tay bài mạnh nhất (bị giới hạn phía trên) và chủ yếu gồm tay bài trung bình; ngược lại với range phân cực.","value":"Cược với tay bài mạnh để đối thủ theo bằng tay bài yếu hơn.","value-bet":"Một lần cược để lấy giá trị: đặt với tay bài mạnh để các tay bài yếu hơn theo.","bluff":"Cược với tay bài yếu khó thắng ở showdown, nhằm khiến đối thủ bỏ tay bài tốt hơn.","semi-bluff":"Cược với tay bài còn yếu nhưng có cơ hội cải thiện (ví dụ có bài chờ): bạn thắng nếu đối thủ bỏ bài hoặc nếu bạn ra bài.","blocker":"Lá bài trên tay bạn làm giảm khả năng đối thủ có một số tay bài nhất định. Ví dụ: khi bạn cầm A cơ, đối thủ không thể có thùng cơ với A.","bluff-catcher":"Tay bài chỉ thắng được bluff của đối thủ, còn thua các lần cược lấy giá trị của họ.","barrel":"Thêm một lần cược ở vòng cược kế tiếp sau lần cược của chính bạn ở vòng trước.","second-barrel":"Lần cược thứ hai liên tiếp: sau c-bet ở flop, người chơi cược tiếp ở turn.","probe-bet":"Lần cược ở turn của người chơi không có vị trí sau khi người tấn công preflop check ở flop thay vì c-bet.","donk-bet":"Lần cược của người chơi đặt cược trước khi người tấn công của vòng trước kịp hành động.","overbet":"Lần cược sau flop lớn hơn toàn bộ pot.","effective-stack":"Trong ván giữa hai người: stack nhỏ hơn trong hai stack, tức là mức tối đa thực tế có thể thắng hoặc thua. Khi có nhiều người chơi, nó được tính riêng cho từng cặp.","spr":"Stack hiệu dụng chia cho pot ở đầu một street (để lên kế hoạch cho ván bài, người ta tính ở flop); cho biết stack sâu đến mức nào so với pot (SPR càng thấp, mọi thứ càng nhanh vào pot).","mdf":"Phần nhỏ nhất của range phải phòng thủ trước một lần cược để bluff của đối thủ bằng tay bài không có cơ hội không tự động có lời.","alpha":"Tần suất đối thủ phải bỏ bài để bluff bằng tay bài không có cơ hội hòa vốn; phụ thuộc vào kích thước lần cược so với pot.","variance":"Độ phân tán kết quả quanh giá trị kỳ vọng: ngay cả khi chơi tốt, các chuỗi ngắn vẫn có thể lỗ nặng hoặc lãi lớn.","buy-in":"Số tiền để tham gia một giải đấu hoặc ngồi vào bàn cash game.","bankroll":"Toàn bộ khoản dự trữ dành riêng để chơi poker; trong ứng dụng này được tính bằng số buy-in, không phải bằng tiền.","tilt":"Trạng thái trong đó cảm xúc (giận dữ, bực bội, hưng phấn) làm các quyết định của bạn tại bàn tệ đi.","winrate":"Kết quả trung bình của người chơi trên một mẫu dài; trong cash game thường tính bằng bb/100, tức là số big blind trên một trăm ván.","downswing":"Giai đoạn kết quả kém rõ rệt, thường là thua lỗ nhiều hơn so với trình độ; ngược lại với upswing.","session":"Một lần ngồi chơi poker, từ khi bắt đầu đến khi kết thúc.","stakes":"Mức blind trong cash game hoặc mức buy-in trong giải đấu; “micro stakes” là các mức thấp nhất.","standard-deviation":"Thước đo độ phân tán kết quả (căn bậc hai của phương sai); trong poker thường tính bằng bb/100.","risk-of-ruin":"Xác suất bạn sẽ có lúc mất toàn bộ bankroll nếu tiếp tục chơi ở cùng mức cược.","mental-game":"Khía cạnh tâm lý của poker: đối phó với tilt, cảm xúc và sự tập trung tại bàn.","tournament":"Hình thức chơi trong đó blind tăng sau mỗi khoảng thời gian và trò chơi tiếp tục đến khi một người có toàn bộ chip; giải thưởng dành cho những người xếp hạng cao nhất.","push-fold":"Chiến lược đơn giản hóa cho short stack: trước flop chỉ chọn all-in hoặc bỏ bài.","shove":"Nước all-in, thường là một lần tố trước flop.","icm":"Mô hình quy đổi chip giải đấu thành giá trị tiền, có tính đến cơ cấu trả thưởng và stack của mọi người chơi.","bubble":"Giai đoạn của giải đấu ngay trước các vị trí có thưởng, khi còn vài người nữa phải bị loại thì mới có người vào vùng nhận thưởng.","bubble-factor":"Chỉ số từ ICM: trong giải đấu, thua một lượng chip đau hơn bao nhiêu so với lợi ích khi thắng cùng lượng chip đó.","cover":"Có ít nhất bằng số chip của đối thủ. Khi đối thủ cover bạn, thua họ một ván all-in sẽ kết thúc giải đấu của bạn.","risk-premium":"Phần equity cần thêm ngoài mức pot odds yêu cầu để mạo hiểm all-in trong giải đấu, vì thua mất nhiều hơn so với thắng được.","m-ratio":"Stack chia cho tổng blind và ante trong một ván: số vòng bàn trọn vẹn (orbit) mà chip của bạn đủ trụ nếu không chơi.","red-zone":"Vùng M rất thấp: chủ yếu chỉ còn all-in hoặc bỏ bài.","green-zone":"Vùng M cao: stack cho phép bạn chơi thoải mái, thận trọng hoặc hung hăng.","ante":"Khoản bắt buộc nhỏ mà mọi người chơi bỏ vào pot trước khi chia bài (chủ yếu trong giải đấu).","bb-ante":"Hình thức ante trong đó, thay vì mọi người chơi, người ở big blind trả ante cho cả bàn.","fold-equity":"Phần giá trị của một nước đi đến từ khả năng đối thủ bỏ bài.","gap-concept":"Nguyên tắc rằng để theo một lần mở cược cần tay bài mạnh hơn so với tự mình mở cược.","chip-ev":"Giá trị kỳ vọng của một nước đi tính bằng chip, không quy đổi ra tiền (không dùng ICM).","tournament-equity":"Phần kỳ vọng của bạn trong tổng giải thưởng, với cơ cấu trả thưởng và các stack hiện có. Nó còn được gọi là “$EV”.","prize-pool":"Tổng số tiền được chia cho những người chơi đạt giải trong giải đấu.","payout":"Giải thưởng cho một thứ hạng cụ thể trong giải đấu; tất cả cộng lại tạo thành cơ cấu phân chia giải thưởng.","pay-jump":"Chênh lệch tiền thưởng giữa hai thứ hạng liền kề trong giải đấu; bước nhảy lớn làm tăng risk premium.","final-table":"Bàn cuối cùng của giải đấu, nơi tranh các giải thưởng cao nhất.","short-stack":"Stack nhỏ so với blind; trong giải đấu thường là khi chỉ còn ít big blind.","nash-equilibrium":"Một bộ chiến lược trong đó không người chơi nào có lợi hơn khi chỉ tự thay đổi chiến lược của mình.","overcall":"Theo một lần cược mà người trước bạn đã theo.","heads-up":"Chơi tay đôi: tại bàn hoặc trong ván chỉ còn hai người chơi.","dead-money":"Chip trong pot của những người chơi không còn khả năng thắng pot, ví dụ những người đã bỏ bài.","stack-off":"Bỏ toàn bộ stack vào pot trong một ván, tức là all-in hoặc theo all-in.","exploit":"Cố ý rời khỏi chiến lược nền tảng để tận dụng một lỗi cụ thể của đối thủ hoặc của cả nhóm người chơi.","hud":"Lớp hiển thị trên bàn chơi online, cho thấy số liệu thống kê về đối thủ từ các ván đã chơi trước đó.","vpip":"Chỉ số HUD: tỷ lệ phần trăm số ván mà người chơi tự nguyện bỏ tiền vào pot trước flop (theo hoặc tố).","pfr":"Chỉ số HUD: tỷ lệ phần trăm số ván mà người chơi tố trước flop.","wtsd":"Chỉ số HUD: người chơi đã xem flop đi đến showdown thường xuyên đến mức nào.","nit":"Người chơi rất chặt, gần như chỉ vào pot với tay bài mạnh.","regular":"Người chơi thường xuyên ở một mức cược, chơi rất nhiều ván; trong khóa học được đặt đối lập với người chơi giải trí.","tag":"Lối chơi chặt và hung hăng: ít tay bài nhưng chơi hung hăng (cược và tố).","lag":"Lối chơi lỏng và hung hăng: nhiều tay bài, chơi hung hăng.","recreational":"Người chơi để giải trí, thường yếu hơn những người chơi thường xuyên; trong tiếng lóng bị gọi một cách miệt thị là “fish”.","calling-station":"Cách gọi miệt thị người chơi theo rất thường xuyên, kể cả với tay bài yếu hoặc bài chờ.","maniac":"Cách gọi miệt thị người chơi rất lỏng và hung hăng, cược và tố với bất cứ bài gì.","rake":"Phí mà sòng bài hoặc phòng chơi online thu từ pot để tổ chức trò chơi.","rake-cap":"Mức rake tối đa mà phòng chơi có thể thu từ một ván."},
  "zh-Hant": {"royal-flush":"撲克中最大的牌型：同一花色的 A、K、Q、J、10，例如 A♠ K♠ Q♠ J♠ T♠。","straight-flush":"同一花色的五張連續牌，例如 5♥ 6♥ 7♥ 8♥ 9♥。其中最大的一種（A 到 10）有自己的名稱，是遊戲中最強的牌型。","four-of-a-kind":"四張點數相同的牌，例如四張 7。若兩手四條點數相同，第五張牌（踢腳）較大者獲勝。","full-house":"同一手牌中有三條加一對，例如三張 Q 和兩張 5。兩手葫蘆相比時，三條較大者獲勝。","flush":"五張同花色（♠、♥、♦ 或 ♣）但不連續的牌。兩手同花相比時，最大的牌較大者獲勝；若相同，則比下一張。","straight":"五張連續的牌，但不全是同一花色，例如 5-6-7-8-9。A 可以當最大的牌（A-K-Q-J-T），也可以當最小的牌（A-2-3-4-5）。","three-of-a-kind":"三張點數相同的牌加另外兩張牌。在德州撲克中分成兩種，各有名稱：暗三條（對子在手上，第三張在牌面上）和明三條（對子在牌面上，第三張在手上）。","set":"由手上的一對加牌面上一張牌組成的三條，例如在 K-7-2 的翻牌拿著 7♣ 7♦。","two-pair":"兩個不同的對子加第五張牌，例如 K-K-8-8-3。平手時先比較大的對子，再比較小的對子，最後比第五張牌。","pair":"兩張點數相同的牌加另外三張牌，例如兩張 9。只有高牌比它弱。","high-card":"沒有對子或更好組合的牌；強弱由最大的牌決定，平手時再依序比下一張。","kicker":"牌型以外最大的一張牌，用來分出平手。例如：一對 A 帶 K，贏一對 A 帶 Q。","wheel":"最小的順子：A-2-3-4-5，其中 A 當作最小的牌。","check":"不投入籌碼繼續玩，只有在你不需要補任何籌碼時才能這麼做：這個下注輪還沒有人下注（翻牌前，若沒人加注，大盲可以過牌）。不要和跟注搞混：跟注是補上對手的下注。","bet":"在還沒有人下注的下注輪中第一個投入籌碼（廣義來說，任何投入底池的籌碼都可以叫下注）。","call":"投入與對手下注或加注相同的金額到底池，以便繼續玩。不要和過牌搞混：過牌是在沒人下注時不下注繼續玩。","raise":"把金額提高到對手的下注之上；其他玩家必須補上差額、再加注或棄牌。中文也稱「加碼」。","fold":"放棄這手牌：你交出手牌，並失去已經投入底池的籌碼。","check-raise":"你先過牌，等對手下注後，在同一個下注輪中對他加注。","all-in":"投入你所有的籌碼。這時你從每位對手身上最多只能贏到你自己投入的數量；其餘部分在邊池中另行爭奪。","pot":"目前這手牌中所有下注的籌碼。由攤牌時牌型最好的玩家拿走（有邊池時每個底池分開決定），或由其他人都棄牌後剩下的玩家拿走。","side-pot":"有人全下時形成的另一個底池：只有投入比全下玩家更多的玩家能爭奪它，所以全下玩家本人無法贏得它。","split-pot":"牌型相同的玩家平分底池的情況，例如雙方都用牌面上的同一個順子。","playing-the-board":"你最好的五張牌型完全由公共牌組成的情況；你的底牌沒有任何幫助，所以最好的結果是平分底池。","board":"中間翻開的公共牌（翻牌、轉牌、河牌），所有玩家都可以使用。這裡指的是牌，不是你坐的牌桌。","community-cards":"翻開放在中間、每位玩家都能用來組成牌型的牌；德州撲克中共有五張。","hole-cards":"德州撲克中每手牌開始時你拿到的兩張蓋著的牌；只有你看得到。","small-blind":"發牌前由按鈕位左邊玩家投入的較小強制下注（兩人對局時由按鈕位本人投入）；這個座位也叫這個名稱。","big-blind":"發牌前由按鈕位左邊第二位玩家投入的較大強制下注（兩人對局時由按鈕位對面的玩家投入）；這個座位也叫這個名稱。它也被當作籌碼量和成績的單位。","chips":"在牌桌上用來玩牌的圓片；現金桌中代表金錢，錦標賽中代表比賽積分。","stack":"玩家面前所有的籌碼；通常以大盲數表示（例如 100 個大盲）。","street":"下注輪的行話稱呼：翻牌前、翻牌、轉牌和河牌是四條街。例如：「三條街拿價值」指在翻牌、轉牌和河牌都做價值下注。","betting-round":"一手牌中玩家輪流過牌、下注、跟注、加注或棄牌的階段；德州撲克有四個：翻牌前、翻牌、轉牌和河牌。","preflop":"第一個下注輪：發完底牌之後，翻牌出現之前。","flop":"翻牌前下注結束後一次發出的前三張公共牌；第二個下注輪也叫這個名稱。","turn":"第四張公共牌，也是第三個下注輪。","river":"第五張、也是最後一張公共牌，以及攤牌前的最後一個下注輪。","showdown":"最後一輪下注後，至少還有兩位玩家在局中時亮出手牌；牌型最好的人拿走底池。","position":"你在牌桌上相對於按鈕位的座位，決定行動順序。越晚行動的人，在做決定前能看到越多對手的動作。","in-position":"翻牌後最後行動的玩家所處的情況，所以他在決定前能看到對手的動作。","out-of-position":"翻牌後比對手先行動的玩家所處的情況，所以他必須在不知道對手動作的情況下做決定。","early-position":"翻牌前最先行動的座位（例如 UTG）；你後面還有很多玩家要行動。","late-position":"最後行動的座位：按鈕位以及緊鄰它之前的座位，尤其是 CO。","utg":"翻牌前第一個行動的玩家，坐在大盲的正左邊。","hijack":"緊鄰 CO 之前的座位，也就是按鈕位右邊第二個座位。","cutoff":"按鈕位正右邊的座位，緊接在按鈕位之前行動。","button":"發牌者的座位，用寫著「dealer」的圓片標示。翻牌後，它在每個下注輪都最後行動。","outs":"還在牌堆中、能改進你手牌的牌，通常是能完成聽牌的牌。例如：同花聽牌時，你的補牌就是剩下的同花色牌。","draw":"還不是強牌型、但之後的公共牌可能讓它變成強牌型的手牌，例如還差一張就成同花或順子。","flush-draw":"四張同花色的牌（手牌和牌面合計）；再一張就成同花。","straight-draw":"還差一張就成順子的四張牌。種類：兩頭順（缺的牌在兩端任一端）和卡順（缺的牌在中間）。","oesd":"兩頭順，英文 open-ended straight draw（縮寫 OESD）：由四張連續牌組成的順子聽牌，兩端的牌都能完成，例如 5-6-7-8 等 4 或 9。","gutshot":"中間缺一個特定點數的順子聽牌，例如 5-6-8-9 只等 7。","backdoor":"翻牌時需要轉牌和河牌連續兩張都中的聽牌，例如翻牌後有三張同花色的牌。","pot-odds":"你需要投入的金額與你可以贏得的底池（包含對手的下注）之間的比例。它告訴你需要多常贏，跟注才有利可圖。","implied-odds":"底池賠率加上你成牌後預期在後面幾條街能贏到的籌碼。","equity":"如果剩下的牌全部發完、不再下注，你贏得底池的機率；通常以百分比表示。","equity-realization":"下注繼續進行時，一手牌能把多少權益轉成實際贏得的籌碼（可能少於或多於它的權益）；取決於位置以及這手牌好不好打等因素。","expected-value":"某個打法重複很多次後的平均結果。平均為正的打法長期會賺錢，即使這一次輸了。","combo":"一種特定、含花色的兩張牌組合，例如 A♠ K♥。計算這些組合可以看出某種手牌在範圍中實際有多少種。","range":"玩家在某個情況下可能持有的所有手牌，或他會用來採取某個打法的手牌。","mixed-hand":"均衡策略有時選一種打法、有時選另一種打法的手牌（例如有時加注、有時跟注）；兩種打法都正確。也可以說這手牌是用混合策略來打。","open":"前面的人都棄牌時，你在翻牌前以加注第一個進入底池。","suited":"兩張底牌同一花色，例如 A♥ K♥（寫作 AKs）。","offsuit":"兩張底牌花色不同，例如 A♥ K♣（寫作 AKo）。","pocket-pair":"由兩張底牌組成的對子，例如翻牌前的 8♣ 8♦。","connectors":"點數相鄰的底牌，例如 8-7 或 9-8；比較容易組成順子。","3-bet":"翻牌前對開池的第一次加注；這個名稱把大盲算作第一注，開池算作第二注。","4-bet":"對 3-bet 的加注，也就是一個下注輪中的第四注。","limp":"還沒有人加注時，翻牌前只跟注大盲進入底池。","isolation":"在一個或多個溜入之後加注，目的是和溜入者（通常是較弱的玩家）單挑。","texture":"公共牌的特性：有幾種花色、牌之間是否接近、是否有對子。它決定了哪些牌型和聽牌是可能的。","dry":"可能的聽牌和強牌型很少的牌面，例如 K♠ 7♦ 2♣。","wet":"可能的聽牌和強牌型很多的牌面，例如 J♥ T♥ 8♣。","rainbow":"三張牌分屬三種不同花色的翻牌，所以翻牌時沒有人有同花聽牌。","two-tone":"有兩張牌同花色的翻牌，所以可能有同花聽牌。","monotone":"三張牌都同花色的翻牌，所以可能已經有人成同花。","paired":"有對子（兩張點數相同的牌）的牌面，例如 8-8-3。","connected":"可能已經有人組成順子的牌面，例如 9-8-7。","disconnected":"牌與牌距離很遠、很難組成順子或順子聽牌的牌面，例如 K-7-2。","semi-connected":"有順子聽牌、但還不可能組成順子的牌面，例如 T-8-3（本課程採用的分類）。","wetness":"牌面有利於聽牌和強牌型的程度：從乾燥到濕潤。也可以用牌面的協調程度來描述。","top-pair":"用牌面上最大的牌組成的對子，例如在 K-7-2 的翻牌拿著 K♠ Q♦。","second-pair":"用牌面上第二大的牌組成的對子，例如在 K-7-2 的翻牌拿著 7♠ 6♠。","overpair":"比牌面上每一張牌都大的口袋對，例如在 J-7-2 的翻牌拿著 Q-Q。","c-bet":"持續下注：上一輪身為進攻者的玩家所做的下注，例如翻牌前開池後在翻牌下注。","aggressor":"在上一個下注輪中最後下注或加注的玩家。","initiative":"最後進攻者的角色：通常由他做下一次下注。","range-advantage":"在某個牌面上，一位玩家的範圍整體權益高於對手範圍的情況。","nuts-advantage":"一位玩家範圍中最強手牌的比例高於對手的情況。","nuts":"在某個牌面、某個時刻可能的最強手牌。例如：牌面 K♥ 9♥ 4♥ 2♣ 時，堅果牌是帶紅心 A 的同花。","polarized":"形容範圍：主要由非常強的牌和詐唬組成，幾乎沒有中等牌。","polarization":"用兩個極端建構範圍：拿價值的強牌和詐唬，沒有中等牌。","linear":"形容範圍：從最強的牌往下建構，沒有單獨的一組詐唬。你也會看到相關的說法「merged range」（非極化範圍）；根據已發表的求解器分析，merged 是介於這種範圍和極化範圍之間的形態。","condensed":"形容範圍：沒有最強的牌（上限受限），主要由中等牌組成；與極化相反。","value":"用強牌下注，讓對手用較弱的牌跟注。","value-bet":"單次的價值下注：用強牌下注，讓較弱的牌跟注。","bluff":"用在攤牌時不太可能贏的弱牌下注，讓對手棄掉更好的牌。","semi-bluff":"用目前仍弱、但有機會改進的牌下注（例如聽牌）：對手棄牌或你中牌，你都能贏。","blocker":"你手上的一張牌，能降低對手持有某些手牌的機率。例如：你拿著紅心 A，對手就不可能有帶紅心 A 的同花。","bluff-catcher":"只能贏對手的詐唬、會輸給他價值下注的手牌。","barrel":"在上一輪自己下注之後，下一個下注輪再次下注。","second-barrel":"連續第二次下注：在翻牌持續下注後，玩家在轉牌再次下注。","probe-bet":"翻牌前進攻者在翻牌過牌、沒有持續下注後，無位置玩家在轉牌的下注。","donk-bet":"在上一輪的進攻者還沒來得及行動前，就先下注的玩家所做的下注。","overbet":"翻牌後大於整個底池的下注。","effective-stack":"兩位玩家的牌局中：兩人籌碼量中較小的那一個，也就是實際上最多能贏或輸的數量。多位玩家時，每兩人分別計算。","spr":"有效籌碼除以某條街開始時的底池（規劃整手牌時以翻牌來計算）；表示籌碼量相對於底池有多深（SPR 越低，所有籌碼越快進入底池）。","mdf":"面對下注時必須防守的最小範圍比例，讓對手用毫無勝算的牌詐唬時不會自動獲利。","alpha":"對手要多常棄牌，用毫無勝算的牌詐唬才能打平；取決於下注大小相對於底池的比例。","variance":"結果圍繞期望值的波動程度：即使打得好，短期內也可能大輸或大贏。","buy-in":"參加錦標賽或在現金桌入座的金額。","bankroll":"專門留給打撲克的全部資金；在這個 App 中以買入數計算，而不是金額。","tilt":"情緒（憤怒、挫折、狂喜）讓你在牌桌上的決定變差的狀態。","winrate":"玩家在較長樣本中的平均成績；現金桌通常以 bb/100 表示，也就是每一百手牌贏多少大盲。","downswing":"成績明顯變差的時期，通常虧損比實力應有的更大；與上風期相反。","session":"一次打撲克，從開始玩到停止。","stakes":"現金桌的盲注大小或錦標賽的買入金額；「微級別」是最低的級別。","standard-deviation":"衡量結果波動的指標（變異數的平方根）；撲克中通常以 bb/100 表示。","risk-of-ruin":"如果你繼續在同一級別打下去，最終輸光全部資金的機率。","mental-game":"撲克的心理層面：處理上頭、情緒和牌桌上的專注力。","tournament":"盲注每隔一段時間上升、一直打到一位玩家拿到所有籌碼為止的賽制；名次最高的玩家獲得獎金。","push-fold":"給短籌碼用的簡化策略：翻牌前只選擇全下或棄牌。","shove":"全下的打法，通常是翻牌前的加注。","icm":"把錦標賽籌碼換算成金錢價值的模型，考慮獎金結構和所有玩家的籌碼量。","bubble":"錦標賽中剛好在獎金圈之前的階段，還要再淘汰幾位玩家才有人進入獎金圈。","bubble-factor":"ICM 的指標：在錦標賽中，輸掉一定數量的籌碼帶來的傷害，比贏得同樣數量的籌碼帶來的好處大多少。","cover":"擁有至少和對手一樣多的籌碼。當對手覆蓋你時，全下輸給他就會讓你出局。","risk-premium":"在錦標賽中冒全下風險時，超出底池賠率要求所需的額外權益，因為輸的代價比贏的收益更大。","m-ratio":"你的籌碼量除以一手牌中盲注和前注的總和：不玩牌的話，你的籌碼能撐幾整圈。","red-zone":"M 值非常低的區域：主要只剩全下或棄牌。","green-zone":"M 值高的區域：籌碼量讓你可以自由地打，保守或積極都可以。","ante":"發牌前每位玩家投入底池的小額強制下注（主要在錦標賽）。","bb-ante":"一種前注形式：不是每位玩家都付，而是由大盲位玩家替全桌支付前注。","fold-equity":"打法價值中，來自對手可能棄牌的那一部分。","gap-concept":"原則：跟注別人的開池需要比自己開池更強的牌。","chip-ev":"以籌碼計算的打法期望值，不換算成金錢（不考慮 ICM）。","tournament-equity":"在既定獎金結構和籌碼量下，你預期能分到的獎金池份額。也稱為「$EV」。","prize-pool":"錦標賽中要分給獲獎玩家的總金額。","payout":"錦標賽中某個名次的獎金；全部加起來構成獎金分配。","pay-jump":"錦標賽中相鄰名次之間的獎金差距；大的獎金跳躍會提高風險溢價。","final-table":"錦標賽的最後一桌，爭奪最高額的獎金。","short-stack":"相對於盲注很少的籌碼量；在錦標賽中通常指只剩不多大盲的籌碼量。","nash-equilibrium":"一組策略，在其中任何玩家只改變自己的策略都無法獲利。","overcall":"跟注一個前面已經有人跟注的下注。","heads-up":"一對一對戰：牌桌上或這手牌中只剩兩位玩家。","dead-money":"底池中來自已經不可能贏得它的玩家的籌碼，例如已棄牌的玩家。","stack-off":"在一手牌中把全部籌碼投入底池，也就是全下或跟注全下。","exploit":"刻意偏離基礎策略，以利用某位對手或整個玩家群體的特定錯誤。","hud":"線上遊戲中疊在牌桌上的介面，顯示對手在先前牌局中的統計數據。","vpip":"HUD 統計數據：玩家在翻牌前自願把錢投入底池（跟注或加注）的手牌比例。","pfr":"HUD 統計數據：玩家在翻牌前加注的手牌比例。","wtsd":"HUD 統計數據：看到翻牌的玩家走到攤牌的頻率。","nit":"非常緊的玩家，幾乎只用強牌進入底池。","regular":"某個級別的固定玩家，打很多手牌；本課程中與娛樂玩家相對。","tag":"緊兇風格：玩的牌少，但打得積極（下注和加注）。","lag":"鬆兇風格：玩的牌多，打得積極。","recreational":"為了娛樂而打牌的玩家，通常比常規玩家弱；行話中貶稱為「魚」。","calling-station":"貶義說法，指非常常跟注的玩家，連弱牌或聽牌也跟。","maniac":"貶義說法，指非常鬆又兇、拿什麼牌都下注和加注的玩家。","rake":"賭場或線上撲克室為了經營牌局，從底池中抽取的費用。","rake-cap":"撲克室從單手牌中最多能抽取的抽水金額。"},
};

